{
  "fields": {
    "name": "service-dns-test",
    "action_type": "SHELL",
    "code": "echo \"Resolving {{input.hostname}} via {{input.dns_server}}...\" && RESULT=$(dig +short +time={{input.timeout}} @{{input.dns_server}} {{input.hostname}} {{input.record_type}} 2>&1) && if [ -z \"$RESULT\" ]; then echo \"FAILED: DNS resolution returned no results for {{input.hostname}} ({{input.record_type}})\" >&2; exit 1; else echo \"OK: {{input.hostname}} ({{input.record_type}}) resolved to:\"; echo \"$RESULT\"; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "hostname": {
          "type": "string",
          "description": "Hostname to resolve"
        },
        "dns_server": {
          "type": "string",
          "description": "DNS server to query (e.g. 8.8.8.8, 1.1.1.1)"
        },
        "record_type": {
          "type": "string",
          "description": "DNS record type (A, AAAA, CNAME, MX, TXT)"
        },
        "timeout": {
          "type": "integer",
          "description": "Query timeout in seconds"
        }
      },
      "required": [
        "hostname",
        "dns_server",
        "record_type",
        "timeout"
      ]
    }
  },
  "explanation": "Tests DNS resolution for an service hostname against a specified DNS server and record type."
}

{
  "fields": {
    "name": "canary-single-server",
    "description": "Canary deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "deploy-canary",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git stash && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "canary_port": {
              "type": "string"
            },
            "prod_port": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "canary_port",
            "prod_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-canary",
        "action_type": "SHELL",
        "code": "PORT={{input.canary_port}} node {{input.app_dir}}/server.js &",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "canary-health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:{{input.canary_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "route-canary-traffic",
        "action_type": "SHELL",
        "code": "sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}} weight=9;\\n    server 127.0.0.1:{{input.canary_port}} weight=1;/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "monitor-errors",
        "action_type": "SHELL",
        "code": "sleep 30 && ERROR_RATE=$(tail -100 /var/log/nginx/access.log | grep -c \" 5[0-9][0-9] \") && test \"$ERROR_RATE\" -lt 5",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": false,
        "name": "promote-canary",
        "action_type": "SHELL",
        "code": "systemctl restart app && kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}};/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-canary",
        "action_type": "SHELL",
        "code": "kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; cd {{input.app_dir}} && git stash pop; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Canary: deploy new version on alternate port, route 10% traffic, monitor errors, promote or rollback."
}

{
  "fields": {
    "name": "deploy-redis",
    "description": "Redis with auth and persistence",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-redis",
        "action_type": "SHELL",
        "code": "apt-get install -y redis-server",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-redis",
        "action_type": "SHELL",
        "code": "sed -i \"s/^# requirepass/requirepass {{input.redis_pass}}/\" /etc/redis/redis.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "redis_pass": {
              "type": "string"
            }
          },
          "required": [
            "redis_pass"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "restart-redis",
        "action_type": "SHELL",
        "code": "systemctl restart redis-server",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-redis",
        "action_type": "SHELL",
        "code": "redis-cli -a {{input.redis_pass}} ping | grep PONG",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": true,
        "name": "undo-redis",
        "action_type": "SHELL",
        "code": "systemctl stop redis-server; apt-get remove -y redis-server",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Redis: install, configure auth, restart, verify PONG."
}

{
  "fields": {
    "name": "spamassassin-filter",
    "description": "Install and configure SpamAssassin",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-spamassassin",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y spamassassin spamc",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-spamd-user",
        "action_type": "SHELL",
        "code": "useradd -r -s /bin/false -d /var/lib/spamassassin spamd 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-rules",
        "action_type": "SHELL",
        "code": "cat > /etc/spamassassin/local.cf <<SPAM\nrewrite_header Subject [SPAM]\nrequired_score {{input.spam_score}}\nuse_bayes 1\nbayes_auto_learn 1\nSPAM",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "spam_score": {
              "type": "string"
            }
          },
          "required": [
            "spam_score"
          ]
        }
      },
      {
        "id": "4",
        "undo": false,
        "name": "update-rules",
        "action_type": "SHELL",
        "code": "sa-update",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"content_filter = smtp-amavis:[127.0.0.1]:10024\" 2>/dev/null; sed -i \"s/^ENABLED=0/ENABLED=1/\" /etc/default/spamassassin",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl enable --now spamassassin && systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-spamd",
        "action_type": "SHELL",
        "code": "echo \"Subject: Test\" | spamc -c; true",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl stop spamassassin; postconf -e \"content_filter =\"; systemctl restart postfix; apt-get remove -y spamassassin spamc",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "SpamAssassin: install, create user, configure rules + Bayes, update rules, integrate Postfix, verify."
}

{
  "fields": {
    "name": "Check cloudflare service health",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nhealth_url = \"{{input.health_url}}\"\napi_key = \"{{input.api_key}}\" or \"\"\nexpected_status = int(\"{{input.expected_status}}\" or \"200\")\n\nreq = urllib.request.Request(health_url, method=\"GET\")\nif api_key:\n    req.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=15)\n    code = resp.getcode()\n    body = resp.read().decode()\n    try:\n        data = json.loads(body)\n    except json.JSONDecodeError:\n        data = body\n    healthy = code == expected_status\n    print(json.dumps({{\"status\": \"healthy\" if healthy else \"unhealthy\", \"code\": code, \"body\": data}}))\n    if not healthy:\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"unreachable\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "health_url": {
          "type": "string",
          "description": "Health check endpoint URL"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth (optional)"
        },
        "expected_status": {
          "type": "string",
          "description": "Expected HTTP status code (default 200)"
        }
      },
      "required": [
        "health_url"
      ]
    }
  },
  "explanation": "Python action that checks cloudflare cloud service health by querying an endpoint and validating the response code."
}

{
  "fields": {
    "name": "cicd-java",
    "description": "CI/CD: pull, test, deploy java app",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && go build .",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pytest",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": false,
        "name": "deploy",
        "action_type": "SHELL",
        "code": "systemctl restart gunicorn",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "smoke-test",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:8000/health",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-deploy",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git checkout HEAD~1 && systemctl restart gunicorn",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "CI/CD for java: pull, install, test, deploy, smoke test with rollback."
}

{
  "fields": {
    "name": "swap-management",
    "description": "Configure or resize swap space",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "check-current-swap",
        "action_type": "SHELL",
        "code": "swapon --show && free -h | grep Swap",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "disable-old-swap",
        "action_type": "SHELL",
        "code": "swapoff /swapfile 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "create-swapfile",
        "action_type": "SHELL",
        "code": "fallocate -l {{input.swap_size}} /swapfile && chmod 600 /swapfile",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "schema": {
          "input": {
            "swap_size": {
              "type": "string"
            },
            "swappiness": {
              "type": "string"
            }
          },
          "required": [
            "swap_size",
            "swappiness"
          ]
        }
      },
      {
        "id": "4",
        "undo": false,
        "name": "format-swap",
        "action_type": "SHELL",
        "code": "mkswap /swapfile",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "enable-swap",
        "action_type": "SHELL",
        "code": "swapon /swapfile",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "persist-fstab",
        "action_type": "SHELL",
        "code": "grep -q \"/swapfile\" /etc/fstab || echo \"/swapfile none swap sw 0 0\" >> /etc/fstab",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "set-swappiness",
        "action_type": "SHELL",
        "code": "sysctl vm.swappiness={{input.swappiness}} && echo \"vm.swappiness={{input.swappiness}}\" > /etc/sysctl.d/99-swappiness.conf",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "8",
        "undo": false,
        "name": "verify-swap",
        "action_type": "SHELL",
        "code": "swapon --show | grep /swapfile && sysctl vm.swappiness",
        "target": "all",
        "parent_step_ids": [
          "6",
          "7"
        ],
        "expected_rc": 0
      },
      {
        "id": "9",
        "undo": true,
        "name": "undo-swap",
        "action_type": "SHELL",
        "code": "swapoff /swapfile 2>/dev/null; rm -f /swapfile /etc/sysctl.d/99-swappiness.conf; sed -i \"/\\/swapfile/d\" /etc/fstab; sysctl vm.swappiness=60",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Swap management: check current, disable old, create+format+enable swapfile, persist in fstab, set swappiness, verify."
}

{
  "fields": {
    "name": "fail2ban-setup",
    "description": "Install and configure Fail2Ban",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-fail2ban",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y fail2ban",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-jail",
        "action_type": "SHELL",
        "code": "cat > /etc/fail2ban/jail.local <<JAIL\n[DEFAULT]\nbantime = {{input.ban_time}}\nfindtime = 600\nmaxretry = {{input.max_retry}}\n[sshd]\nenabled = true\nport = ssh\nlogpath = /var/log/auth.log\nJAIL",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "ban_time": {
              "type": "string"
            },
            "max_retry": {
              "type": "string"
            }
          },
          "required": [
            "ban_time",
            "max_retry"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-fail2ban",
        "action_type": "SHELL",
        "code": "systemctl enable --now fail2ban",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-jail-status",
        "action_type": "SHELL",
        "code": "fail2ban-client status sshd",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": true,
        "name": "undo-fail2ban",
        "action_type": "SHELL",
        "code": "systemctl stop fail2ban; apt-get remove -y fail2ban",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Fail2Ban: install, configure jail for SSH, start, verify jail status."
}

{
  "fields": {
    "name": "Add iptables DROP rule",
    "action_type": "ANSIBLE",
    "code": "- name: Add iptables rule for port {{input.port}}\n  iptables:\n    chain: INPUT\n    protocol: \"{{input.protocol}}\"\n    destination_port: \"{{input.port}}\"\n    source: \"{{input.source}}\"\n    jump: \"{{input.jump}}\"\n    comment: \"{{input.comment}}\"\n\n- name: Save iptables rules\n  command: iptables-save > /etc/iptables/rules.v4\n  changed_when: true\n",
    "schema": {
      "input": {
        "port": {
          "type": "string",
          "description": "Destination port"
        },
        "protocol": {
          "type": "string",
          "description": "Protocol: tcp or udp"
        },
        "source": {
          "type": "string",
          "description": "Source IP/CIDR (default 0.0.0.0/0)"
        },
        "jump": {
          "type": "string",
          "description": "Target action: ACCEPT, DROP, REJECT"
        },
        "comment": {
          "type": "string",
          "description": "Rule comment"
        }
      },
      "required": [
        "port",
        "protocol",
        "jump"
      ]
    }
  },
  "explanation": "Ansible action that adds an iptables DROP rule for a specific port and persists the rules to disk."
}

{
  "fields": {
    "name": "Run web container",
    "action_type": "ANSIBLE",
    "code": "- name: Run {{input.container_name}} container\n  docker_container:\n    name: \"{{input.container_name}}\"\n    image: \"{{input.image}}\"\n    state: started\n    restart_policy: unless-stopped\n    ports:\n      - \"{{input.host_port}}:{{input.container_port}}\"\n    env: \"{{input.environment}}\"\n    volumes:\n      - \"{{input.volume_mount}}\"\n",
    "schema": {
      "input": {
        "container_name": {
          "type": "string",
          "description": "Container name"
        },
        "image": {
          "type": "string",
          "description": "Docker image to use"
        },
        "host_port": {
          "type": "string",
          "description": "Host port to map"
        },
        "container_port": {
          "type": "string",
          "description": "Container port to expose"
        },
        "environment": {
          "type": "string",
          "description": "Environment variables as JSON"
        },
        "volume_mount": {
          "type": "string",
          "description": "Volume mount (host:container)"
        }
      },
      "required": [
        "container_name",
        "image"
      ]
    }
  },
  "explanation": "Ansible action that runs a web Docker container with port mapping, environment variables, and volume mounts."
}

{
  "fields": {
    "name": "Install puma via gem",
    "action_type": "ANSIBLE",
    "code": "- name: Ensure Ruby is installed
  package:
    name:
      - ruby
      - ruby-dev
    state: present

- name: Install {{input.package}} gem
  gem:
    name: "{{input.package}}"
    version: "{{input.version}}"
    state: present
    user_install: no
  when: input.version is defined and input.version != ""

- name: Install {{input.package}} gem (latest)
  gem:
    name: "{{input.package}}"
    state: latest
    user_install: no
  when: input.version is not defined or input.version == ""

- name: Verify gem installation
  command: "gem list {{input.package}}"
  register: gem_check
  changed_when: false
",
    "schema": {
      "input": {
        "package": {
          "type": "string",
          "description": "Ruby gem name"
        },
        "version": {
          "type": "string",
          "description": "Gem version (optional)"
        }
      },
      "required": [
        "package"
      ]
    }
