{
  "fields": {
    "name": "Run DB migration scripts",
    "action_type": "PYTHON",
    "code": "import json
import os
import sqlite3
import sys

db_path = "{{input.db_path}}"
migration_dir = "{{input.migration_dir}}"

if not os.path.isdir(migration_dir):
    print(json.dumps({{"status": "error", "message": f"Migration dir not found: {{migration_dir}}"}}))
    sys.exit(1)

try:
    conn = sqlite3.connect(db_path)
    conn.execute("CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT DEFAULT CURRENT_TIMESTAMP)")
    applied = set(row[0] for row in conn.execute("SELECT version FROM schema_migrations").fetchall())
    scripts = sorted(f for f in os.listdir(migration_dir) if f.endswith(".sql"))
    newly_applied = []
    for script in scripts:
        version = script.split("_")[0] if "_" in script else script
        if version not in applied:
            sql_path = os.path.join(migration_dir, script)
            with open(sql_path, "r") as f:
                sql = f.read()
            conn.executescript(sql)
            conn.execute("INSERT INTO schema_migrations (version) VALUES (?)", (version,))
            conn.commit()
            newly_applied.append(script)
    conn.close()
    print(json.dumps({{"status": "ok", "applied": newly_applied, "count": len(newly_applied)}}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "db_path": {
          "type": "string",
          "description": "Path to database file"
        },
        "migration_dir": {
          "type": "string",
          "description": "Directory containing SQL migration scripts"
        }
      },
      "required": [
        "db_path",
        "migration_dir"
      ]
    }
  },
  "explanation": "Python action that runs pending SQL migration scripts against a mysql database, tracking applied versions."
}

{
  "fields": {
    "name": "Check open file descriptors",
    "action_type": "PYTHON",
    "code": "import json
import sys

threshold_pct = float("{{input.threshold_pct}}" or "80")

with open("/proc/sys/fs/file-nr", "r") as f:
    parts = f.read().strip().split()
    allocated = int(parts[0])
    free = int(parts[1])
    maximum = int(parts[2])

used = allocated - free
pct = (used / maximum) * 100.0 if maximum > 0 else 0.0

result = {{
    "allocated": allocated,
    "free": free,
    "used": used,
    "maximum": maximum,
    "percent_used": round(pct, 2),
    "threshold": threshold_pct,
    "status": "critical" if pct > threshold_pct else "ok",
}}
print(json.dumps(result))
if pct > threshold_pct:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "threshold_pct": {
          "type": "string",
          "description": "Usage threshold percentage (default 80)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/sys/fs/file-nr to check system-wide open file descriptor usage."
}

