{
  "fields": {
    "name": "Send Slack notification",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nwebhook_url = \"{{input.webhook_url}}\"\nchannel = \"{{input.channel}}\"\nmessage = \"{{input.message}}\"\nseverity = \"{{input.severity}}\" or \"info\"\n\ncolor_map = {{\"info\": \"#36a64f\", \"warning\": \"#ffcc00\", \"critical\": \"#ff0000\"}}\npayload = {{\n    \"channel\": channel,\n    \"attachments\": [{{\n        \"color\": color_map.get(severity, \"#36a64f\"),\n        \"title\": f\"[{{severity.upper()}}] Alert\",\n        \"text\": message,\n        \"footer\": \"Dimensigon Automation\",\n    }}],\n}}\n\ndata = json.dumps(payload).encode(\"utf-8\")\nreq = urllib.request.Request(webhook_url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=15)\n    print(json.dumps({{\"status\": \"sent\", \"channel\": channel}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "webhook_url": {
          "type": "string",
          "description": "Slack incoming webhook URL"
        },
        "channel": {
          "type": "string",
          "description": "Slack channel name"
        },
        "message": {
          "type": "string",
          "description": "Message text to send"
        },
        "severity": {
          "type": "string",
          "description": "Severity level: info, warning, critical"
        }
      },
      "required": [
        "webhook_url",
        "channel",
        "message"
      ]
    }
  },
  "explanation": "Python action that sends a critical-level notification to a Slack channel using an incoming webhook with color-coded severity."
}

