              "type": "string"
            },
            "workers": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "venv_dir",
            "branch",
            "workers"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "pull-code",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
