    "name": "cicd-go",
    "description": "CI/CD: pull, test, deploy go app",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && mvn test -q",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": false,
        "name": "deploy",
        "action_type": "SHELL",
        "code": "systemctl restart node-app",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "smoke-test",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:8080/health",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-deploy",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git checkout HEAD~1 && systemctl restart node-app",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "CI/CD for go: pull, install, test, deploy, smoke test with rollback."
}

{
  "fields": {
    "name": "tune-mysql",
    "description": "Tune MySQL/MariaDB performance",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-mysql-conf",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf /etc/mysql/mysql.conf.d/mysqld.cnf.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-buffer-pool",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*innodb_buffer_pool_size.*/innodb_buffer_pool_size = {{input.buffer_pool}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "buffer_pool": {
              "type": "string"
            },
            "max_conn": {
              "type": "string"
            }
          },
          "required": [
            "buffer_pool",
            "max_conn"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-connections",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_connections.*/max_connections = {{input.max_conn}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-mysql",
        "action_type": "SHELL",
        "code": "systemctl restart mysql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-mysql-vars",
        "action_type": "SHELL",
        "code": "mysql -e \"SHOW VARIABLES LIKE 'innodb_buffer_pool_size'; SHOW VARIABLES LIKE 'max_connections';\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-mysql-tuning",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf.bak /etc/mysql/mysql.conf.d/mysqld.cnf && systemctl restart mysql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "MySQL tuning: backup, set buffer pool + max connections in parallel, restart, verify."
}

