{
  "fields": {
    "name": "deploy-filebeat",
    "description": "Install and configure Filebeat log shipper",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-filebeat",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y filebeat",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-filebeat",
        "action_type": "SHELL",
        "code": "cat > /etc/filebeat/filebeat.yml <<FB\nfilebeat.inputs:\n  - type: log\n    enabled: true\n    paths:\n      - /var/log/syslog\n      - /var/log/auth.log\n      - {{input.extra_log_path}}\noutput.elasticsearch:\n  hosts: [\"{{input.es_host}}:9200\"]\nFB",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "es_host": {
              "type": "string"
            },
            "extra_log_path": {
              "type": "string"
            }
          },
          "required": [
            "es_host",
            "extra_log_path"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-filebeat-conf",
        "action_type": "SHELL",
        "code": "filebeat test config -c /etc/filebeat/filebeat.yml",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-filebeat",
        "action_type": "SHELL",
        "code": "systemctl enable --now filebeat",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-filebeat",
        "action_type": "SHELL",
        "code": "sleep 5 && filebeat test output",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-filebeat",
        "action_type": "SHELL",
        "code": "systemctl stop filebeat; apt-get remove -y filebeat",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Filebeat: install, configure inputs+output, test config, start, verify output connectivity."
}

{
  "fields": {
    "name": "Assert nginx is running",
    "action_type": "ANSIBLE",
    "code": "- name: Get {{input.service_name}} status\n  systemd:\n    name: \"{{input.service_name}}\"\n  register: service_state\n\n- name: Assert {{input.service_name}} is active\n  assert:\n    that:\n      - service_state.status.ActiveState == \"active\"\n    fail_msg: \"{{input.service_name}} is not active (state: {{ service_state.status.ActiveState }})\"\n    success_msg: \"{{input.service_name}} is running\"\n\n- name: Assert {{input.service_name}} is enabled\n  assert:\n    that:\n      - service_state.status.UnitFileState == \"enabled\"\n    fail_msg: \"{{input.service_name}} is not enabled\"\n    success_msg: \"{{input.service_name}} is enabled on boot\"\n",
    "schema": {
      "input": {
        "service_name": {
          "type": "string",
          "description": "Service name to assert status"
        }
      },
      "required": [
        "service_name"
      ]
    }
  },
  "explanation": "Ansible action that asserts nginx is both active and enabled using systemd facts and assertion checks."
}

