        "id": "2",
        "undo": false,
        "name": "configure-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"myhostname={{input.hostname}}\" && postconf -e \"mydomain={{input.domain}}\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "hostname": {
              "type": "string"
            },
            "domain": {
              "type": "string"
            }
          },
          "required": [
            "hostname",
            "domain"
          ]
        }
      },
      {
