{
  "fields": {
    "name": "SHA256 hash of binary file",
    "action_type": "PYTHON",
    "code": "import hashlib
import json
import os
import sys

file_path = "{{input.file_path}}"
expected_hash = "{{input.expected_hash}}" or ""

if not os.path.isfile(file_path):
    print(json.dumps({{"status": "error", "message": f"File not found: {{file_path}}"}}))
    sys.exit(1)

sha256 = hashlib.sha256()
with open(file_path, "rb") as f:
    for chunk in iter(lambda: f.read(8192), b""):
        sha256.update(chunk)
computed = sha256.hexdigest()

result = {{"status": "ok", "file": file_path, "sha256": computed, "size_bytes": os.path.getsize(file_path)}}
if expected_hash:
    match = computed == expected_hash.lower()
    result["match"] = match
    result["status"] = "ok" if match else "mismatch"
print(json.dumps(result))
if expected_hash and not match:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "file_path": {
          "type": "string",
          "description": "Path to file to hash"
        },
        "expected_hash": {
          "type": "string",
          "description": "Expected SHA256 hash to verify (optional)"
        }
      },
      "required": [
        "file_path"
      ]
    }
  },
  "explanation": "Python action that computes the SHA256 hash of a binary file and optionally verifies it against an expected value."
}

{
  "fields": {
    "name": "Count network connections",
    "action_type": "PYTHON",
    "code": "import json
import sys

port = "{{input.port}}"
threshold = int("{{input.threshold}}" or "1000")

states = {{}}
total = 0
tcp_state_map = {{
    "01": "ESTABLISHED", "02": "SYN_SENT", "03": "SYN_RECV",
    "04": "FIN_WAIT1", "05": "FIN_WAIT2", "06": "TIME_WAIT",
    "07": "CLOSE", "08": "CLOSE_WAIT", "09": "LAST_ACK",
    "0A": "LISTEN", "0B": "CLOSING",
}}

try:
    with open("/proc/net/tcp", "r") as f:
        lines = f.readlines()[1:]  # skip header
    for line in lines:
        parts = line.split()
        local_port = int(parts[1].split(":")[1], 16)
        state_code = parts[3]
        if port and str(local_port) != port:
            continue
        state = tcp_state_map.get(state_code, "UNKNOWN")
        states[state] = states.get(state, 0) + 1
        total += 1
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)

result = {{
    "total": total,
    "by_state": states,
    "threshold": threshold,
    "status": "critical" if total > threshold else "ok",
}}
print(json.dumps(result))
if total > threshold:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "port": {
          "type": "string",
          "description": "Filter by local port number (optional)"
        },
        "threshold": {
          "type": "string",
          "description": "Max connection count threshold (default 1000)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/net/tcp to count TCP connections by state, optionally filtering by port 5432."
}

