        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-opendkim",
        "action_type": "SHELL",
        "code": "systemctl enable --now opendkim && systemctl restart postfix",
        "target": "all",
