    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "snapshot-current",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && cp -a {{input.app_dir}} /var/backups/app_$TIMESTAMP && echo $TIMESTAMP > /tmp/deploy_timestamp",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
