{
  "fields": {
    "name": "Decode JWT token",
    "action_type": "PYTHON",
    "code": "import json
import base64
import sys

token = "{{input.token}}"

parts = token.split(".")
if len(parts) != 3:
    print(json.dumps({{"status": "error", "message": "Invalid JWT format"}}))
    sys.exit(1)

def decode_part(part):
    padding = 4 - len(part) % 4
    part += "=" * padding
    return json.loads(base64.urlsafe_b64decode(part).decode("utf-8"))

try:
    header = decode_part(parts[0])
    payload = decode_part(parts[1])
    import time
    exp = payload.get("exp")
    expired = exp is not None and exp < time.time()
    print(json.dumps({{
        "status": "ok",
        "header": header,
        "payload": payload,
        "expired": expired,
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "token": {
          "type": "string",
          "description": "JWT token string to decode"
        }
      },
      "required": [
        "token"
      ]
    }
  },
  "explanation": "Python action that decodes a service-to-service JWT token header and payload using base64, checking expiration."
}

{
