{
  "fields": {
    "name": "temp-file-cleanup",
    "description": "Clean temporary files and caches",
    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "clean-tmp-old",
        "action_type": "SHELL",
        "code": "find /tmp -type f -mtime +{{input.days_old}} -delete 2>/dev/null; find /tmp -type d -empty -mtime +{{input.days_old}} -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "days_old": {
              "type": "string"
            }
          },
          "required": [
            "days_old"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clean-var-tmp",
        "action_type": "SHELL",
        "code": "find /var/tmp -type f -mtime +{{input.days_old}} -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "truncate-large-logs",
        "action_type": "SHELL",
        "code": "find /var/log -name \"*.log\" -size +100M -exec truncate -s 10M {} \\; 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "4",
        "undo": false,
        "name": "clean-journal",
        "action_type": "SHELL",
        "code": "journalctl --vacuum-time={{input.days_old}}d --vacuum-size=500M 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "5",
        "undo": false,
        "name": "clean-thumbnail-cache",
        "action_type": "SHELL",
        "code": "find /home -path \"*/.cache/thumbnails\" -type d -exec rm -rf {} + 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "6",
        "undo": false,
        "name": "report-freed-space",
        "action_type": "SHELL",
        "code": "df -h / /tmp /var",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2",
          "3",
          "4",
          "5"
        ]
      }
    ]
  },
  "explanation": "Temp cleanup: parallel clean /tmp, /var/tmp, truncate logs, vacuum journal, remove caches, report space."
}

{
  "fields": {
    "name": "pg-replica-prep",
    "description": "Prepare PostgreSQL for streaming replication",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-pg-conf",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf /etc/postgresql/*/main/postgresql.conf.repl.bak && cp /etc/postgresql/*/main/pg_hba.conf /etc/postgresql/*/main/pg_hba.conf.repl.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-wal-level",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*wal_level.*/wal_level = replica/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-wal-senders",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_wal_senders.*/max_wal_senders = 5/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "create-repl-user",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"CREATE USER {{input.repl_user}} WITH REPLICATION PASSWORD '{{input.repl_pass}}'\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "repl_user": {
              "type": "string"
            },
            "repl_pass": {
              "type": "string"
            },
            "replica_ip": {
              "type": "string"
            }
          },
          "required": [
            "repl_user",
            "repl_pass",
            "replica_ip"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "add-hba-entry",
        "action_type": "SHELL",
        "code": "echo \"host replication {{input.repl_user}} {{input.replica_ip}}/32 md5\" >> /etc/postgresql/*/main/pg_hba.conf",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-postgresql",
        "action_type": "SHELL",
        "code": "systemctl restart postgresql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-wal-level",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"SHOW wal_level\" | grep replica",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-repl-prep",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf.repl.bak /etc/postgresql/*/main/postgresql.conf && cp /etc/postgresql/*/main/pg_hba.conf.repl.bak /etc/postgresql/*/main/pg_hba.conf && systemctl restart postgresql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Replica prep: backup, set wal_level+max_wal_senders, create repl user, add HBA entry, restart, verify."
}

