    "name": "sha256-verify-binary",
    "action_type": "SHELL",
    "code": "if [ ! -f \"{{input.file_path}}\" ]; then echo \"File not found\" >&2; exit 1; fi && ACTUAL=$(sha256sum \"{{input.file_path}}\" | awk '{{print $1}}') && if [ \"$ACTUAL\" = \"{{input.expected_hash}}\" ]; then echo \"PASS: Checksum matches\"; echo \"SHA256: $ACTUAL\"; exit 0; else echo \"FAIL: Checksum mismatch\" >&2; echo \"Expected: {{input.expected_hash}}\" >&2; echo \"Actual:   $ACTUAL\" >&2; exit 1; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "file_path": {
          "type": "string",
          "description": "Path to the file to verify"
        },
        "expected_hash": {
          "type": "string",
          "description": "Expected SHA256 hash"
        }
      },
      "required": [
        "file_path",
        "expected_hash"
      ]
    }
  },
  "explanation": "Verifies the SHA256 checksum of a binary file against an expected hash value."
}

{
  "fields": {
    "name": "pg-replica-prep",
    "description": "Prepare PostgreSQL for streaming replication",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-pg-conf",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf /etc/postgresql/*/main/postgresql.conf.repl.bak && cp /etc/postgresql/*/main/pg_hba.conf /etc/postgresql/*/main/pg_hba.conf.repl.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-wal-level",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*wal_level.*/wal_level = replica/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-wal-senders",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_wal_senders.*/max_wal_senders = 5/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "create-repl-user",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"CREATE USER {{input.repl_user}} WITH REPLICATION PASSWORD '{{input.repl_pass}}'\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "repl_user": {
              "type": "string"
            },
            "repl_pass": {
              "type": "string"
            },
            "replica_ip": {
              "type": "string"
            }
          },
          "required": [
            "repl_user",
            "repl_pass",
            "replica_ip"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "add-hba-entry",
        "action_type": "SHELL",
        "code": "echo \"host replication {{input.repl_user}} {{input.replica_ip}}/32 md5\" >> /etc/postgresql/*/main/pg_hba.conf",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-postgresql",
        "action_type": "SHELL",
        "code": "systemctl restart postgresql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-wal-level",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"SHOW wal_level\" | grep replica",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-repl-prep",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf.repl.bak /etc/postgresql/*/main/postgresql.conf && cp /etc/postgresql/*/main/pg_hba.conf.repl.bak /etc/postgresql/*/main/pg_hba.conf && systemctl restart postgresql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Replica prep: backup, set wal_level+max_wal_senders, create repl user, add HBA entry, restart, verify."
}

