{
  "fields": {
    "name": "deploy-pgbouncer",
    "description": "Deploy PgBouncer connection pooler",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-pgbouncer",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y pgbouncer",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-pgbouncer",
        "action_type": "SHELL",
        "code": "cat > /etc/pgbouncer/pgbouncer.ini <<INI\n[databases]\n{{input.db_name}} = host=127.0.0.1 port=5432 dbname={{input.db_name}}\n[pgbouncer]\nlisten_addr = 127.0.0.1\nlisten_port = 6432\nauth_type = md5\nauth_file = /etc/pgbouncer/userlist.txt\npool_mode = transaction\nmax_client_conn = {{input.max_clients}}\ndefault_pool_size = {{input.pool_size}}\nINI",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "db_name": {
              "type": "string"
            },
            "db_user": {
              "type": "string"
            },
            "db_pass": {
              "type": "string"
            },
            "max_clients": {
              "type": "string"
            },
            "pool_size": {
              "type": "string"
            }
          },
          "required": [
            "db_name",
            "db_user",
            "db_pass",
            "max_clients",
            "pool_size"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "write-userlist",
        "action_type": "SHELL",
        "code": "echo \"\"{{input.db_user}}\" \"{{input.db_pass}}\"\" > /etc/pgbouncer/userlist.txt && chmod 640 /etc/pgbouncer/userlist.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl enable --now pgbouncer",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-pgbouncer",
        "action_type": "SHELL",
        "code": "psql -h 127.0.0.1 -p 6432 -U {{input.db_user}} {{input.db_name}} -c \"SELECT 1\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl stop pgbouncer; apt-get remove -y pgbouncer",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "PgBouncer: install, configure pool, write userlist, start, verify connectivity."
}

{
  "fields": {
    "name": "deploy-with-rollback",
    "description": "Deploy with automatic rollback on failure",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "snapshot-current",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && cp -a {{input.app_dir}} /var/backups/app_$TIMESTAMP && echo $TIMESTAMP > /tmp/deploy_timestamp",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "svc_name": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "svc_name"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm test",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "restart-service",
        "action_type": "SHELL",
        "code": "systemctl restart {{input.svc_name}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 5 && curl -sf http://localhost:3000/health",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "rollback-deploy",
        "action_type": "SHELL",
        "code": "TS=$(cat /tmp/deploy_timestamp) && rm -rf {{input.app_dir}} && cp -a /var/backups/app_$TS {{input.app_dir}} && systemctl restart {{input.svc_name}}",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Rollback deploy: snapshot app dir, pull, install, test, restart, health check. Restores from snapshot on failure."
}

