    "expected_rc": 0,
    "schema": {
      "input": {
        "backup_archive": {
          "type": "string",
          "description": "Path to the tar.gz backup archive"
        },
        "file_path": {
          "type": "string",
          "description": "Relative path of the file inside the archive to restore"
        },
        "restore_dir": {
          "type": "string",
          "description": "Directory to restore the file into"
        }
      },
      "required": [
        "backup_archive",
        "file_path",
        "restore_dir"
