        "code": "cp /etc/postgresql/*/main/postgresql.conf /etc/postgresql/*/main/postgresql.conf.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-shared-buffers",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*shared_buffers.*/shared_buffers = {{input.shared_buffers}}/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "shared_buffers": {
              "type": "string"
