        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "set-max-connections",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_connections.*/max_connections = {{input.max_connections}}/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "restart-postgresql",
        "action_type": "SHELL",
        "code": "systemctl restart postgresql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3",
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "verify-settings",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"SHOW shared_buffers; SHOW work_mem; SHOW max_connections;\"",
