{
  "fields": {
    "name": "Override limits for haproxy",
    "action_type": "ANSIBLE",
    "code": "- name: Create systemd override directory for {{input.service_name}}\n  file:\n    path: \"/etc/systemd/system/{{input.service_name}}.service.d\"\n    state: directory\n    mode: \"0755\"\n\n- name: Deploy limits override for {{input.service_name}}\n  copy:\n    dest: \"/etc/systemd/system/{{input.service_name}}.service.d/limits.conf\"\n    content: |\n      [Service]\n      LimitNOFILE={{input.limit_nofile}}\n      LimitNPROC={{input.limit_nproc}}\n      LimitMEMLOCK={{input.limit_memlock}}\n    mode: \"0644\"\n  notify: reload systemd and restart service\n\n- name: Reload systemd daemon\n  systemd:\n    daemon_reload: yes\n\n- name: Restart {{input.service_name}} to apply limits\n  systemd:\n    name: \"{{input.service_name}}\"\n    state: restarted\n",
    "schema": {
      "input": {
        "service_name": {
          "type": "string",
          "description": "Service name to set limits for"
        },
        "limit_nofile": {
          "type": "string",
          "description": "Max open files limit (e.g. 65536)"
        },
        "limit_nproc": {
          "type": "string",
          "description": "Max processes limit (e.g. 4096)"
        },
        "limit_memlock": {
          "type": "string",
          "description": "Max locked memory (e.g. infinity, 67108864)"
        }
      },
      "required": [
        "service_name",
        "limit_nofile"
      ]
    }
  },
  "explanation": "Ansible action that creates a systemd drop-in override to set file, process, and memory limits for haproxy."
}

{
  "fields": {
    "name": "apparmor-profile-setup",
    "description": "Create and enforce AppArmor profile",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-apparmor-utils",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y apparmor-utils",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-profile",
        "action_type": "SHELL",
        "code": "cat > /etc/apparmor.d/usr.local.bin.{{input.app_name}} <<PROF\n#include <tunables/global>\n/usr/local/bin/{{input.app_name}} {\n  #include <abstractions/base>\n  #include <abstractions/nameservice>\n  /usr/local/bin/{{input.app_name}} mr,\n  /var/log/{{input.app_name}}/** rw,\n  /tmp/{{input.app_name}}/** rw,\n  /etc/{{input.app_name}}/** r,\n  deny /etc/shadow r,\n  deny /etc/passwd w,\n}\nPROF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "app_name": {
              "type": "string"
            }
          },
          "required": [
            "app_name"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "load-profile-complain",
        "action_type": "SHELL",
        "code": "apparmor_parser -r /etc/apparmor.d/usr.local.bin.{{input.app_name}} && aa-complain /usr/local/bin/{{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enforce-profile",
        "action_type": "SHELL",
        "code": "aa-enforce /usr/local/bin/{{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-profile",
        "action_type": "SHELL",
        "code": "aa-status | grep {{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-apparmor",
        "action_type": "SHELL",
        "code": "aa-disable /usr/local/bin/{{input.app_name}} 2>/dev/null; rm -f /etc/apparmor.d/usr.local.bin.{{input.app_name}}",
        "parent_step_ids": [
          "2"
        ]
      }
    ]
  },
  "explanation": "AppArmor: install utils, create profile, load in complain mode, enforce, verify status."
}

