        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
