{
  "fields": {
    "name": "nginx-error-count",
    "action_type": "SHELL",
    "code": "if [ ! -f \"{{input.log_file}}\" ]; then echo \"FAILED: Log file not found: {{input.log_file}}\" >&2; exit 1; fi && ERROR_COUNT=$(grep -c -i \"{{input.error_pattern}}\" \"{{input.log_file}}\" 2>/dev/null || echo 0) && echo \"Error count in {{input.log_file}}: $ERROR_COUNT (pattern: {{input.error_pattern}})\" && if [ \"$ERROR_COUNT\" -ge \"{{input.threshold}}\" ]; then echo \"CRITICAL: $ERROR_COUNT errors found (threshold: {{input.threshold}})\" >&2; echo \"=== Recent matching lines ===\" && grep -i \"{{input.error_pattern}}\" \"{{input.log_file}}\" | tail -5; exit 1; else echo \"OK: Error count ($ERROR_COUNT) is below threshold ({{input.threshold}})\"; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "log_file": {
          "type": "string",
          "description": "Path to the application log file"
        },
        "error_pattern": {
          "type": "string",
          "description": "Grep pattern to match errors (e.g. ERROR, FATAL, Exception)"
        },
        "threshold": {
          "type": "integer",
          "description": "Maximum acceptable error count"
        },
        "lookback_minutes": {
          "type": "integer",
          "description": "Number of minutes to look back in the log"
        }
      },
      "required": [
        "log_file",
        "error_pattern",
        "threshold",
        "lookback_minutes"
      ]
    }
  },
  "explanation": "Counts error occurrences in the nginx application log and alerts if the count exceeds the threshold."
}

{
  "fields": {
