    "expected_rc": 0,
    "schema": {
      "input": {
        "local_file": {
          "type": "string",
          "description": "Path to the local backup file"
        },
        "bucket": {
          "type": "string",
          "description": "S3 bucket name"
        },
        "s3_prefix": {
          "type": "string",
          "description": "S3 key prefix/folder path"
        },
        "storage_class": {
          "type": "string",
          "description": "S3 storage class (STANDARD, STANDARD_IA, GLACIER, DEEP_ARCHIVE)"
        }
      },
      "required": [
        "local_file",
        "bucket",
        "s3_prefix",
        "storage_class"
      ]
    }
  },
  "explanation": "Uploads a logs backup file to Amazon S3 with server-side AES256 encryption and configurable storage class."
}

