{
  "fields": {
    "name": "Analyze postgres slow query log",
    "action_type": "PYTHON",
    "code": "import json
import os
import re
import sys

log_file = "{{input.log_file}}"
threshold_sec = float("{{input.threshold_sec}}" or "1.0")
max_queries = int("{{input.max_queries}}" or "20")

if not os.path.isfile(log_file):
    print(json.dumps({{"status": "error", "message": f"Log file not found: {{log_file}}"}}))
    sys.exit(1)

slow_queries = []
time_pattern = re.compile(r"Query_time:\s*([\d.]+)")

with open(log_file, "r", errors="replace") as f:
    current_time = 0
    current_query = ""
    for line in f:
        match = time_pattern.search(line)
        if match:
            if current_query and current_time >= threshold_sec:
                slow_queries.append({{"time_sec": current_time, "query": current_query[:200]}})
            current_time = float(match.group(1))
            current_query = ""
        elif not line.startswith("#") and line.strip():
            current_query += line.strip() + " "
    if current_query and current_time >= threshold_sec:
        slow_queries.append({{"time_sec": current_time, "query": current_query[:200]}})

slow_queries.sort(key=lambda x: x["time_sec"], reverse=True)
print(json.dumps({{
    "status": "ok",
    "log_file": log_file,
    "threshold_sec": threshold_sec,
    "total_slow_queries": len(slow_queries),
    "top_queries": slow_queries[:max_queries],
}}))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "log_file": {
          "type": "string",
          "description": "Path to the slow query log file"
        },
        "threshold_sec": {
          "type": "string",
          "description": "Minimum query time in seconds (default 1.0)"
        },
        "max_queries": {
          "type": "string",
          "description": "Maximum queries to return (default 20)"
        }
      },
      "required": [
        "log_file"
      ]
    }
  },
  "explanation": "Python action that parses a postgres slow query log, extracts queries above a time threshold, and ranks them by execution time."
}

