{
  "fields": {
    "name": "HTTP GET apache health",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nurl = \"{{input.url}}\"\nreq = urllib.request.Request(url, method=\"GET\")\nif \"{{input.auth_header}}\":\n    req.add_header(\"Authorization\", \"{{input.auth_header}}\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    body = json.loads(resp.read().decode())\n    status = resp.getcode()\n    if status == 200:\n        print(json.dumps({{\"status\": \"ok\", \"code\": status, \"body\": body}}))\n    else:\n        print(json.dumps({{\"status\": \"error\", \"code\": status}}))\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
