          "type": "string",
          "description": "Authorization header value (optional)"
        }
      },
      "required": [
        "url"
      ]
    }
  },
  "explanation": "Python action that sends an HTTP GET request to a apache endpoint, checks the response status code, and returns the result as JSON."
}

