  "fields": {
    "name": "gRPC health check for api-gateway",
    "action_type": "PYTHON",
    "code": "import json\nimport http.client\nimport ssl\nimport sys\n\nhost = \"{{input.host}}\"\nport = int(\"{{input.port}}\" or \"443\")\nuse_tls = \"{{input.use_tls}}\" != \"false\"\ntimeout = int(\"{{input.timeout}}\" or \"10\")\n\ntry:\n    if use_tls:\n        ctx = ssl.create_default_context()\n        conn = http.client.HTTPSConnection(host, port, timeout=timeout, context=ctx)\n    else:\n        conn = http.client.HTTPConnection(host, port, timeout=timeout)\n    conn.request(\"POST\", \"/grpc.health.v1.Health/Check\",\n                 headers={{\"Content-Type\": \"application/grpc\", \"TE\": \"trailers\"}})\n    resp = conn.getresponse()\n    body = resp.read()\n    conn.close()\n    if resp.status == 200:\n        print(json.dumps({{\"status\": \"ok\", \"code\": resp.status, \"message\": \"gRPC service healthy\"}}))\n    else:\n        print(json.dumps({{\"status\": \"error\", \"code\": resp.status}}))\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
