{
  "fields": {
    "name": "tune-mysql",
    "description": "Tune MySQL/MariaDB performance",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-mysql-conf",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf /etc/mysql/mysql.conf.d/mysqld.cnf.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-buffer-pool",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*innodb_buffer_pool_size.*/innodb_buffer_pool_size = {{input.buffer_pool}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "buffer_pool": {
              "type": "string"
            },
            "max_conn": {
              "type": "string"
            }
          },
          "required": [
            "buffer_pool",
            "max_conn"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-connections",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_connections.*/max_connections = {{input.max_conn}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-mysql",
        "action_type": "SHELL",
        "code": "systemctl restart mysql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-mysql-vars",
        "action_type": "SHELL",
        "code": "mysql -e \"SHOW VARIABLES LIKE 'innodb_buffer_pool_size'; SHOW VARIABLES LIKE 'max_connections';\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-mysql-tuning",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf.bak /etc/mysql/mysql.conf.d/mysqld.cnf && systemctl restart mysql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "MySQL tuning: backup, set buffer pool + max connections in parallel, restart, verify."
}

{
  "fields": {
    "name": "frontend-response-time",
    "action_type": "SHELL",
    "code": "TIMES=$(curl -s -o /dev/null -w \"dns:%{time_namelookup} connect:%{time_connect} ttfb:%{time_starttransfer} total:%{time_total}\" --connect-timeout {{input.timeout}} --max-time {{input.max_time}} \"{{input.url}}\") && TOTAL=$(echo \"$TIMES\" | grep -oP \"total:\\K[0-9.]+\") && TOTAL_MS=$(echo \"$TOTAL\" | awk '{printf \"%d\", $1 * 1000}') && echo \"Response times for {{input.url}}: $TIMES\" && if [ \"$TOTAL_MS\" -ge \"{{input.threshold_ms}}\" ]; then echo \"WARNING: Response time (${TOTAL_MS}ms) exceeds {{input.threshold_ms}}ms threshold\" >&2; exit 1; else echo \"OK: Response time ${TOTAL_MS}ms is within {{input.threshold_ms}}ms threshold\"; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "URL to measure response time for"
        },
        "timeout": {
          "type": "integer",
          "description": "Connection timeout in seconds"
        },
        "max_time": {
          "type": "integer",
          "description": "Maximum total time in seconds"
        },
        "threshold_ms": {
          "type": "integer",
          "description": "Response time threshold in milliseconds"
        }
      },
      "required": [
        "url",
        "timeout",
        "max_time",
        "threshold_ms"
      ]
    }
  },
  "explanation": "Measures DNS, connect, TTFB, and total response time for the frontend endpoint and alerts if the threshold is exceeded."
}

