{
  "fields": {
    "name": "staging-pitr-restore",
    "action_type": "SHELL",
    "code": "echo \"=== Point-in-Time Restore for {{input.database}} ===\" && echo \"Stopping PostgreSQL...\" && systemctl stop postgresql 2>&1 && echo \"Cleaning data directory...\" && rm -rf {{input.data_dir}}/* && echo \"Restoring base backup...\" && tar xzf \"{{input.base_backup}}\" -C {{input.data_dir}}/ 2>&1 && echo \"Configuring recovery target...\" && cat > {{input.data_dir}}/recovery.signal <<SIGNAL\nSIGNAL\ncat >> {{input.data_dir}}/postgresql.auto.conf <<RECOVERY\nrestore_command = 'cp {{input.wal_archive_dir}}/%f %p'\nrecovery_target_time = '{{input.target_time}}'\nrecovery_target_action = 'promote'\nRECOVERY\nchown -R postgres:postgres {{input.data_dir}} && echo \"Starting PostgreSQL for recovery...\" && systemctl start postgresql 2>&1 && echo \"PITR restore initiated to target time: {{input.target_time}}\"",
    "expected_rc": 0,
    "schema": {
      "input": {
        "database": {
          "type": "string",
          "description": "Database identifier"
        },
        "data_dir": {
          "type": "string",
          "description": "PostgreSQL data directory path"
        },
        "base_backup": {
          "type": "string",
          "description": "Path to the base backup tar.gz file"
        },
        "wal_archive_dir": {
          "type": "string",
          "description": "Directory containing WAL archive files"
        },
        "target_time": {
          "type": "string",
          "description": "Recovery target timestamp (e.g. 2024-01-15 14:30:00)"
        }
      },
      "required": [
        "database",
        "data_dir",
        "base_backup",
        "wal_archive_dir",
        "target_time"
      ]
    }
  },
  "explanation": "Performs a PostgreSQL point-in-time recovery for the staging database using a base backup and WAL archive."
}

{
  "fields": {
    "name": "deploy-mongodb",
    "description": "Deploy MongoDB with auth enabled",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "import-mongo-key",
        "action_type": "SHELL",
        "code": "curl -fsSL https://pgp.mongodb.com/server-7.0.asc | gpg --dearmor -o /usr/share/keyrings/mongodb-server-7.0.gpg",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-mongo-repo",
        "action_type": "SHELL",
        "code": "echo \"deb [signed-by=/usr/share/keyrings/mongodb-server-7.0.gpg] https://repo.mongodb.org/apt/ubuntu jammy/mongodb-org/7.0 multiverse\" > /etc/apt/sources.list.d/mongodb-org-7.0.list && apt-get update",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-mongodb",
        "action_type": "SHELL",
        "code": "apt-get install -y mongodb-org",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-mongodb",
        "action_type": "SHELL",
        "code": "systemctl enable --now mongod",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "create-admin-user",
        "action_type": "SHELL",
        "code": "mongosh --eval \"use admin; db.createUser({user:\"{{input.admin_user}}\",pwd:\"{{input.admin_pass}}\",roles:[\"root\"]})\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "schema": {
          "input": {
            "admin_user": {
              "type": "string"
            },
            "admin_pass": {
              "type": "string"
            }
          },
          "required": [
            "admin_user",
            "admin_pass"
          ]
        }
      },
      {
        "id": "6",
        "undo": false,
        "name": "enable-auth",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#security:/security:\\n  authorization: enabled/\" /etc/mongod.conf && systemctl restart mongod",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-mongodb",
        "action_type": "SHELL",
        "code": "mongosh -u {{input.admin_user}} -p {{input.admin_pass}} --authenticationDatabase admin --eval \"db.runCommand({ping:1})\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-mongodb",
        "action_type": "SHELL",
        "code": "systemctl stop mongod; apt-get remove -y mongodb-org",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "MongoDB: import key, add repo, install, start, create admin, enable auth, verify."
}

{
