{
  "fields": {
    "name": "Poll redis until ready",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport time\nimport sys\n\nurl = \"{{input.url}}\"\nmax_retries = int(\"{{input.max_retries}}\" or \"30\")\ninterval = int(\"{{input.interval}}\" or \"10\")\n\nfor attempt in range(1, max_retries + 1):\n    try:\n        req = urllib.request.Request(url, method=\"GET\")\n        resp = urllib.request.urlopen(req, timeout=10)\n        body = json.loads(resp.read().decode())\n        if resp.getcode() == 200:\n            print(json.dumps({{\"status\": \"ready\", \"attempt\": attempt, \"body\": body}}))\n            sys.exit(0)\n    except Exception:\n        pass\n    print(f\"Attempt {{attempt}}/{{max_retries}} - not ready, waiting {{interval}}s...\")\n    time.sleep(interval)\n\nprint(json.dumps({{\"status\": \"timeout\", \"attempts\": max_retries}}))\nsys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "Endpoint URL to poll"
        },
        "max_retries": {
          "type": "string",
          "description": "Max number of retries (default 30)"
        },
        "interval": {
          "type": "string",
          "description": "Seconds between retries (default 10)"
        }
      },
      "required": [
        "url"
      ]
    }
  },
  "explanation": "Python action that repeatedly polls a redis health endpoint until it returns HTTP 200 or max retries are exhausted."
}

