{
  "fields": {
    "name": "canary-single-server",
    "description": "Canary deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "deploy-canary",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git stash && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "canary_port": {
              "type": "string"
            },
            "prod_port": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "canary_port",
            "prod_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-canary",
        "action_type": "SHELL",
        "code": "PORT={{input.canary_port}} node {{input.app_dir}}/server.js &",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "canary-health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:{{input.canary_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "route-canary-traffic",
        "action_type": "SHELL",
        "code": "sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}} weight=9;\\n    server 127.0.0.1:{{input.canary_port}} weight=1;/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "monitor-errors",
        "action_type": "SHELL",
        "code": "sleep 30 && ERROR_RATE=$(tail -100 /var/log/nginx/access.log | grep -c \" 5[0-9][0-9] \") && test \"$ERROR_RATE\" -lt 5",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": false,
        "name": "promote-canary",
        "action_type": "SHELL",
        "code": "systemctl restart app && kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}};/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-canary",
        "action_type": "SHELL",
        "code": "kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; cd {{input.app_dir}} && git stash pop; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Canary: deploy new version on alternate port, route 10% traffic, monitor errors, promote or rollback."
}

{
  "fields": {
    "name": "pg-replica-prep",
    "description": "Prepare PostgreSQL for streaming replication",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-pg-conf",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf /etc/postgresql/*/main/postgresql.conf.repl.bak && cp /etc/postgresql/*/main/pg_hba.conf /etc/postgresql/*/main/pg_hba.conf.repl.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-wal-level",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*wal_level.*/wal_level = replica/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-wal-senders",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_wal_senders.*/max_wal_senders = 5/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "create-repl-user",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"CREATE USER {{input.repl_user}} WITH REPLICATION PASSWORD '{{input.repl_pass}}'\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "repl_user": {
              "type": "string"
            },
            "repl_pass": {
              "type": "string"
            },
            "replica_ip": {
              "type": "string"
            }
          },
          "required": [
            "repl_user",
            "repl_pass",
            "replica_ip"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "add-hba-entry",
        "action_type": "SHELL",
        "code": "echo \"host replication {{input.repl_user}} {{input.replica_ip}}/32 md5\" >> /etc/postgresql/*/main/pg_hba.conf",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-postgresql",
        "action_type": "SHELL",
        "code": "systemctl restart postgresql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-wal-level",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"SHOW wal_level\" | grep replica",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-repl-prep",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf.repl.bak /etc/postgresql/*/main/postgresql.conf && cp /etc/postgresql/*/main/pg_hba.conf.repl.bak /etc/postgresql/*/main/pg_hba.conf && systemctl restart postgresql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Replica prep: backup, set wal_level+max_wal_senders, create repl user, add HBA entry, restart, verify."
}

