{
  "fields": {
    "name": "artifact-cleanup",
    "description": "Clean up old CI/CD artifacts and images",
    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "clean-old-backups",
        "action_type": "SHELL",
        "code": "find /var/backups/app_* -maxdepth 0 -mtime +{{input.retention_days}} -exec rm -rf {} \\; 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "retention_days": {
              "type": "string"
            },
            "registry": {
              "type": "string"
            },
            "image_name": {
              "type": "string"
            }
          },
          "required": [
            "retention_days"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clean-docker-images",
        "action_type": "SHELL",
        "code": "docker image prune -a --filter \"until={{input.retention_days}}d\" -f 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "clean-build-caches",
        "action_type": "SHELL",
        "code": "docker builder prune -f --keep-storage=5GB 2>/dev/null; npm cache clean --force 2>/dev/null; pip cache purge 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "4",
        "undo": false,
        "name": "clean-test-artifacts",
        "action_type": "SHELL",
        "code": "find /tmp -name \"test-results*.xml\" -mtime +7 -delete 2>/dev/null; find /tmp -name \"*_pre_ci.sql\" -mtime +3 -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "5",
        "undo": false,
        "name": "report-disk-freed",
        "action_type": "SHELL",
        "code": "df -h / | tail -1",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2",
          "3",
          "4"
        ]
      }
    ]
  },
  "explanation": "Artifact cleanup: parallel clean old backups, docker images, build caches, test artifacts, then report disk."
}

{
  "fields": {
    "name": "tune-mysql",
    "description": "Tune MySQL/MariaDB performance",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-mysql-conf",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf /etc/mysql/mysql.conf.d/mysqld.cnf.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-buffer-pool",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*innodb_buffer_pool_size.*/innodb_buffer_pool_size = {{input.buffer_pool}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "buffer_pool": {
              "type": "string"
            },
            "max_conn": {
              "type": "string"
            }
          },
          "required": [
            "buffer_pool",
            "max_conn"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-connections",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_connections.*/max_connections = {{input.max_conn}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-mysql",
        "action_type": "SHELL",
        "code": "systemctl restart mysql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-mysql-vars",
        "action_type": "SHELL",
        "code": "mysql -e \"SHOW VARIABLES LIKE 'innodb_buffer_pool_size'; SHOW VARIABLES LIKE 'max_connections';\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-mysql-tuning",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf.bak /etc/mysql/mysql.conf.d/mysqld.cnf && systemctl restart mysql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "MySQL tuning: backup, set buffer pool + max connections in parallel, restart, verify."
}

