{
  "fields": {
    "name": "Detect postgres connection leaks",
    "action_type": "PYTHON",
    "code": "import json
import socket
import time
import sys

host = "{{input.host}}" or "localhost"
port = int("{{input.port}}")
interval = int("{{input.interval}}" or "5")
samples = int("{{input.samples}}" or "6")
growth_threshold = int("{{input.growth_threshold}}" or "10")

def count_connections(h, p):
    count = 0
    try:
        with open("/proc/net/tcp", "r") as f:
            for line in f.readlines()[1:]:
                parts = line.split()
                remote_port = int(parts[2].split(":")[1], 16)
                state = parts[3]
                if remote_port == p and state == "01":
                    count += 1
    except Exception:
        pass
    return count

counts = []
for i in range(samples):
    c = count_connections(host, port)
    counts.append(c)
    if i < samples - 1:
        time.sleep(interval)

growth = counts[-1] - counts[0] if len(counts) > 1 else 0
leak_detected = growth >= growth_threshold
result = {{
    "status": "leak_suspected" if leak_detected else "ok",
    "host": host,
    "port": port,
    "samples": counts,
    "growth": growth,
    "growth_threshold": growth_threshold,
    "first_count": counts[0],
    "last_count": counts[-1],
}}
print(json.dumps(result))
if leak_detected:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "Database host (default localhost)"
        },
        "port": {
          "type": "string",
          "description": "Database port"
        },
        "interval": {
          "type": "string",
          "description": "Seconds between samples (default 5)"
        },
        "samples": {
          "type": "string",
          "description": "Number of samples to take (default 6)"
        },
        "growth_threshold": {
          "type": "string",
          "description": "Connection growth to flag as leak (default 10)"
        }
      },
      "required": [
        "port"
      ]
    }
  },
  "explanation": "Python action that samples postgres connection counts over time and alerts if steady growth indicates a connection leak."
}

