{
  "fields": {
    "name": "Check CPU usage",
    "action_type": "PYTHON",
    "code": "import json
import sys
import os

threshold = float("{{input.threshold}}" or "80")

def get_cpu_usage():
    with open("/proc/stat", "r") as f:
        line = f.readline()
    parts = line.split()
    idle = int(parts[4])
    total = sum(int(p) for p in parts[1:])
    return idle, total

import time
idle1, total1 = get_cpu_usage()
time.sleep(1)
idle2, total2 = get_cpu_usage()

idle_delta = idle2 - idle1
total_delta = total2 - total1
usage = (1.0 - idle_delta / total_delta) * 100.0 if total_delta > 0 else 0.0
cpu_count = os.cpu_count() or 1

result = {{
    "cpu_percent": round(usage, 2),
    "cpu_count": cpu_count,
    "threshold": threshold,
    "status": "critical" if usage > threshold else "ok",
}}
print(json.dumps(result))
if usage > threshold:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "threshold": {
          "type": "string",
          "description": "CPU usage percent threshold (default 80)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/stat to compute CPU usage percentage and alerts if it exceeds the threshold."
}

