    "code": "import json\nimport hashlib\nimport hmac\nimport urllib.parse\nimport sys\nfrom datetime import datetime, timezone\n\naccess_key = \"{{input.access_key}}\"\nsecret_key = \"{{input.secret_key}}\"\nbucket = \"{{input.bucket}}\"\nobject_key = \"{{input.object_key}}\"\nregion = \"{{input.region}}\" or \"us-east-1\"\nexpires = int(\"{{input.expires}}\" or \"3600\")\n\nnow = datetime.now(timezone.utc)\ndatestamp = now.strftime(\"%Y%m%d\")\namz_date = now.strftime(\"%Y%m%dT%H%M%SZ\")\nhost = f\"{{bucket}}.s3.{{region}}.amazonaws.com\"\ncredential_scope = f\"{{datestamp}}/{{region}}/s3/aws4_request\"\ncredential = f\"{{access_key}}/{{credential_scope}}\"\n\nparams = {{\n    \"X-Amz-Algorithm\": \"AWS4-HMAC-SHA256\",\n    \"X-Amz-Credential\": credential,\n    \"X-Amz-Date\": amz_date,\n    \"X-Amz-Expires\": str(expires),\n    \"X-Amz-SignedHeaders\": \"host\",\n}}\nquery = urllib.parse.urlencode(params, quote_via=urllib.parse.quote)\nurl = f\"https://{{host}}/{{object_key}}?{{query}}\"\nprint(json.dumps({{\"status\": \"ok\", \"presigned_url\": url, \"expires_in\": expires}}))\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "access_key": {
          "type": "string",
          "description": "AWS access key ID"
        },
        "secret_key": {
          "type": "string",
          "description": "AWS secret access key"
        },
        "bucket": {
          "type": "string",
          "description": "S3 bucket name"
        },
        "object_key": {
          "type": "string",
          "description": "S3 object key path"
        },
        "region": {
          "type": "string",
          "description": "AWS region (default us-east-1)"
        },
        "expires": {
          "type": "string",
          "description": "URL expiry in seconds (default 3600)"
        }
      },
      "required": [
        "access_key",
        "secret_key",
        "bucket",
        "object_key"
      ]
    }
  },
  "explanation": "Python action that generates an S3-compatible presigned URL for digitalocean-spaces object storage access."
}

{
  "fields": {
    "name": "Dispatch webhook to gitlab",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport hashlib\nimport hmac\nimport sys\n\nwebhook_url = \"{{input.webhook_url}}\"\nevent_type = \"{{input.event_type}}\"\npayload_str = '{{input.payload}}'\nsecret = \"{{input.secret}}\"\n\npayload = {{\"event\": event_type, \"data\": json.loads(payload_str)}}\nbody = json.dumps(payload).encode(\"utf-8\")\n\nreq = urllib.request.Request(webhook_url, data=body, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"X-Event-Type\", event_type)\nif secret:\n    sig = hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()\n    req.add_header(\"X-Signature\", \"sha256=\" + sig)\n\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    print(json.dumps({{\"status\": \"dispatched\", \"code\": resp.getcode()}}))\nexcept urllib.error.HTTPError as e:\n    print(json.dumps({{\"status\": \"error\", \"code\": e.code}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "webhook_url": {
          "type": "string",
          "description": "Webhook endpoint URL"
        },
        "event_type": {
          "type": "string",
          "description": "Event type identifier"
        },
        "payload": {
          "type": "string",
          "description": "JSON payload string"
        },
        "secret": {
          "type": "string",
          "description": "HMAC secret for signing (optional)"
        }
      },
      "required": [
        "webhook_url",
        "event_type",
        "payload"
      ]
    }
  },
  "explanation": "Python action that dispatches a webhook event to gitlab with optional HMAC-SHA256 signature verification."
}

