    "code": "import json\nimport urllib.request\nimport urllib.parse\nimport sys\n\nbot_token = \"{{input.bot_token}}\"\nchat_id = \"{{input.chat_id}}\"\nmessage = \"{{input.message}}\"\nparse_mode = \"{{input.parse_mode}}\" or \"Markdown\"\n\nurl = f\"https://api.telegram.org/bot{{bot_token}}/sendMessage\"\ndata = urllib.parse.urlencode({{\n    \"chat_id\": chat_id,\n    \"text\": message,\n    \"parse_mode\": parse_mode,\n}}).encode(\"utf-8\")\n\nreq = urllib.request.Request(url, data=data, method=\"POST\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=15)\n    result = json.loads(resp.read().decode())\n    if result.get(\"ok\"):\n        print(json.dumps({{\"status\": \"sent\", \"message_id\": result[\"result\"][\"message_id\"]}}))\n    else:\n        print(json.dumps({{\"status\": \"error\", \"description\": result.get(\"description\")}}))\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "bot_token": {
          "type": "string",
          "description": "Telegram bot API token"
        },
        "chat_id": {
          "type": "string",
          "description": "Telegram chat or group ID"
        },
        "message": {
          "type": "string",
          "description": "Message text to send"
        },
        "parse_mode": {
          "type": "string",
          "description": "Parse mode: Markdown or HTML"
        }
      },
      "required": [
        "bot_token",
        "chat_id",
        "message"
      ]
    }
  },
  "explanation": "Python action that sends a HTML-formatted message via Telegram Bot API to a specified chat."
}

