    "code": "import json\nimport urllib.request\nimport sys\n\napi_url = \"{{input.api_url}}\"\napi_key = \"{{input.api_key}}\"\npaths = \"{{input.paths}}\"\n\npath_list = [p.strip() for p in paths.split(\",\") if p.strip()]\npayload = {{\"purge_paths\": path_list}}\ndata = json.dumps(payload).encode(\"utf-8\")\nreq = urllib.request.Request(api_url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    result = json.loads(resp.read().decode())\n    print(json.dumps({{\"status\": \"purged\", \"paths\": path_list, \"count\": len(path_list)}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "api_url": {
          "type": "string",
          "description": "CDN purge API endpoint"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        },
        "paths": {
          "type": "string",
          "description": "Comma-separated paths to purge"
        }
      },
      "required": [
        "api_url",
        "api_key",
        "paths"
      ]
    }
  },
  "explanation": "Python action that purges cached content on fastly CDN for specified URL paths."
}

