{
  "fields": {
    "name": "Log notification to file",
    "action_type": "PYTHON",
    "code": "import json\nimport os\nimport sys\nfrom datetime import datetime\n\nlog_file = \"{{input.log_file}}\"\nlevel = \"{{input.level}}\" or \"INFO\"\nmessage = \"{{input.message}}\"\nsource = \"{{input.source}}\" or \"dimensigon\"\n\nlog_dir = os.path.dirname(log_file)\nif log_dir and not os.path.isdir(log_dir):\n    os.makedirs(log_dir, exist_ok=True)\n\ntimestamp = datetime.utcnow().isoformat() + \"Z\"\nentry = {{\n    \"timestamp\": timestamp,\n    \"level\": level.upper(),\n    \"source\": source,\n    \"message\": message,\n}}\n\ntry:\n    with open(log_file, \"a\") as f:\n        f.write(json.dumps(entry) + \"\\n\")\n    print(json.dumps({{\"status\": \"logged\", \"file\": log_file, \"level\": level}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "log_file": {
          "type": "string",
          "description": "Path to log file"
        },
        "level": {
          "type": "string",
          "description": "Log level: INFO, WARNING, ERROR, CRITICAL"
        },
        "message": {
          "type": "string",
          "description": "Log message"
        },
        "source": {
          "type": "string",
          "description": "Source identifier (optional)"
        }
      },
      "required": [
        "log_file",
        "message"
      ]
    }
  },
  "explanation": "Python action that appends a structured JSON INFO-level log entry to a notification log file."
}

