{
  "fields": {
    "name": "disk-usage-check-var",
    "action_type": "SHELL",
    "code": "USAGE=$(df \"{{input.mount_point}}\" --output=pcent | tail -1 | tr -d \" %%\") && echo \"Disk usage on {{input.mount_point}}: ${{USAGE}}%%\" && if [ \"$USAGE\" -ge \"{{input.threshold}}\" ]; then echo \"CRITICAL: Usage ${{USAGE}}%% exceeds threshold {{input.threshold}}%%\" >&2; exit 1; else echo \"OK: Usage is within acceptable range\"; exit 0; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "mount_point": {
          "type": "string",
          "description": "Mount point to check (e.g. /, /var, /home)"
        },
        "threshold": {
          "type": "integer",
          "description": "Usage percentage threshold to alert on"
        }
      },
      "required": [
        "mount_point",
        "threshold"
      ]
    }
  },
  "explanation": "Checks disk usage on the var filesystem and alerts if it exceeds the configured threshold."
}

{
  "fields": {
    "name": "multi-container-app",
    "description": "Deploy multi-container app with DB and cache",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-network",
        "action_type": "SHELL",
        "code": "docker network create {{input.app_name}}-net 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_name": {
              "type": "string"
            },
            "app_image": {
              "type": "string"
            },
            "app_port": {
              "type": "string"
            }
          },
          "required": [
            "app_name",
            "app_image",
            "app_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "start-database",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-db --network {{input.app_name}}-net -v {{input.app_name}}-dbdata:/var/lib/postgresql/data -e POSTGRES_DB={{input.app_name}} -e POSTGRES_PASSWORD=secret postgres:16-alpine",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-redis",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-redis --network {{input.app_name}}-net redis:7-alpine",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "wait-for-deps",
        "action_type": "SHELL",
        "code": "sleep 5 && docker exec {{input.app_name}}-db pg_isready && docker exec {{input.app_name}}-redis redis-cli ping",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "start-app",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-app --network {{input.app_name}}-net -p {{input.app_port}}:8080 -e DATABASE_URL=postgresql://postgres:secret@{{input.app_name}}-db/{{input.app_name}} -e REDIS_URL=redis://{{input.app_name}}-redis:6379 {{input.app_image}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 5 && curl -sf http://localhost:{{input.app_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "undo-multi-container",
        "action_type": "SHELL",
        "code": "docker stop {{input.app_name}}-app {{input.app_name}}-redis {{input.app_name}}-db 2>/dev/null; docker rm {{input.app_name}}-app {{input.app_name}}-redis {{input.app_name}}-db 2>/dev/null; docker network rm {{input.app_name}}-net 2>/dev/null; true",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Multi-container: create network, start DB+Redis in parallel, wait, start app, health check."
}

