    "name": "pg-replica-prep",
    "description": "Prepare PostgreSQL for streaming replication",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-pg-conf",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf /etc/postgresql/*/main/postgresql.conf.repl.bak && cp /etc/postgresql/*/main/pg_hba.conf /etc/postgresql/*/main/pg_hba.conf.repl.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-wal-level",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*wal_level.*/wal_level = replica/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-wal-senders",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_wal_senders.*/max_wal_senders = 5/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "create-repl-user",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"CREATE USER {{input.repl_user}} WITH REPLICATION PASSWORD '{{input.repl_pass}}'\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "repl_user": {
              "type": "string"
            },
            "repl_pass": {
              "type": "string"
            },
            "replica_ip": {
              "type": "string"
            }
          },
          "required": [
            "repl_user",
            "repl_pass",
            "replica_ip"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "add-hba-entry",
        "action_type": "SHELL",
        "code": "echo \"host replication {{input.repl_user}} {{input.replica_ip}}/32 md5\" >> /etc/postgresql/*/main/pg_hba.conf",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-postgresql",
        "action_type": "SHELL",
        "code": "systemctl restart postgresql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-wal-level",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"SHOW wal_level\" | grep replica",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-repl-prep",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf.repl.bak /etc/postgresql/*/main/postgresql.conf && cp /etc/postgresql/*/main/pg_hba.conf.repl.bak /etc/postgresql/*/main/pg_hba.conf && systemctl restart postgresql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Replica prep: backup, set wal_level+max_wal_senders, create repl user, add HBA entry, restart, verify."
}

{
  "fields": {
    "name": "container-log-collect",
    "description": "Set up centralized container log collection",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "configure-log-driver",
        "action_type": "SHELL",
        "code": "cat > /etc/docker/daemon.json <<JSON\n{\n  \"log-driver\": \"json-file\",\n  \"log-opts\": {\n    \"max-size\": \"{{input.max_size}}\",\n    \"max-file\": \"{{input.max_files}}\"\n  }\n}\nJSON",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "max_size": {
              "type": "string"
            },
            "max_files": {
              "type": "string"
            }
          },
          "required": [
            "max_size",
            "max_files"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "restart-docker",
        "action_type": "SHELL",
        "code": "systemctl restart docker",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "deploy-log-aggregator",
        "action_type": "SHELL",
        "code": "docker run -d --name log-aggregator --restart unless-stopped -v /var/lib/docker/containers:/var/lib/docker/containers:ro -v /var/run/docker.sock:/var/run/docker.sock:ro -p 24224:24224 fluent/fluentd:v1.16-1",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-log-driver",
        "action_type": "SHELL",
        "code": "docker info --format \"{{.LoggingDriver}}\" | grep json-file",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-aggregator",
        "action_type": "SHELL",
        "code": "sleep 3 && docker logs log-aggregator 2>&1 | head -3",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-log-collection",
        "action_type": "SHELL",
        "code": "docker stop log-aggregator 2>/dev/null; docker rm log-aggregator 2>/dev/null; rm /etc/docker/daemon.json; systemctl restart docker",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Container logs: configure JSON log driver with rotation, restart Docker, deploy fluentd aggregator, verify."
}

{
  "fields": {
    "name": "deploy-go-binary",
    "description": "Build and deploy Go binary",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-binary",
        "action_type": "SHELL",
        "code": "cp {{input.bin_path}} {{input.bin_path}}.bak 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "src_dir": {
              "type": "string"
            },
            "bin_path": {
              "type": "string"
            },
            "svc_name": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            }
          },
          "required": [
            "src_dir",
            "bin_path",
            "svc_name",
            "branch"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "pull-code",
        "action_type": "SHELL",
        "code": "cd {{input.src_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "build-binary",
        "action_type": "SHELL",
        "code": "cd {{input.src_dir}} && CGO_ENABLED=0 go build -o /tmp/app_new .",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "stop-service",
        "action_type": "SHELL",
        "code": "systemctl stop {{input.svc_name}}",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "replace-binary",
        "action_type": "SHELL",
        "code": "mv /tmp/app_new {{input.bin_path}} && chmod +x {{input.bin_path}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-service",
        "action_type": "SHELL",
        "code": "systemctl start {{input.svc_name}}",
