        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 2 && curl -sf http://localhost:8080/healthz",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-go-deploy",
        "action_type": "SHELL",
        "code": "cp {{input.bin_path}}.bak {{input.bin_path}} && systemctl restart {{input.svc_name}}",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Go deploy: backup binary, pull, build, stop, replace binary, start, health check."
}

{
  "fields": {
    "name": "apparmor-profile-setup",
    "description": "Create and enforce AppArmor profile",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-apparmor-utils",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y apparmor-utils",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-profile",
        "action_type": "SHELL",
        "code": "cat > /etc/apparmor.d/usr.local.bin.{{input.app_name}} <<PROF\n#include <tunables/global>\n/usr/local/bin/{{input.app_name}} {\n  #include <abstractions/base>\n  #include <abstractions/nameservice>\n  /usr/local/bin/{{input.app_name}} mr,\n  /var/log/{{input.app_name}}/** rw,\n  /tmp/{{input.app_name}}/** rw,\n  /etc/{{input.app_name}}/** r,\n  deny /etc/shadow r,\n  deny /etc/passwd w,\n}\nPROF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "app_name": {
              "type": "string"
            }
          },
          "required": [
            "app_name"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "load-profile-complain",
        "action_type": "SHELL",
        "code": "apparmor_parser -r /etc/apparmor.d/usr.local.bin.{{input.app_name}} && aa-complain /usr/local/bin/{{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enforce-profile",
        "action_type": "SHELL",
        "code": "aa-enforce /usr/local/bin/{{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-profile",
        "action_type": "SHELL",
        "code": "aa-status | grep {{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-apparmor",
        "action_type": "SHELL",
        "code": "aa-disable /usr/local/bin/{{input.app_name}} 2>/dev/null; rm -f /etc/apparmor.d/usr.local.bin.{{input.app_name}}",
        "parent_step_ids": [
          "2"
        ]
      }
    ]
  },
  "explanation": "AppArmor: install utils, create profile, load in complain mode, enforce, verify status."
}

{
  "fields": {
    "name": "reverse-proxy-nginx",
    "description": "Configure nginx as reverse proxy",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
