        "code": "cat > /etc/nginx/sites-available/proxy.conf <<CONF\n<VirtualHost *:80>\nServerName {{input.server_name}}\nProxyPass / http://{{input.backend_host}}:{{input.backend_port}}/\nProxyPassReverse / http://{{input.backend_host}}:{{input.backend_port}}/\n</VirtualHost>\nCONF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "backend_host": {
              "type": "string"
            },
            "backend_port": {
              "type": "string"
            },
            "server_name": {
              "type": "string"
            }
          },
          "required": [
            "backend_host",
            "backend_port",
            "server_name"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-config",
        "action_type": "SHELL",
        "code": "apachectl configtest",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": false,
        "name": "reload-nginx",
        "action_type": "SHELL",
        "code": "systemctl reload nginx",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-proxy",
        "action_type": "SHELL",
        "code": "curl -sf -H \"Host: {{input.server_name}}\" http://localhost/",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-proxy",
        "action_type": "SHELL",
        "code": "rm -rf /etc/nginx && mv /etc/nginx.bak /etc/nginx && systemctl reload nginx",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Reverse proxy: backup, write proxy config, test, reload, verify with rollback."
}

{
  "fields": {
    "name": "artifact-cleanup",
    "description": "Clean up old CI/CD artifacts and images",
    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "clean-old-backups",
        "action_type": "SHELL",
        "code": "find /var/backups/app_* -maxdepth 0 -mtime +{{input.retention_days}} -exec rm -rf {} \\; 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "retention_days": {
              "type": "string"
            },
            "registry": {
              "type": "string"
            },
            "image_name": {
              "type": "string"
            }
          },
          "required": [
            "retention_days"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clean-docker-images",
        "action_type": "SHELL",
        "code": "docker image prune -a --filter \"until={{input.retention_days}}d\" -f 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "clean-build-caches",
        "action_type": "SHELL",
        "code": "docker builder prune -f --keep-storage=5GB 2>/dev/null; npm cache clean --force 2>/dev/null; pip cache purge 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "4",
        "undo": false,
        "name": "clean-test-artifacts",
        "action_type": "SHELL",
        "code": "find /tmp -name \"test-results*.xml\" -mtime +7 -delete 2>/dev/null; find /tmp -name \"*_pre_ci.sql\" -mtime +3 -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "5",
        "undo": false,
        "name": "report-disk-freed",
        "action_type": "SHELL",
        "code": "df -h / | tail -1",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2",
          "3",
          "4"
        ]
      }
    ]
  },
  "explanation": "Artifact cleanup: parallel clean old backups, docker images, build caches, test artifacts, then report disk."
}

