{
  "fields": {
    "name": "deploy-mongodb",
    "description": "Deploy MongoDB with auth enabled",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "import-mongo-key",
        "action_type": "SHELL",
        "code": "curl -fsSL https://pgp.mongodb.com/server-7.0.asc | gpg --dearmor -o /usr/share/keyrings/mongodb-server-7.0.gpg",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-mongo-repo",
        "action_type": "SHELL",
        "code": "echo \"deb [signed-by=/usr/share/keyrings/mongodb-server-7.0.gpg] https://repo.mongodb.org/apt/ubuntu jammy/mongodb-org/7.0 multiverse\" > /etc/apt/sources.list.d/mongodb-org-7.0.list && apt-get update",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-mongodb",
        "action_type": "SHELL",
        "code": "apt-get install -y mongodb-org",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-mongodb",
        "action_type": "SHELL",
        "code": "systemctl enable --now mongod",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "create-admin-user",
        "action_type": "SHELL",
        "code": "mongosh --eval \"use admin; db.createUser({user:\"{{input.admin_user}}\",pwd:\"{{input.admin_pass}}\",roles:[\"root\"]})\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "schema": {
          "input": {
            "admin_user": {
              "type": "string"
            },
            "admin_pass": {
              "type": "string"
            }
          },
          "required": [
            "admin_user",
            "admin_pass"
          ]
        }
      },
      {
        "id": "6",
        "undo": false,
        "name": "enable-auth",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#security:/security:\\n  authorization: enabled/\" /etc/mongod.conf && systemctl restart mongod",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-mongodb",
        "action_type": "SHELL",
        "code": "mongosh -u {{input.admin_user}} -p {{input.admin_pass}} --authenticationDatabase admin --eval \"db.runCommand({ping:1})\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-mongodb",
        "action_type": "SHELL",
        "code": "systemctl stop mongod; apt-get remove -y mongodb-org",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "MongoDB: import key, add repo, install, start, create admin, enable auth, verify."
}

{
  "fields": {
    "name": "multi-container-app",
    "description": "Deploy multi-container app with DB and cache",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-network",
        "action_type": "SHELL",
        "code": "docker network create {{input.app_name}}-net 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_name": {
              "type": "string"
            },
            "app_image": {
              "type": "string"
            },
            "app_port": {
              "type": "string"
            }
          },
          "required": [
            "app_name",
            "app_image",
            "app_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "start-database",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-db --network {{input.app_name}}-net -v {{input.app_name}}-dbdata:/var/lib/postgresql/data -e POSTGRES_DB={{input.app_name}} -e POSTGRES_PASSWORD=secret postgres:16-alpine",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-redis",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-redis --network {{input.app_name}}-net redis:7-alpine",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
