{
  "fields": {
    "name": "dovecot-imap",
    "description": "Install and configure Dovecot IMAP server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-dovecot",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y dovecot-imapd dovecot-lmtpd",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-maildir",
        "action_type": "SHELL",
        "code": "sed -i \"s|^#*mail_location.*|mail_location = maildir:~/Maildir|\" /etc/dovecot/conf.d/10-mail.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-auth",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*disable_plaintext_auth.*/disable_plaintext_auth = yes/\" /etc/dovecot/conf.d/10-auth.conf && sed -i \"s/^#*auth_mechanisms.*/auth_mechanisms = plain login/\" /etc/dovecot/conf.d/10-auth.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "configure-ssl",
        "action_type": "SHELL",
        "code": "sed -i \"s|^#*ssl_cert.*|ssl_cert = </etc/letsencrypt/live/{{input.domain}}/fullchain.pem|\" /etc/dovecot/conf.d/10-ssl.conf && sed -i \"s|^#*ssl_key.*|ssl_key = </etc/letsencrypt/live/{{input.domain}}/privkey.pem|\" /etc/dovecot/conf.d/10-ssl.conf && sed -i \"s/^#*ssl =.*/ssl = required/\" /etc/dovecot/conf.d/10-ssl.conf",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ],
        "schema": {
          "input": {
            "domain": {
              "type": "string"
            }
          },
          "required": [
            "domain"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "restart-dovecot",
        "action_type": "SHELL",
        "code": "systemctl enable --now dovecot",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "verify-imap",
        "action_type": "SHELL",
        "code": "echo \"A1 LOGOUT\" | openssl s_client -connect localhost:993 -quiet 2>/dev/null | grep -q \"OK\"",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "undo-dovecot",
        "action_type": "SHELL",
        "code": "systemctl stop dovecot; apt-get remove -y dovecot-imapd dovecot-lmtpd",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Dovecot: install, configure maildir+auth+SSL, restart, verify IMAP on port 993."
}

{
  "fields": {
    "name": "canary-single-server",
    "description": "Canary deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "deploy-canary",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git stash && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "canary_port": {
              "type": "string"
            },
            "prod_port": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "canary_port",
            "prod_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-canary",
        "action_type": "SHELL",
        "code": "PORT={{input.canary_port}} node {{input.app_dir}}/server.js &",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "canary-health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:{{input.canary_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "route-canary-traffic",
        "action_type": "SHELL",
        "code": "sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}} weight=9;\\n    server 127.0.0.1:{{input.canary_port}} weight=1;/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "monitor-errors",
        "action_type": "SHELL",
        "code": "sleep 30 && ERROR_RATE=$(tail -100 /var/log/nginx/access.log | grep -c \" 5[0-9][0-9] \") && test \"$ERROR_RATE\" -lt 5",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": false,
        "name": "promote-canary",
        "action_type": "SHELL",
        "code": "systemctl restart app && kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}};/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-canary",
        "action_type": "SHELL",
        "code": "kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; cd {{input.app_dir}} && git stash pop; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Canary: deploy new version on alternate port, route 10% traffic, monitor errors, promote or rollback."
}

