    "code": "import json\nimport urllib.request\nimport sys\n\nurl = \"{{input.url}}\"\nreq = urllib.request.Request(url, method=\"DELETE\")\nreq.add_header(\"Authorization\", \"Bearer {{input.api_key}}\")\nreq.add_header(\"Content-Type\", \"application/json\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    code = resp.getcode()\n    if code in (200, 202, 204):\n        print(json.dumps({{\"status\": \"deleted\", \"code\": code}}))\n    else:\n        print(json.dumps({{\"status\": \"unexpected\", \"code\": code}}))\n        sys.exit(1)\nexcept urllib.error.HTTPError as e:\n    print(json.dumps({{\"status\": \"error\", \"code\": e.code}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "Resource URL to delete"
