{
  "fields": {
    "name": "Generic webhook with retry",
    "action_type": "PYTHON",
    "code": "import json
import urllib.request
import urllib.error
import time
import sys

url = "{{input.url}}"
payload_str = '{{input.payload}}'
max_retries = int("{{input.max_retries}}" or "3")
headers_str = '{{input.headers}}' or "{{}}"

payload = json.loads(payload_str)
headers = json.loads(headers_str)
data = json.dumps(payload).encode("utf-8")

for attempt in range(1, max_retries + 1):
    req = urllib.request.Request(url, data=data, method="POST")
    req.add_header("Content-Type", "application/json")
    for k, v in headers.items():
        req.add_header(k, v)
    try:
        resp = urllib.request.urlopen(req, timeout=15)
        code = resp.getcode()
        if code < 300:
            print(json.dumps({{"status": "sent", "code": code, "attempt": attempt}}))
            sys.exit(0)
    except urllib.error.HTTPError as e:
        if attempt == max_retries:
            print(json.dumps({{"status": "failed", "code": e.code, "attempts": attempt}}))
            sys.exit(1)
    except Exception as e:
        if attempt == max_retries:
            print(json.dumps({{"status": "error", "message": str(e), "attempts": attempt}}))
            sys.exit(1)
    time.sleep(2 ** attempt)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "Webhook URL"
        },
        "payload": {
          "type": "string",
          "description": "JSON payload string"
        },
        "max_retries": {
          "type": "string",
          "description": "Max retry attempts (default 3)"
        },
        "headers": {
          "type": "string",
          "description": "JSON string of extra headers (optional)"
        }
      },
      "required": [
        "url",
        "payload"
      ]
    }
  },
  "explanation": "Python action that sends a webhook POST request to a logging system with exponential backoff retry on failure."
}

