{
  "fields": {
    "name": "GET digitalocean instance metadata",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nmetadata_url = \"{{input.metadata_url}}\"\ntoken_header = \"{{input.token_header}}\" or \"\"\ntoken_value = \"{{input.token_value}}\" or \"\"\n\nreq = urllib.request.Request(metadata_url, method=\"GET\")\nif token_header and token_value:\n    req.add_header(token_header, token_value)\ntry:\n    resp = urllib.request.urlopen(req, timeout=5)\n    body = resp.read().decode()\n    try:\n        data = json.loads(body)\n    except json.JSONDecodeError:\n        data = body\n    print(json.dumps({{\"status\": \"ok\", \"metadata\": data}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
