        },
        "token_value": {
          "type": "string",
          "description": "Auth header value (optional)"
        }
      },
      "required": [
        "metadata_url"
      ]
    }
  },
  "explanation": "Python action that sends an HTTP GET to the digitalocean instance metadata endpoint and returns the result."
}

