        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": false,
        "name": "reload-apache2",
        "action_type": "SHELL",
        "code": "systemctl reload apache2",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-proxy",
