  "fields": {
    "name": "PagerDuty alert trigger",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nrouting_key = \"{{input.routing_key}}\"\nsummary = \"{{input.summary}}\"\nseverity = \"{{input.severity}}\" or \"error\"\nsource = \"{{input.source}}\" or \"dimensigon\"\ncomponent = \"{{input.component}}\"\n\npayload = {{\n    \"routing_key\": routing_key,\n    \"event_action\": \"trigger\",\n    \"payload\": {{\n        \"summary\": summary,\n        \"severity\": severity,\n        \"source\": source,\n        \"component\": component,\n    }},\n}}\n\ndata = json.dumps(payload).encode(\"utf-8\")\nurl = \"https://events.pagerduty.com/v2/enqueue\"\nreq = urllib.request.Request(url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=15)\n    result = json.loads(resp.read().decode())\n    print(json.dumps({{\"status\": result.get(\"status\"), \"dedup_key\": result.get(\"dedup_key\")}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "routing_key": {
          "type": "string",
          "description": "PagerDuty Events API v2 routing key"
        },
        "summary": {
          "type": "string",
          "description": "Alert summary text"
        },
        "severity": {
          "type": "string",
          "description": "Severity: critical, error, warning, info"
        },
        "source": {
          "type": "string",
          "description": "Source of the alert"
        },
        "component": {
          "type": "string",
          "description": "Affected component"
        }
      },
      "required": [
        "routing_key",
        "summary"
      ]
    }
  },
  "explanation": "Python action that triggers a warning-level PagerDuty alert using Events API v2."
}

{
  "fields": {
    "name": "config-backup-encrypt",
    "action_type": "SHELL",
    "code": "if [ ! -f \"{{input.backup_file}}\" ]; then echo \"FAILED: Source file not found: {{input.backup_file}}\" >&2; exit 1; fi && echo \"Encrypting {{input.backup_file}} with GPG...\" && gpg --batch --yes --symmetric --cipher-algo AES256 --passphrase \"{{input.passphrase}}\" --output \"{{input.backup_file}}.gpg\" \"{{input.backup_file}}\" 2>&1 && ORIG_SIZE=$(du -sh \"{{input.backup_file}}\" | cut -f1) && ENC_SIZE=$(du -sh \"{{input.backup_file}}.gpg\" | cut -f1) && echo \"Encryption complete: {{input.backup_file}}.gpg ($ENC_SIZE, original: $ORIG_SIZE)\" || (echo \"FAILED: GPG encryption error\" >&2; exit 1)",
    "expected_rc": 0,
    "schema": {
      "input": {
        "backup_file": {
          "type": "string",
          "description": "Path to the backup file to encrypt"
        },
        "passphrase": {
          "type": "string",
          "description": "Symmetric encryption passphrase"
        }
      },
      "required": [
        "backup_file",
        "passphrase"
      ]
    }
  },
  "explanation": "Encrypts a config backup file using GPG symmetric AES256 encryption with a passphrase."
}

