{
  "fields": {
    "name": "dkim-signing",
    "description": "Set up OpenDKIM for email signing",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-opendkim",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y opendkim opendkim-tools",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-key-dir",
        "action_type": "SHELL",
        "code": "mkdir -p /etc/opendkim/keys/{{input.domain}} && chown -R opendkim:opendkim /etc/opendkim",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "domain": {
              "type": "string"
            },
            "selector": {
              "type": "string"
            }
          },
          "required": [
            "domain",
            "selector"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "generate-dkim-key",
        "action_type": "SHELL",
        "code": "opendkim-genkey -s {{input.selector}} -d {{input.domain}} -D /etc/opendkim/keys/{{input.domain}} && chown opendkim:opendkim /etc/opendkim/keys/{{input.domain}}/*",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "configure-opendkim",
        "action_type": "SHELL",
        "code": "cat > /etc/opendkim.conf <<DKIM\nSyslog yes\nDomain {{input.domain}}\nSelector {{input.selector}}\nKeyFile /etc/opendkim/keys/{{input.domain}}/{{input.selector}}.private\nSocket inet:8891@localhost\nCanonicalization relaxed/simple\nMode sv\nDKIM",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"milter_default_action = accept\" && postconf -e \"milter_protocol = 6\" && postconf -e \"smtpd_milters = inet:localhost:8891\" && postconf -e \"non_smtpd_milters = inet:localhost:8891\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-opendkim",
        "action_type": "SHELL",
        "code": "systemctl enable --now opendkim && systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "show-dns-record",
        "action_type": "SHELL",
        "code": "cat /etc/opendkim/keys/{{input.domain}}/{{input.selector}}.txt",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-dkim",
        "action_type": "SHELL",
        "code": "systemctl stop opendkim; postconf -e \"smtpd_milters =\" && postconf -e \"non_smtpd_milters =\" && systemctl restart postfix; apt-get remove -y opendkim opendkim-tools",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "DKIM: install OpenDKIM, generate key, configure, integrate with Postfix, start, show DNS record."
}

{
  "fields": {
    "name": "apparmor-profile-setup",
    "description": "Create and enforce AppArmor profile",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-apparmor-utils",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y apparmor-utils",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-profile",
        "action_type": "SHELL",
        "code": "cat > /etc/apparmor.d/usr.local.bin.{{input.app_name}} <<PROF\n#include <tunables/global>\n/usr/local/bin/{{input.app_name}} {\n  #include <abstractions/base>\n  #include <abstractions/nameservice>\n  /usr/local/bin/{{input.app_name}} mr,\n  /var/log/{{input.app_name}}/** rw,\n  /tmp/{{input.app_name}}/** rw,\n  /etc/{{input.app_name}}/** r,\n  deny /etc/shadow r,\n  deny /etc/passwd w,\n}\nPROF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "app_name": {
              "type": "string"
            }
          },
          "required": [
            "app_name"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "load-profile-complain",
        "action_type": "SHELL",
        "code": "apparmor_parser -r /etc/apparmor.d/usr.local.bin.{{input.app_name}} && aa-complain /usr/local/bin/{{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enforce-profile",
        "action_type": "SHELL",
        "code": "aa-enforce /usr/local/bin/{{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-profile",
        "action_type": "SHELL",
        "code": "aa-status | grep {{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-apparmor",
        "action_type": "SHELL",
        "code": "aa-disable /usr/local/bin/{{input.app_name}} 2>/dev/null; rm -f /etc/apparmor.d/usr.local.bin.{{input.app_name}}",
        "parent_step_ids": [
          "2"
        ]
      }
