{
  "fields": {
    "name": "Build multi-platform image with buildx",
    "action_type": "ANSIBLE",
    "code": "- name: Check if buildx is available\n  command: docker buildx version\n  register: buildx_check\n  changed_when: false\n  failed_when: false\n\n- name: Create buildx builder\n  command: \"docker buildx create --name {{input.builder_name}} --use\"\n  when: buildx_check.rc == 0\n  register: builder_create\n  failed_when: false\n\n- name: Build multi-platform image\n  command: >-\n    docker buildx build\n    --platform {{input.platforms}}\n    -t {{input.image_name}}:{{input.tag}}\n    -f {{input.dockerfile}}\n    --push={{ input.push | default(\"false\") }}\n    {{input.build_context}}\n  register: build_result\n\n- name: Display build result\n  debug:\n    msg: \"Multi-platform build complete for {{ input.image_name }}:{{ input.tag }} ({{ input.platforms }})\"\n",
    "schema": {
      "input": {
        "builder_name": {
          "type": "string",
          "description": "Name for the buildx builder instance"
        },
        "image_name": {
          "type": "string",
          "description": "Image name to build"
        },
        "tag": {
          "type": "string",
          "description": "Image tag"
        },
        "platforms": {
          "type": "string",
          "description": "Comma-separated platforms (e.g. linux/amd64,linux/arm64)"
        },
        "dockerfile": {
          "type": "string",
          "description": "Path to the Dockerfile"
        },
        "build_context": {
          "type": "string",
          "description": "Build context directory"
        },
        "push": {
          "type": "string",
          "description": "Push to registry after build: true/false"
        }
      },
      "required": [
        "image_name",
        "tag",
        "platforms",
        "build_context"
      ]
    }
  },
  "explanation": "Ansible action that uses docker buildx to build a multi-platform image for amd64-arm-arm64 targets with optional registry push."
}

