{
  "fields": {
    "name": "Configure DNS resolver",
    "action_type": "ANSIBLE",
    "code": "- name: Configure /etc/resolv.conf\n  copy:\n    dest: /etc/resolv.conf\n    content: |\n      # Managed by Ansible\n      search {{input.search_domain}}\n      nameserver {{input.primary_dns}}\n      nameserver {{input.secondary_dns}}\n      options timeout:2 attempts:3\n    owner: root\n    group: root\n    mode: \"0644\"\n    backup: yes\n\n- name: Test DNS resolution\n  command: \"nslookup {{input.test_domain}} {{input.primary_dns}}\"\n  register: dns_test\n  changed_when: false\n  failed_when: dns_test.rc != 0\n",
    "schema": {
      "input": {
