        "code": "cat > /etc/systemd/system/gunicorn.service <<SVC\n[Unit]\nDescription=Gunicorn Flask\nAfter=network.target\n[Service]\nUser=www-data\nWorkingDirectory={{input.app_dir}}\nExecStart={{input.venv_dir}}/bin/gunicorn -w {{input.workers}} -b 0.0.0.0:8000 wsgi:app\nRestart=always\n[Install]\nWantedBy=multi-user.target\nSVC",
