  "fields": {
    "name": "OAuth token refresh for keycloak",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport urllib.parse\nimport sys\n\ntoken_url = \"{{input.token_url}}\"\nclient_id = \"{{input.client_id}}\"\nclient_secret = \"{{input.client_secret}}\"\nrefresh_token = \"{{input.refresh_token}}\"\n\ndata = urllib.parse.urlencode({{\n    \"grant_type\": \"refresh_token\",\n    \"client_id\": client_id,\n    \"client_secret\": client_secret,\n    \"refresh_token\": refresh_token,\n}}).encode(\"utf-8\")\n\nreq = urllib.request.Request(token_url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/x-www-form-urlencoded\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    tokens = json.loads(resp.read().decode())\n    print(json.dumps({{\n        \"status\": \"refreshed\",\n        \"access_token\": tokens.get(\"access_token\", \"\")[:10] + \"...\",\n        \"expires_in\": tokens.get(\"expires_in\"),\n    }}))\nexcept urllib.error.HTTPError as e:\n    print(json.dumps({{\"status\": \"error\", \"code\": e.code, \"message\": e.read().decode()}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "token_url": {
          "type": "string",
          "description": "OAuth token endpoint URL"
        },
        "client_id": {
          "type": "string",
          "description": "OAuth client ID"
        },
        "client_secret": {
          "type": "string",
          "description": "OAuth client secret"
        },
        "refresh_token": {
          "type": "string",
          "description": "Refresh token"
        }
      },
      "required": [
        "token_url",
        "client_id",
        "client_secret",
        "refresh_token"
      ]
    }
  },
  "explanation": "Python action that refreshes an OAuth2 access token using a refresh token grant against keycloak token endpoint."
}

