{
  "fields": {
    "name": "Gracefully stop redis",
    "action_type": "ANSIBLE",
    "code": "- name: Check if {{input.service_name}} is running
  command: "systemctl is-active {{input.service_name}}"
  register: is_active
  changed_when: false
  failed_when: false

- name: Gracefully stop {{input.service_name}}
  systemd:
    name: "{{input.service_name}}"
    state: stopped
  when: is_active.rc == 0

- name: Disable {{input.service_name}} on boot
  systemd:
    name: "{{input.service_name}}"
    enabled: no
  when: input.disable_on_boot is defined and input.disable_on_boot == "true"

- name: Verify {{input.service_name}} is stopped
  command: "systemctl is-active {{input.service_name}}"
  register: verify_stopped
  changed_when: false
  failed_when: verify_stopped.rc == 0
",
    "schema": {
      "input": {
        "service_name": {
          "type": "string",
          "description": "Service name to stop"
        },
        "disable_on_boot": {
          "type": "string",
          "description": "Also disable on boot: true/false"
        }
      },
      "required": [
        "service_name"
      ]
    }
  },
  "explanation": "Ansible action that gracefully stops redis, optionally disables it, and verifies it is no longer running."
}

