{
  "fields": {
    "name": "Decode JWT token",
    "action_type": "PYTHON",
    "code": "import json
import base64
import sys

token = "{{input.token}}"

parts = token.split(".")
if len(parts) != 3:
    print(json.dumps({{"status": "error", "message": "Invalid JWT format"}}))
    sys.exit(1)

def decode_part(part):
    padding = 4 - len(part) % 4
    part += "=" * padding
    return json.loads(base64.urlsafe_b64decode(part).decode("utf-8"))

try:
    header = decode_part(parts[0])
    payload = decode_part(parts[1])
    import time
    exp = payload.get("exp")
    expired = exp is not None and exp < time.time()
    print(json.dumps({{
        "status": "ok",
        "header": header,
        "payload": payload,
        "expired": expired,
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "token": {
          "type": "string",
          "description": "JWT token string to decode"
        }
      },
      "required": [
        "token"
      ]
    }
  },
  "explanation": "Python action that decodes a auth JWT token header and payload using base64, checking expiration."
}

{
  "fields": {
    "name": "Count nginx processes",
    "action_type": "PYTHON",
    "code": "import json
import os
import sys

process_name = "{{input.process_name}}"
min_count = int("{{input.min_count}}" or "1")

count = 0
pids = []
for pid in os.listdir("/proc"):
    if not pid.isdigit():
        continue
    try:
        with open(f"/proc/{{pid}}/comm", "r") as f:
            comm = f.read().strip()
        if process_name in comm:
            count += 1
            pids.append(int(pid))
    except (IOError, OSError):
        continue

result = {{
    "process": process_name,
    "count": count,
    "pids": pids[:20],
    "min_expected": min_count,
    "status": "ok" if count >= min_count else "critical",
}}
print(json.dumps(result))
if count < min_count:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "process_name": {
          "type": "string",
          "description": "Process name to search for"
        },
        "min_count": {
          "type": "string",
          "description": "Minimum expected process count (default 1)"
        }
      },
      "required": [
        "process_name"
      ]
    }
  },
  "explanation": "Python action that counts running nginx processes by scanning /proc and alerts if count is below minimum."
}

