{
  "fields": {
    "name": "canary-single-server",
    "description": "Canary deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "deploy-canary",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git stash && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "canary_port": {
              "type": "string"
            },
            "prod_port": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "canary_port",
            "prod_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-canary",
        "action_type": "SHELL",
        "code": "PORT={{input.canary_port}} node {{input.app_dir}}/server.js &",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "canary-health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:{{input.canary_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "route-canary-traffic",
        "action_type": "SHELL",
        "code": "sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}} weight=9;\\n    server 127.0.0.1:{{input.canary_port}} weight=1;/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "monitor-errors",
        "action_type": "SHELL",
        "code": "sleep 30 && ERROR_RATE=$(tail -100 /var/log/nginx/access.log | grep -c \" 5[0-9][0-9] \") && test \"$ERROR_RATE\" -lt 5",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": false,
        "name": "promote-canary",
        "action_type": "SHELL",
        "code": "systemctl restart app && kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}};/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-canary",
        "action_type": "SHELL",
        "code": "kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; cd {{input.app_dir}} && git stash pop; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Canary: deploy new version on alternate port, route 10% traffic, monitor errors, promote or rollback."
}

{
  "fields": {
    "name": "auto-security-updates",
    "description": "Enable automatic security updates",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-unattended",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y unattended-upgrades apt-listchanges",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "enable-auto-updates",
        "action_type": "SHELL",
        "code": "cat > /etc/apt/apt.conf.d/20auto-upgrades <<CONF\nAPT::Periodic::Update-Package-Lists \"1\";\nAPT::Periodic::Unattended-Upgrade \"1\";\nAPT::Periodic::AutocleanInterval \"7\";\nCONF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-security-only",
        "action_type": "SHELL",
        "code": "sed -i \"s|//.*\"\\${distro_id}:${distro_codename}-security\"|\\t\"${distro_id}:${distro_codename}-security\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enable-email-notify",
        "action_type": "SHELL",
        "code": "sed -i \"s|//Unattended-Upgrade::Mail \"\"|Unattended-Upgrade::Mail \"{{input.admin_email}}\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "schema": {
          "input": {
            "admin_email": {
              "type": "string"
            }
          },
          "required": [
            "admin_email"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "dry-run-test",
        "action_type": "SHELL",
        "code": "unattended-upgrade --dry-run --debug",
        "target": "all",
        "parent_step_ids": [
          "3",
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-auto-updates",
        "action_type": "SHELL",
        "code": "rm -f /etc/apt/apt.conf.d/20auto-upgrades; apt-get remove -y unattended-upgrades",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Auto updates: install unattended-upgrades, enable periodic updates, security-only, email notify, dry-run test."
}

{
  "fields": {
    "name": "deploy-pgbouncer",
    "description": "Deploy PgBouncer connection pooler",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-pgbouncer",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y pgbouncer",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-pgbouncer",
        "action_type": "SHELL",
        "code": "cat > /etc/pgbouncer/pgbouncer.ini <<INI\n[databases]\n{{input.db_name}} = host=127.0.0.1 port=5432 dbname={{input.db_name}}\n[pgbouncer]\nlisten_addr = 127.0.0.1\nlisten_port = 6432\nauth_type = md5\nauth_file = /etc/pgbouncer/userlist.txt\npool_mode = transaction\nmax_client_conn = {{input.max_clients}}\ndefault_pool_size = {{input.pool_size}}\nINI",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "db_name": {
              "type": "string"
            },
            "db_user": {
              "type": "string"
            },
            "db_pass": {
              "type": "string"
            },
            "max_clients": {
              "type": "string"
            },
            "pool_size": {
              "type": "string"
            }
          },
          "required": [
            "db_name",
            "db_user",
            "db_pass",
            "max_clients",
            "pool_size"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "write-userlist",
        "action_type": "SHELL",
        "code": "echo \"\"{{input.db_user}}\" \"{{input.db_pass}}\"\" > /etc/pgbouncer/userlist.txt && chmod 640 /etc/pgbouncer/userlist.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl enable --now pgbouncer",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-pgbouncer",
        "action_type": "SHELL",
        "code": "psql -h 127.0.0.1 -p 6432 -U {{input.db_user}} {{input.db_name}} -c \"SELECT 1\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl stop pgbouncer; apt-get remove -y pgbouncer",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "PgBouncer: install, configure pool, write userlist, start, verify connectivity."
}

{
  "fields": {
    "name": "deploy-mongodb",
    "description": "Deploy MongoDB with auth enabled",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "import-mongo-key",
        "action_type": "SHELL",
        "code": "curl -fsSL https://pgp.mongodb.com/server-7.0.asc | gpg --dearmor -o /usr/share/keyrings/mongodb-server-7.0.gpg",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-mongo-repo",
        "action_type": "SHELL",
        "code": "echo \"deb [signed-by=/usr/share/keyrings/mongodb-server-7.0.gpg] https://repo.mongodb.org/apt/ubuntu jammy/mongodb-org/7.0 multiverse\" > /etc/apt/sources.list.d/mongodb-org-7.0.list && apt-get update",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-mongodb",
        "action_type": "SHELL",
        "code": "apt-get install -y mongodb-org",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-mongodb",
        "action_type": "SHELL",
        "code": "systemctl enable --now mongod",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "create-admin-user",
        "action_type": "SHELL",
        "code": "mongosh --eval \"use admin; db.createUser({user:\"{{input.admin_user}}\",pwd:\"{{input.admin_pass}}\",roles:[\"root\"]})\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "schema": {
          "input": {
            "admin_user": {
              "type": "string"
            },
            "admin_pass": {
              "type": "string"
            }
          },
          "required": [
            "admin_user",
            "admin_pass"
          ]
        }
      },
      {
        "id": "6",
        "undo": false,
        "name": "enable-auth",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#security:/security:\\n  authorization: enabled/\" /etc/mongod.conf && systemctl restart mongod",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-mongodb",
        "action_type": "SHELL",
        "code": "mongosh -u {{input.admin_user}} -p {{input.admin_pass}} --authenticationDatabase admin --eval \"db.runCommand({ping:1})\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-mongodb",
        "action_type": "SHELL",
        "code": "systemctl stop mongod; apt-get remove -y mongodb-org",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "MongoDB: import key, add repo, install, start, create admin, enable auth, verify."
}

