{
  "fields": {
    "name": "Override limits for redis",
    "action_type": "ANSIBLE",
    "code": "- name: Create systemd override directory for {{input.service_name}}\n  file:\n    path: \"/etc/systemd/system/{{input.service_name}}.service.d\"\n    state: directory\n    mode: \"0755\"\n\n- name: Deploy limits override for {{input.service_name}}\n  copy:\n    dest: \"/etc/systemd/system/{{input.service_name}}.service.d/limits.conf\"\n    content: |\n      [Service]\n      LimitNOFILE={{input.limit_nofile}}\n      LimitNPROC={{input.limit_nproc}}\n      LimitMEMLOCK={{input.limit_memlock}}\n    mode: \"0644\"\n  notify: reload systemd and restart service\n\n- name: Reload systemd daemon\n  systemd:\n    daemon_reload: yes\n\n- name: Restart {{input.service_name}} to apply limits\n  systemd:\n    name: \"{{input.service_name}}\"\n    state: restarted\n",
    "schema": {
      "input": {
        "service_name": {
          "type": "string",
          "description": "Service name to set limits for"
        },
        "limit_nofile": {
          "type": "string",
          "description": "Max open files limit (e.g. 65536)"
        },
        "limit_nproc": {
          "type": "string",
          "description": "Max processes limit (e.g. 4096)"
        },
        "limit_memlock": {
          "type": "string",
          "description": "Max locked memory (e.g. infinity, 67108864)"
        }
      },
      "required": [
        "service_name",
        "limit_nofile"
      ]
    }
  },
  "explanation": "Ansible action that creates a systemd drop-in override to set file, process, and memory limits for redis."
}

