{
  "fields": {
    "name": "Collect disk I/O metrics",
    "action_type": "PYTHON",
    "code": "import json
import sys

device = "{{input.device}}" or "sda"

def read_diskstats(dev):
    with open("/proc/diskstats", "r") as f:
        for line in f:
            parts = line.split()
            if len(parts) >= 14 and parts[2] == dev:
                return {{
                    "reads_completed": int(parts[3]),
                    "reads_merged": int(parts[4]),
                    "sectors_read": int(parts[5]),
                    "read_time_ms": int(parts[6]),
                    "writes_completed": int(parts[7]),
                    "writes_merged": int(parts[8]),
                    "sectors_written": int(parts[9]),
                    "write_time_ms": int(parts[10]),
                    "io_in_progress": int(parts[11]),
                    "io_time_ms": int(parts[12]),
                }}
    return None

stats = read_diskstats(device)
if stats is None:
    print(json.dumps({{"status": "error", "message": f"Device {{device}} not found"}}))
    sys.exit(1)

stats["device"] = device
stats["status"] = "ok"
print(json.dumps(stats))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "device": {
          "type": "string",
          "description": "Disk device name (default sda)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/diskstats to collect I/O metrics for disk device sda."
}

{
  "fields": {
    "name": "Expand environment variables",
    "action_type": "PYTHON",
    "code": "import os
import re
import json
import sys

input_path = "{{input.input_path}}"
output_path = "{{input.output_path}}"
strict = "{{input.strict}}" == "true"

def expand_env(text, strict_mode):
    missing = []
    def replacer(match):
        var = match.group(1) or match.group(2)
        value = os.environ.get(var)
        if value is None:
            missing.append(var)
            return match.group(0) if not strict_mode else ""
        return value
    expanded = re.sub(r"\$\{{(\w+)\}}|\$(\w+)", replacer, text)
    return expanded, missing

try:
    with open(input_path, "r") as f:
        content = f.read()

    expanded, missing = expand_env(content, strict)

    if strict and missing:
        print(json.dumps({{"status": "error", "missing_vars": missing}}))
        sys.exit(1)

    with open(output_path, "w") as f:
        f.write(expanded)

    print(json.dumps({{
        "status": "expanded",
        "output": output_path,
        "missing_vars": missing,
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "input_path": {
          "type": "string",
          "description": "Path to template file with $VAR or ${VAR} references"
        },
        "output_path": {
          "type": "string",
          "description": "Path for expanded output"
        },
        "strict": {
          "type": "string",
          "description": "Fail on missing vars: true/false (default false)"
        }
      },
      "required": [
        "input_path",
        "output_path"
      ]
    }
  },
  "explanation": "Python action that expands environment variable references in a docker-compose file, optionally failing on missing variables."
}

