{
  "fields": {
    "name": "Merge YAML config files",
    "action_type": "PYTHON",
    "code": "import json
import sys
import re

def simple_yaml_parse(text):
    """Minimal YAML parser for flat and one-level nested key-value pairs."""
    result = {{}}
    current_key = None
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        indent = len(line) - len(line.lstrip())
        match = re.match(r"^(\w[\w.-]*):\s*(.*)", stripped)
        if match:
            key, val = match.group(1), match.group(2).strip()
            if indent == 0:
                if val:
                    result[key] = val
                else:
                    result[key] = {{}}
                    current_key = key
            elif current_key:
                result[current_key][key] = val
    return result

def deep_merge(base, override):
    merged = dict(base)
    for k, v in override.items():
        if k in merged and isinstance(merged[k], dict) and isinstance(v, dict):
            merged[k] = deep_merge(merged[k], v)
        else:
            merged[k] = v
    return merged

base_path = "{{input.base_file}}"
override_path = "{{input.override_file}}"
output_path = "{{input.output_file}}"

try:
    with open(base_path) as f:
        base = simple_yaml_parse(f.read())
    with open(override_path) as f:
        override = simple_yaml_parse(f.read())
    merged = deep_merge(base, override)
    with open(output_path, "w") as f:
        for k, v in merged.items():
            if isinstance(v, dict):
                f.write(f"{{k}}:\n")
                for sk, sv in v.items():
                    f.write(f"  {{sk}}: {{sv}}\n")
            else:
                f.write(f"{{k}}: {{v}}\n")
    print(json.dumps({{"status": "merged", "output": output_path, "keys": len(merged)}}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "base_file": {
          "type": "string",
          "description": "Path to base YAML file"
        },
        "override_file": {
          "type": "string",
          "description": "Path to override YAML file"
        },
        "output_file": {
          "type": "string",
          "description": "Path for merged output"
        }
      },
      "required": [
        "base_file",
        "override_file",
        "output_file"
      ]
    }
  },
  "explanation": "Python action that deep-merges two deployment YAML configuration files, with the override file taking precedence."
}

