    "code": "import json\nimport urllib.request\nimport sys\n\napi_url = \"{{input.api_url}}\"\napi_key = \"{{input.api_key}}\"\n\nreq = urllib.request.Request(api_url, method=\"GET\")\nreq.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    data = json.loads(resp.read().decode())\n    buckets = data if isinstance(data, list) else data.get(\"buckets\", data.get(\"items\", []))\n    print(json.dumps({{\"status\": \"ok\", \"count\": len(buckets), \"buckets\": buckets}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "api_url": {
          "type": "string",
          "description": "Storage API list endpoint"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        }
      },
      "required": [
        "api_url",
        "api_key"
      ]
    }
  },
  "explanation": "Python action that queries backblaze storage API to list all available buckets."
}

{
  "fields": {
    "name": "Send Discord webhook message",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nwebhook_url = \"{{input.webhook_url}}\"\ntitle = \"{{input.title}}\"\nmessage = \"{{input.message}}\"\ncolor = int(\"{{input.color}}\" or \"3066993\")\n\npayload = {{\n    \"embeds\": [{{\n        \"title\": title,\n        \"description\": message,\n        \"color\": color,\n        \"footer\": {{\"text\": \"Dimensigon Automation\"}},\n    }}],\n}}\n\ndata = json.dumps(payload).encode(\"utf-8\")\nreq = urllib.request.Request(webhook_url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=15)\n    print(json.dumps({{\"status\": \"sent\", \"code\": resp.getcode()}}))\nexcept urllib.error.HTTPError as e:\n    if e.code == 204:\n        print(json.dumps({{\"status\": \"sent\", \"code\": 204}}))\n    else:\n        print(json.dumps({{\"status\": \"error\", \"code\": e.code}}))\n        sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "webhook_url": {
          "type": "string",
          "description": "Discord webhook URL"
        },
        "title": {
          "type": "string",
          "description": "Embed title"
        },
        "message": {
          "type": "string",
          "description": "Embed description/message"
        },
        "color": {
          "type": "string",
          "description": "Embed color as decimal integer (default green)"
        }
      },
      "required": [
        "webhook_url",
        "title",
        "message"
      ]
    }
  },
  "explanation": "Python action that sends a alert notification to Discord using a webhook with embedded message formatting."
}

