{
  "fields": {
    "name": "API version check for microservice",
    "action_type": "PYTHON",
    "code": "import json
import urllib.request
import sys

url = "{{input.url}}"
expected_version = "{{input.expected_version}}"
version_field = "{{input.version_field}}" or "version"

req = urllib.request.Request(url, method="GET")
req.add_header("Accept", "application/json")
if "{{input.api_key}}":
    req.add_header("Authorization", "Bearer {{input.api_key}}")
try:
    resp = urllib.request.urlopen(req, timeout=15)
    data = json.loads(resp.read().decode())
    actual_version = str(data.get(version_field, ""))
    if not actual_version:
        for key in data:
            if "version" in key.lower():
                actual_version = str(data[key])
                break
    match = actual_version == expected_version
    print(json.dumps({{
        "status": "ok" if match else "mismatch",
        "expected": expected_version,
        "actual": actual_version,
        "match": match,
    }}))
    if not match:
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "API version endpoint URL"
        },
        "expected_version": {
          "type": "string",
          "description": "Expected API version string"
        },
        "version_field": {
          "type": "string",
          "description": "JSON field containing the version (default: version)"
        },
        "api_key": {
          "type": "string",
          "description": "Bearer token for auth (optional)"
        }
      },
      "required": [
        "url",
        "expected_version"
      ]
    }
  },
  "explanation": "Python action that checks the deployed microservice API version against an expected value for deployment verification."
}

