    "name": "postfix-mail-server",
    "description": "Postfix mail server setup",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-postfix",
        "action_type": "SHELL",
        "code": "DEBIAN_FRONTEND=noninteractive apt-get install -y postfix",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"myhostname={{input.hostname}}\" && postconf -e \"mydomain={{input.domain}}\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "hostname": {
              "type": "string"
            },
            "domain": {
              "type": "string"
            }
          },
          "required": [
            "hostname",
            "domain"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "restart-postfix",
        "action_type": "SHELL",
        "code": "systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-smtp",
        "action_type": "SHELL",
        "code": "echo \"QUIT\" | nc localhost 25 | grep -q \"220\"",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": true,
        "name": "undo-postfix",
        "action_type": "SHELL",
        "code": "systemctl stop postfix; apt-get remove -y postfix",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Postfix: install, configure hostname/domain, restart, verify SMTP."
}

{
  "fields": {
    "name": "test-runner-notify",
    "description": "Run test suite and send notification",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "webhook_url": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "webhook_url"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pip install -r requirements.txt",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pytest --junitxml=/tmp/test-results.xml 2>&1 | tee /tmp/test-output.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "notify-success",
        "action_type": "SHELL",
        "code": "PASS=$(grep -c \"passed\" /tmp/test-output.txt); curl -sf -X POST {{input.webhook_url}} -H \"Content-Type: application/json\" -d \"{\"text\":\"Tests passed: $PASS tests on {{input.branch}}\"}\"",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": true,
        "name": "notify-failure",
        "action_type": "SHELL",
        "code": "FAIL=$(tail -5 /tmp/test-output.txt); curl -sf -X POST {{input.webhook_url}} -H \"Content-Type: application/json\" -d \"{\"text\":\"Tests FAILED on {{input.branch}}: $FAIL\"}\"",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Test runner: pull, install deps, run pytest with XML report, notify webhook on success/failure."
}

{
  "fields": {
    "name": "Create Azure VM",
    "action_type": "ANSIBLE",
    "code": "- name: Create Azure VM {{input.vm_name}}\n  azure.azcollection.azure_rm_virtualmachine:\n    resource_group: \"{{input.resource_group}}\"\n    name: \"{{input.vm_name}}\"\n    vm_size: \"{{input.vm_size}}\"\n    admin_username: \"{{input.admin_username}}\"\n    ssh_password_enabled: false\n    ssh_public_keys:\n      - path: \"/home/{{input.admin_username}}/.ssh/authorized_keys\"\n        key_data: \"{{input.ssh_key}}\"\n    image:\n      offer: \"{{input.image_offer}}\"\n      publisher: \"{{input.image_publisher}}\"\n      sku: \"{{input.image_sku}}\"\n      version: latest\n    state: present\n",
    "schema": {
      "input": {
        "resource_group": {
          "type": "string",
          "description": "Azure resource group"
        },
        "vm_name": {
          "type": "string",
          "description": "Virtual machine name"
        },
        "vm_size": {
          "type": "string",
          "description": "VM size (e.g. Standard_B2s)"
        },
        "admin_username": {
          "type": "string",
          "description": "Admin username"
        },
        "ssh_key": {
          "type": "string",
          "description": "SSH public key data"
        },
        "image_offer": {
          "type": "string",
          "description": "Image offer (e.g. UbuntuServer)"
        },
        "image_publisher": {
          "type": "string",
          "description": "Image publisher (e.g. Canonical)"
        },
        "image_sku": {
          "type": "string",
          "description": "Image SKU (e.g. 22_04-lts)"
        }
      },
      "required": [
        "resource_group",
        "vm_name",
        "vm_size",
        "admin_username"
      ]
    }
  },
  "explanation": "Ansible action that provisions an Azure Standard_D2s_v3 virtual machine with SSH key authentication and marketplace image."
}

