{
  "fields": {
    "name": "Check mysql replication status",
    "action_type": "PYTHON",
    "code": "import json\nimport socket\nimport sys\n\nprimary_host = \"{{input.primary_host}}\"\nprimary_port = int(\"{{input.primary_port}}\")\nreplica_host = \"{{input.replica_host}}\"\nreplica_port = int(\"{{input.replica_port}}\")\ntimeout = int(\"{{input.timeout}}\" or \"5\")\n\nresults = {{}}\nfor label, host, port in [(\"primary\", primary_host, primary_port), (\"replica\", replica_host, replica_port)]:\n    try:\n        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n        sock.settimeout(timeout)\n        result = sock.connect_ex((host, port))\n        sock.close()\n        results[label] = {{\"host\": host, \"port\": port, \"reachable\": result == 0}}\n    except Exception as e:\n        results[label] = {{\"host\": host, \"port\": port, \"reachable\": False, \"error\": str(e)}}\n\nboth_up = results.get(\"primary\", {{}}).get(\"reachable\", False) and results.get(\"replica\", {{}}).get(\"reachable\", False)\noutput = {{\n    \"status\": \"ok\" if both_up else \"error\",\n    \"primary\": results.get(\"primary\", {{}}),\n    \"replica\": results.get(\"replica\", {{}}),\n}}\nprint(json.dumps(output))\nif not both_up:\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "primary_host": {
          "type": "string",
          "description": "Primary/master database host"
        },
        "primary_port": {
          "type": "string",
          "description": "Primary database port"
        },
        "replica_host": {
          "type": "string",
          "description": "Replica/slave database host"
        },
        "replica_port": {
          "type": "string",
          "description": "Replica database port"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 5)"
        }
      },
      "required": [
        "primary_host",
        "primary_port",
        "replica_host",
        "replica_port"
      ]
    }
  },
  "explanation": "Python action that checks mysql replication status by verifying connectivity to both the primary and replica instances."
}

{
  "fields": {
    "name": "canary-single-server",
    "description": "Canary deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "deploy-canary",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git stash && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "canary_port": {
              "type": "string"
            },
            "prod_port": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "canary_port",
            "prod_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-canary",
        "action_type": "SHELL",
        "code": "PORT={{input.canary_port}} node {{input.app_dir}}/server.js &",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "canary-health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:{{input.canary_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "route-canary-traffic",
        "action_type": "SHELL",
        "code": "sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}} weight=9;\\n    server 127.0.0.1:{{input.canary_port}} weight=1;/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "monitor-errors",
        "action_type": "SHELL",
        "code": "sleep 30 && ERROR_RATE=$(tail -100 /var/log/nginx/access.log | grep -c \" 5[0-9][0-9] \") && test \"$ERROR_RATE\" -lt 5",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": false,
        "name": "promote-canary",
        "action_type": "SHELL",
        "code": "systemctl restart app && kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}};/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-canary",
        "action_type": "SHELL",
        "code": "kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; cd {{input.app_dir}} && git stash pop; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Canary: deploy new version on alternate port, route 10% traffic, monitor errors, promote or rollback."
}

