    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "PostgreSQL host address"
        },
        "admin_user": {
          "type": "string",
          "description": "Admin user with CREATEROLE privilege"
        },
        "new_user": {
          "type": "string",
          "description": "Username for the new role"
        },
        "password": {
          "type": "string",
          "description": "Password for the new role"
        },
        "database": {
          "type": "string",
          "description": "Database to grant access to"
        },
        "privileges": {
          "type": "string",
          "description": "Privileges to grant (e.g. SELECT, SELECT,INSERT,UPDATE,DELETE, ALL)"
        }
      },
      "required": [
        "host",
        "admin_user",
        "new_user",
        "password",
        "database",
        "privileges"
      ]
    }
  },
  "explanation": "Creates a PostgreSQL user in the staging environment with specified database privileges and default grants."
}

