    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "clean-tmp-old",
        "action_type": "SHELL",
        "code": "find /tmp -type f -mtime +{{input.days_old}} -delete 2>/dev/null; find /tmp -type d -empty -mtime +{{input.days_old}} -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "days_old": {
              "type": "string"
            }
          },
          "required": [
            "days_old"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clean-var-tmp",
        "action_type": "SHELL",
