{
  "fields": {
    "name": "log-alerting",
    "description": "Set up log-based alerting",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-alert-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/log-alert.sh <<SCRIPT\n#!/bin/bash\nPATTERN=\"{{input.alert_pattern}}\"\nLOGFILE=\"{{input.log_path}}\"\nERRORS=$(tail -100 \"$LOGFILE\" | grep -c \"$PATTERN\")\nif [ \"$ERRORS\" -gt {{input.threshold}} ]; then\n  echo \"ALERT: $ERRORS matches for $PATTERN in $LOGFILE\" | logger -t log-alert\nfi\nSCRIPT\nchmod +x /usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/5 * * * * /usr/local/bin/log-alert.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-alert-script",
        "action_type": "SHELL",
        "code": "/usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": true,
        "name": "undo-log-alerting",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v log-alert | crontab - && rm -f /usr/local/bin/log-alert.sh",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Log alerting: create alert script, add cron, test. Matches pattern in log and fires syslog alert."
}

{
  "fields": {
    "name": "private-registry",
    "description": "Deploy private Docker registry",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-registry-dirs",
        "action_type": "SHELL",
        "code": "mkdir -p /opt/registry/data /opt/registry/auth /opt/registry/certs",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-htpasswd",
        "action_type": "SHELL",
        "code": "docker run --rm --entrypoint htpasswd httpd:2 -Bbn {{input.reg_user}} {{input.reg_pass}} > /opt/registry/auth/htpasswd",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "reg_user": {
              "type": "string"
            },
            "reg_pass": {
              "type": "string"
            },
            "reg_port": {
              "type": "string"
            }
          },
          "required": [
            "reg_user",
            "reg_pass",
            "reg_port"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-registry",
        "action_type": "SHELL",
        "code": "docker run -d --name registry --restart unless-stopped -p {{input.reg_port}}:5000 -v /opt/registry/data:/var/lib/registry -v /opt/registry/auth:/auth -e REGISTRY_AUTH=htpasswd -e REGISTRY_AUTH_HTPASSWD_REALM=\"Registry Realm\" -e REGISTRY_AUTH_HTPASSWD_PATH=/auth/htpasswd registry:2",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-registry",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf -u {{input.reg_user}}:{{input.reg_pass}} http://localhost:{{input.reg_port}}/v2/_catalog",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "test-push-pull",
        "action_type": "SHELL",
        "code": "docker pull alpine:latest && docker tag alpine:latest localhost:{{input.reg_port}}/test-alpine && docker push localhost:{{input.reg_port}}/test-alpine && docker rmi localhost:{{input.reg_port}}/test-alpine",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-registry",
        "action_type": "SHELL",
        "code": "docker stop registry 2>/dev/null; docker rm registry 2>/dev/null; rm -rf /opt/registry",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Private registry: create dirs, generate htpasswd, start registry container, verify API, test push+pull."
}

