{
  "fields": {
    "name": "Install rake via gem",
    "action_type": "ANSIBLE",
    "code": "- name: Ensure Ruby is installed
  package:
    name:
      - ruby
      - ruby-dev
    state: present

- name: Install {{input.package}} gem
  gem:
    name: "{{input.package}}"
    version: "{{input.version}}"
    state: present
    user_install: no
  when: input.version is defined and input.version != ""

- name: Install {{input.package}} gem (latest)
  gem:
    name: "{{input.package}}"
    state: latest
    user_install: no
  when: input.version is not defined or input.version == ""

- name: Verify gem installation
  command: "gem list {{input.package}}"
  register: gem_check
  changed_when: false
",
    "schema": {
      "input": {
        "package": {
          "type": "string",
          "description": "Ruby gem name"
        },
        "version": {
          "type": "string",
          "description": "Gem version (optional)"
        }
      },
      "required": [
        "package"
      ]
    }
  },
  "explanation": "Ansible action that installs the rake Ruby gem system-wide with optional version pinning."
}

