        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm ci",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "test-new-slot",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm test",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "switch-symlink",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && ln -sfn {{input.app_dir}}/$SLOT {{input.app_dir}}/current",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-app",
        "action_type": "SHELL",
        "code": "systemctl restart app",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "health-check",
