}

{
  "fields": {
    "name": "db-migration-pipeline",
    "description": "CI pipeline with database migration",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "db_name": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "db_name"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "backup-database",
        "action_type": "SHELL",
        "code": "sudo -u postgres pg_dump {{input.db_name}} > /tmp/{{input.db_name}}_pre_ci.sql",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pip install -r requirements.txt",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-migrations",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && python manage.py migrate --noinput",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && python manage.py test --noinput",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-app",
        "action_type": "SHELL",
        "code": "systemctl restart gunicorn",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": true,
        "name": "undo-db-migration-ci",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql {{input.db_name}} < /tmp/{{input.db_name}}_pre_ci.sql && cd {{input.app_dir}} && git checkout HEAD~1 && systemctl restart gunicorn",
        "parent_step_ids": [
          "2"
        ]
      }
    ]
  },
  "explanation": "DB migration CI: pull, backup DB + install deps in parallel, migrate, test, restart. Restores DB on failure."
}

{
  "fields": {
    "name": "container-log-collect",
    "description": "Set up centralized container log collection",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "configure-log-driver",
        "action_type": "SHELL",
        "code": "cat > /etc/docker/daemon.json <<JSON\n{\n  \"log-driver\": \"json-file\",\n  \"log-opts\": {\n    \"max-size\": \"{{input.max_size}}\",\n    \"max-file\": \"{{input.max_files}}\"\n  }\n}\nJSON",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "max_size": {
              "type": "string"
            },
            "max_files": {
              "type": "string"
            }
          },
          "required": [
            "max_size",
            "max_files"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "restart-docker",
        "action_type": "SHELL",
        "code": "systemctl restart docker",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "deploy-log-aggregator",
        "action_type": "SHELL",
        "code": "docker run -d --name log-aggregator --restart unless-stopped -v /var/lib/docker/containers:/var/lib/docker/containers:ro -v /var/run/docker.sock:/var/run/docker.sock:ro -p 24224:24224 fluent/fluentd:v1.16-1",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-log-driver",
        "action_type": "SHELL",
        "code": "docker info --format \"{{.LoggingDriver}}\" | grep json-file",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-aggregator",
        "action_type": "SHELL",
        "code": "sleep 3 && docker logs log-aggregator 2>&1 | head -3",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-log-collection",
        "action_type": "SHELL",
        "code": "docker stop log-aggregator 2>/dev/null; docker rm log-aggregator 2>/dev/null; rm /etc/docker/daemon.json; systemctl restart docker",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Container logs: configure JSON log driver with rotation, restart Docker, deploy fluentd aggregator, verify."
}

{
  "fields": {
    "name": "auto-security-updates",
    "description": "Enable automatic security updates",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-unattended",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y unattended-upgrades apt-listchanges",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "enable-auto-updates",
        "action_type": "SHELL",
        "code": "cat > /etc/apt/apt.conf.d/20auto-upgrades <<CONF\nAPT::Periodic::Update-Package-Lists \"1\";\nAPT::Periodic::Unattended-Upgrade \"1\";\nAPT::Periodic::AutocleanInterval \"7\";\nCONF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-security-only",
        "action_type": "SHELL",
        "code": "sed -i \"s|//.*\"\\${distro_id}:${distro_codename}-security\"|\\t\"${distro_id}:${distro_codename}-security\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enable-email-notify",
        "action_type": "SHELL",
        "code": "sed -i \"s|//Unattended-Upgrade::Mail \"\"|Unattended-Upgrade::Mail \"{{input.admin_email}}\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "schema": {
          "input": {
            "admin_email": {
              "type": "string"
            }
          },
          "required": [
            "admin_email"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "dry-run-test",
        "action_type": "SHELL",
        "code": "unattended-upgrade --dry-run --debug",
        "target": "all",
        "parent_step_ids": [
          "3",
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-auto-updates",
        "action_type": "SHELL",
        "code": "rm -f /etc/apt/apt.conf.d/20auto-upgrades; apt-get remove -y unattended-upgrades",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Auto updates: install unattended-upgrades, enable periodic updates, security-only, email notify, dry-run test."
}

