{
  "fields": {
    "name": "Trigger azure-vmss auto-scale",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\napi_url = \"{{input.api_url}}\"\napi_key = \"{{input.api_key}}\"\ngroup_id = \"{{input.group_id}}\"\ndesired_count = int(\"{{input.desired_count}}\")\n\npayload = {{\"group_id\": group_id, \"desired_capacity\": desired_count}}\ndata = json.dumps(payload).encode(\"utf-8\")\nreq = urllib.request.Request(api_url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    result = json.loads(resp.read().decode())\n    print(json.dumps({{\"status\": \"scaled\", \"group\": group_id, \"desired\": desired_count}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "api_url": {
          "type": "string",
          "description": "Auto-scaling API endpoint"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        },
        "group_id": {
          "type": "string",
          "description": "Auto-scaling group ID"
        },
        "desired_count": {
          "type": "string",
          "description": "Desired instance count"
