{
  "fields": {
    "name": "full-mail-server",
    "description": "Full mail stack: Postfix + Dovecot + DKIM",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-packages",
        "action_type": "SHELL",
        "code": "DEBIAN_FRONTEND=noninteractive apt-get update && apt-get install -y postfix dovecot-imapd opendkim opendkim-tools",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"myhostname=mail.{{input.domain}}\" && postconf -e \"mydomain={{input.domain}}\" && postconf -e \"home_mailbox=Maildir/\" && postconf -e \"smtpd_tls_cert_file=/etc/letsencrypt/live/{{input.domain}}/fullchain.pem\" && postconf -e \"smtpd_tls_key_file=/etc/letsencrypt/live/{{input.domain}}/privkey.pem\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "domain": {
              "type": "string"
            },
            "dkim_selector": {
              "type": "string"
            }
          },
          "required": [
            "domain",
            "dkim_selector"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-dovecot",
        "action_type": "SHELL",
        "code": "sed -i \"s|^#*mail_location.*|mail_location = maildir:~/Maildir|\" /etc/dovecot/conf.d/10-mail.conf && sed -i \"s/^#*ssl =.*/ssl = required/\" /etc/dovecot/conf.d/10-ssl.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "generate-dkim",
        "action_type": "SHELL",
        "code": "mkdir -p /etc/opendkim/keys/{{input.domain}} && opendkim-genkey -s {{input.dkim_selector}} -d {{input.domain}} -D /etc/opendkim/keys/{{input.domain}} && chown -R opendkim:opendkim /etc/opendkim",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-dkim",
        "action_type": "SHELL",
        "code": "postconf -e \"milter_protocol = 6\" && postconf -e \"smtpd_milters = inet:localhost:8891\" && postconf -e \"non_smtpd_milters = inet:localhost:8891\"",
        "target": "all",
        "parent_step_ids": [
          "2",
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-all-services",
        "action_type": "SHELL",
        "code": "systemctl enable --now postfix dovecot opendkim",
        "target": "all",
        "parent_step_ids": [
          "3",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-smtp",
        "action_type": "SHELL",
        "code": "echo \"QUIT\" | nc localhost 25 | grep -q \"220\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": false,
        "name": "verify-imap",
        "action_type": "SHELL",
        "code": "echo \"A1 LOGOUT\" | openssl s_client -connect localhost:993 -quiet 2>/dev/null | grep -q \"OK\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "9",
        "undo": true,
        "name": "undo-mail-stack",
        "action_type": "SHELL",
        "code": "systemctl stop postfix dovecot opendkim; apt-get remove -y postfix dovecot-imapd opendkim opendkim-tools",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Full mail stack: install all packages, configure Postfix+Dovecot+DKIM in parallel, start all, verify SMTP+IMAP."
}

{
  "fields": {
    "name": "deploy-flask-gunicorn",
    "description": "Deploy Flask app with Gunicorn",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-current",
        "action_type": "SHELL",
        "code": "cp -a {{input.app_dir}} {{input.app_dir}}.bak 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "venv_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "workers": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "venv_dir",
            "branch",
            "workers"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "pull-code",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "{{input.venv_dir}}/bin/pip install -r {{input.app_dir}}/requirements.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "write-gunicorn-conf",
        "action_type": "SHELL",
        "code": "cat > /etc/systemd/system/gunicorn.service <<SVC\n[Unit]\nDescription=Gunicorn Flask\nAfter=network.target\n[Service]\nUser=www-data\nWorkingDirectory={{input.app_dir}}\nExecStart={{input.venv_dir}}/bin/gunicorn -w {{input.workers}} -b 0.0.0.0:8000 wsgi:app\nRestart=always\n[Install]\nWantedBy=multi-user.target\nSVC",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "reload-and-restart",
        "action_type": "SHELL",
        "code": "systemctl daemon-reload && systemctl enable --now gunicorn",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:8000/health",
        "target": "all",
