        "id": "7",
        "undo": true,
        "name": "undo-flask-deploy",
        "action_type": "SHELL",
        "code": "rm -rf {{input.app_dir}} && mv {{input.app_dir}}.bak {{input.app_dir}} && systemctl restart gunicorn",
        "parent_step_ids": [
          "2"
        ]
      }
    ]
  },
  "explanation": "Flask+Gunicorn: backup, pull, pip install, write systemd unit, start, health check."
}

