{
  "fields": {
    "name": "Check API key expiry",
    "action_type": "PYTHON",
    "code": "import json
import os
import sys
from datetime import datetime, timezone

key_file = "{{input.key_file}}"
max_age_days = int("{{input.max_age_days}}" or "90")

if not os.path.isfile(key_file):
    print(json.dumps({{"status": "error", "message": f"Key file not found: {{key_file}}"}}))
    sys.exit(1)

mod_time = os.path.getmtime(key_file)
mod_dt = datetime.fromtimestamp(mod_time, tz=timezone.utc)
now = datetime.now(timezone.utc)
age_days = (now - mod_dt).days
expired = age_days > max_age_days

print(json.dumps({{
    "status": "expired" if expired else "ok",
    "key_file": key_file,
    "age_days": age_days,
    "max_age_days": max_age_days,
    "last_modified": mod_dt.isoformat(),
}}))
if expired:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "key_file": {
          "type": "string",
          "description": "Path to the API key file"
        },
        "max_age_days": {
          "type": "string",
          "description": "Maximum key age in days (default 90)"
        }
      },
      "required": [
        "key_file"
      ]
    }
  },
  "explanation": "Python action that checks the age of a production-api API key file and alerts if it exceeds the maximum age."
}

