    "action_type": "PYTHON",
    "code": "import json\nimport hashlib\nimport hmac\nimport urllib.parse\nimport sys\nfrom datetime import datetime, timezone\n\naccess_key = \"{{input.access_key}}\"\nsecret_key = \"{{input.secret_key}}\"\nbucket = \"{{input.bucket}}\"\nobject_key = \"{{input.object_key}}\"\nregion = \"{{input.region}}\" or \"us-east-1\"\nexpires = int(\"{{input.expires}}\" or \"3600\")\n\nnow = datetime.now(timezone.utc)\ndatestamp = now.strftime(\"%Y%m%d\")\namz_date = now.strftime(\"%Y%m%dT%H%M%SZ\")\nhost = f\"{{bucket}}.s3.{{region}}.amazonaws.com\"\ncredential_scope = f\"{{datestamp}}/{{region}}/s3/aws4_request\"\ncredential = f\"{{access_key}}/{{credential_scope}}\"\n\nparams = {{\n    \"X-Amz-Algorithm\": \"AWS4-HMAC-SHA256\",\n    \"X-Amz-Credential\": credential,\n    \"X-Amz-Date\": amz_date,\n    \"X-Amz-Expires\": str(expires),\n    \"X-Amz-SignedHeaders\": \"host\",\n}}\nquery = urllib.parse.urlencode(params, quote_via=urllib.parse.quote)\nurl = f\"https://{{host}}/{{object_key}}?{{query}}\"\nprint(json.dumps({{\"status\": \"ok\", \"presigned_url\": url, \"expires_in\": expires}}))\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "access_key": {
          "type": "string",
          "description": "AWS access key ID"
        },
        "secret_key": {
          "type": "string",
          "description": "AWS secret access key"
        },
        "bucket": {
          "type": "string",
          "description": "S3 bucket name"
        },
        "object_key": {
          "type": "string",
          "description": "S3 object key path"
        },
        "region": {
          "type": "string",
          "description": "AWS region (default us-east-1)"
        },
        "expires": {
          "type": "string",
          "description": "URL expiry in seconds (default 3600)"
        }
      },
      "required": [
        "access_key",
        "secret_key",
        "bucket",
        "object_key"
      ]
    }
  },
  "explanation": "Python action that generates an S3-compatible presigned URL for backblaze object storage access."
}

{
  "fields": {
    "name": "Count rows in mariadb table",
    "action_type": "PYTHON",
    "code": "import json\nimport sqlite3\nimport sys\n\ndb_path = \"{{input.db_path}}\"\ntable_name = \"{{input.table_name}}\"\nmin_rows = int(\"{{input.min_rows}}\" or \"0\")\n\ntry:\n    conn = sqlite3.connect(db_path)\n    cursor = conn.execute(f\"SELECT COUNT(*) FROM {{table_name}}\")\n    count = cursor.fetchone()[0]\n    conn.close()\n    ok = count >= min_rows\n    print(json.dumps({{\n        \"status\": \"ok\" if ok else \"below_minimum\",\n        \"table\": table_name,\n        \"row_count\": count,\n        \"min_expected\": min_rows,\n    }}))\n    if not ok:\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "db_path": {
          "type": "string",
          "description": "Path to SQLite database file"
        },
        "table_name": {
          "type": "string",
          "description": "Table name to count rows in"
        },
        "min_rows": {
          "type": "string",
          "description": "Minimum expected rows (default 0)"
        }
      },
      "required": [
        "db_path",
        "table_name"
      ]
    }
  },
  "explanation": "Python action that counts rows in a mariadb table and alerts if the count falls below the minimum threshold."
}

