    "code": "import urllib.request\nimport os\nimport json\nimport sys\n\nurl = \"{{input.url}}\"\nfilepath = \"{{input.filepath}}\"\napi_key = \"{{input.api_key}}\"\n\nif not os.path.isfile(filepath):\n    print(json.dumps({{\"status\": \"error\", \"message\": f\"File not found: {{filepath}}\"}}))\n    sys.exit(1)\n\nwith open(filepath, \"rb\") as f:\n    data = f.read()\n\nreq = urllib.request.Request(url, data=data, method=\"PUT\")\nreq.add_header(\"Content-Type\", \"application/octet-stream\")\nreq.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=120)\n    print(json.dumps({{\"status\": \"uploaded\", \"code\": resp.getcode(), \"size\": len(data)}}))\nexcept urllib.error.HTTPError as e:\n    print(json.dumps({{\"status\": \"error\", \"code\": e.code, \"message\": e.read().decode()}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "Upload destination URL"
        },
        "filepath": {
          "type": "string",
          "description": "Local file path to upload"
        },
        "api_key": {
          "type": "string",
          "description": "API key for authentication"
        }
      },
      "required": [
        "url",
        "filepath",
        "api_key"
      ]
    }
  },
  "explanation": "Python action that uploads a local file to nexus via HTTP PUT with bearer token auth."
}

{
  "fields": {
    "name": "uptime-monitor-setup",
    "description": "Set up endpoint uptime monitoring",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-check-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/uptime-check.sh <<SCRIPT\n#!/bin/bash\nLOGFILE=/var/log/uptime-monitor.log\nfor URL in {{input.urls}}; do\n  STATUS=$(curl -sf -o /dev/null -w \"%%{http_code}\" --max-time 10 \"$URL\" 2>/dev/null)\n  echo \"$(date -Iseconds) $URL $STATUS\" >> $LOGFILE\n  if [ \"$STATUS\" != \"200\" ]; then\n    echo \"ALERT: $URL returned $STATUS\" | logger -t uptime-monitor\n  fi\ndone\nSCRIPT\nchmod +x /usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "urls": {
              "type": "string"
            },
            "interval_min": {
              "type": "string"
            }
          },
          "required": [
            "urls",
            "interval_min"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-log-file",
        "action_type": "SHELL",
        "code": "touch /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "add-cron-job",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/{{input.interval_min}} * * * * /usr/local/bin/uptime-check.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-initial-check",
        "action_type": "SHELL",
        "code": "/usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-log-output",
        "action_type": "SHELL",
        "code": "test -s /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-uptime-monitor",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v uptime-check | crontab - && rm -f /usr/local/bin/uptime-check.sh /var/log/uptime-monitor.log",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Uptime monitor: create check script, add cron job, run initial check, verify log."
}

