{
  "fields": {
    "name": "spamassassin-filter",
    "description": "Install and configure SpamAssassin",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-spamassassin",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y spamassassin spamc",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-spamd-user",
        "action_type": "SHELL",
        "code": "useradd -r -s /bin/false -d /var/lib/spamassassin spamd 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-rules",
        "action_type": "SHELL",
        "code": "cat > /etc/spamassassin/local.cf <<SPAM\nrewrite_header Subject [SPAM]\nrequired_score {{input.spam_score}}\nuse_bayes 1\nbayes_auto_learn 1\nSPAM",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "spam_score": {
              "type": "string"
            }
          },
          "required": [
            "spam_score"
          ]
        }
      },
      {
        "id": "4",
        "undo": false,
        "name": "update-rules",
        "action_type": "SHELL",
        "code": "sa-update",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"content_filter = smtp-amavis:[127.0.0.1]:10024\" 2>/dev/null; sed -i \"s/^ENABLED=0/ENABLED=1/\" /etc/default/spamassassin",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl enable --now spamassassin && systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-spamd",
        "action_type": "SHELL",
        "code": "echo \"Subject: Test\" | spamc -c; true",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl stop spamassassin; postconf -e \"content_filter =\"; systemctl restart postfix; apt-get remove -y spamassassin spamc",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "SpamAssassin: install, create user, configure rules + Bayes, update rules, integrate Postfix, verify."
}

{
  "fields": {
    "name": "server-root-login-alert",
    "action_type": "SHELL",
    "code": "ALERT_SCRIPT=\"/usr/local/bin/root-login-alert.sh\" && cat > \"$ALERT_SCRIPT\" <<'SCRIPT'\n#!/bin/bash\nif [ \"$PAM_USER\" = \"root\" ] && [ \"$PAM_TYPE\" = \"open_session\" ]; then\n  SUBJECT=\"Root login alert on $(hostname)\"\n  BODY=\"Root login detected\\nUser: $PAM_USER\\nRemote Host: $PAM_RHOST\\nService: $PAM_SERVICE\\nTime: $(date)\\nTTY: $PAM_TTY\"\n  echo -e \"$BODY\" | mail -s \"$SUBJECT\" \"ALERT_EMAIL\"\nfi\nSCRIPT\nsed -i \"s/ALERT_EMAIL/{{input.alert_email}}/g\" \"$ALERT_SCRIPT\" && chmod 755 \"$ALERT_SCRIPT\" && if ! grep -q \"root-login-alert\" /etc/pam.d/sshd; then echo \"session optional pam_exec.so /usr/local/bin/root-login-alert.sh\" >> /etc/pam.d/sshd; fi && echo \"Root login email alert configured ({{input.alert_email}})\"",
    "expected_rc": 0,
    "schema": {
      "input": {
        "alert_email": {
          "type": "string",
          "description": "Email address to receive root login alerts"
        }
      },
      "required": [
        "alert_email"
      ]
    }
  },
  "explanation": "Configures a PAM-based email alert on the server that sends a notification whenever root logs in via SSH."
}

