    "code": "- name: Get {{input.container_name}} status\n  command: \"docker inspect --format='{{.State.Status}}'  {{input.container_name}}\"\n  register: container_status\n  changed_when: false\n  failed_when: false\n\n- name: Assert container is running\n  assert:\n    that:\n      - container_status.stdout == \"running\"\n    fail_msg: \"Container {{input.container_name}} is {{ container_status.stdout }}\"\n\n- name: Check container health\n  command: \"docker inspect --format='{{.State.Health.Status}}'  {{input.container_name}}\"\n  register: health_status\n  changed_when: false\n  failed_when: false\n  when: container_status.stdout == \"running\"\n",
    "schema": {
      "input": {
