{
  "fields": {
    "name": "nginx-cgroup-limits",
    "action_type": "SHELL",
    "code": "mkdir -p /etc/systemd/system/{{input.service_name}}.service.d && cat > /etc/systemd/system/{{input.service_name}}.service.d/cgroup-limits.conf <<EOF\n[Service]\nMemoryMax={{input.memory_max}}\nMemoryHigh={{input.memory_high}}\nCPUWeight={{input.cpu_weight}}\nTasksMax={{input.tasks_max}}\nEOF\nsystemctl daemon-reload && systemctl restart {{input.service_name}} && echo \"Cgroup limits applied: MemoryMax={{input.memory_max}}, CPUWeight={{input.cpu_weight}}, TasksMax={{input.tasks_max}}\"",
    "expected_rc": 0,
    "schema": {
      "input": {
        "service_name": {
          "type": "string",
          "description": "Systemd service to apply cgroup limits to"
        },
        "memory_max": {
          "type": "string",
          "description": "Hard memory limit (e.g. 1G, 512M)"
        },
        "memory_high": {
          "type": "string",
          "description": "Memory throttle threshold (e.g. 800M)"
        },
        "cpu_weight": {
          "type": "integer",
          "description": "CPU weight 1-10000 (default 100)"
        },
        "tasks_max": {
          "type": "integer",
          "description": "Maximum number of tasks/threads"
        }
      },
      "required": [
        "service_name",
        "memory_max",
        "memory_high",
        "cpu_weight",
        "tasks_max"
      ]
    }
  },
  "explanation": "Applies cgroup v2 resource limits (memory, CPU, tasks) to the nginx service via a systemd drop-in."
}

