        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "app_name": {
              "type": "string"
            }
          },
          "required": [
            "app_name"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "load-profile-complain",
        "action_type": "SHELL",
        "code": "apparmor_parser -r /etc/apparmor.d/usr.local.bin.{{input.app_name}} && aa-complain /usr/local/bin/{{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enforce-profile",
        "action_type": "SHELL",
        "code": "aa-enforce /usr/local/bin/{{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-profile",
        "action_type": "SHELL",
        "code": "aa-status | grep {{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-apparmor",
        "action_type": "SHELL",
        "code": "aa-disable /usr/local/bin/{{input.app_name}} 2>/dev/null; rm -f /etc/apparmor.d/usr.local.bin.{{input.app_name}}",
        "parent_step_ids": [
          "2"
        ]
