{
  "fields": {
    "name": "Check open file descriptors",
    "action_type": "PYTHON",
    "code": "import json
import sys

threshold_pct = float("{{input.threshold_pct}}" or "80")

with open("/proc/sys/fs/file-nr", "r") as f:
    parts = f.read().strip().split()
    allocated = int(parts[0])
    free = int(parts[1])
    maximum = int(parts[2])

used = allocated - free
pct = (used / maximum) * 100.0 if maximum > 0 else 0.0

result = {{
    "allocated": allocated,
    "free": free,
    "used": used,
    "maximum": maximum,
    "percent_used": round(pct, 2),
    "threshold": threshold_pct,
    "status": "critical" if pct > threshold_pct else "ok",
}}
print(json.dumps(result))
if pct > threshold_pct:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "threshold_pct": {
          "type": "string",
          "description": "Usage threshold percentage (default 80)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/sys/fs/file-nr to check system-wide open file descriptor usage."
}

{
  "fields": {
    "name": "Multipart upload to s3",
    "action_type": "PYTHON",
    "code": "import json
import urllib.request
import os
import uuid
import sys

url = "{{input.url}}"
filepath = "{{input.filepath}}"
field_name = "{{input.field_name}}" or "file"
api_key = "{{input.api_key}}"

if not os.path.isfile(filepath):
    print(json.dumps({{"status": "error", "message": f"File not found: {{filepath}}"}}))
    sys.exit(1)

boundary = uuid.uuid4().hex
filename = os.path.basename(filepath)
with open(filepath, "rb") as f:
    file_data = f.read()

body = (
    f"--{{boundary}}\r\n"
    f"Content-Disposition: form-data; name=\"{{field_name}}\"; filename=\"{{filename}}\"\r\n"
    f"Content-Type: application/octet-stream\r\n\r\n"
).encode() + file_data + f"\r\n--{{boundary}}--\r\n".encode()

req = urllib.request.Request(url, data=body, method="POST")
req.add_header("Content-Type", f"multipart/form-data; boundary={{boundary}}")
if api_key:
    req.add_header("Authorization", "Bearer " + api_key)
try:
    resp = urllib.request.urlopen(req, timeout=120)
    print(json.dumps({{"status": "uploaded", "code": resp.getcode(), "size": len(file_data), "filename": filename}}))
except urllib.error.HTTPError as e:
    print(json.dumps({{"status": "error", "code": e.code, "message": e.read().decode()[:500]}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "Upload endpoint URL"
        },
        "filepath": {
          "type": "string",
          "description": "Local file path to upload"
        },
        "field_name": {
          "type": "string",
          "description": "Form field name for the file (default: file)"
        },
        "api_key": {
          "type": "string",
          "description": "Bearer token for auth (optional)"
        }
      },
      "required": [
        "url",
        "filepath"
      ]
    }
  },
  "explanation": "Python action that uploads a file to s3 using multipart/form-data encoding with optional bearer auth."
}

