{
  "fields": {
    "name": "Parse JSON config for kubernetes",
    "action_type": "PYTHON",
    "code": "import json
import sys

config_path = "{{input.config_path}}"
key_path = "{{input.key_path}}"

try:
    with open(config_path, "r") as f:
        config = json.load(f)

    # Navigate nested keys via dot notation
    value = config
    if key_path:
        for key in key_path.split("."):
            if isinstance(value, dict):
                value = value[key]
            elif isinstance(value, list):
                value = value[int(key)]
            else:
                raise KeyError(f"Cannot traverse into {{type(value).__name__}}")

    print(json.dumps({{"status": "ok", "key": key_path, "value": value}}))
except FileNotFoundError:
    print(json.dumps({{"status": "error", "message": f"File not found: {{config_path}}"}}))
