{
  "fields": {
    "name": "development-psql-create-user",
    "action_type": "SHELL",
    "code": "psql -h {{input.host}} -U {{input.admin_user}} <<SQL\nDO \\$\\$\nBEGIN\n  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = '{{input.new_user}}') THEN\n    CREATE ROLE {{input.new_user}} LOGIN PASSWORD '{{input.password}}';\n    RAISE NOTICE 'Role created: {{input.new_user}}';\n  ELSE\n    RAISE NOTICE 'Role already exists: {{input.new_user}}';\n  END IF;\nEND\n\\$\\$;\nGRANT CONNECT ON DATABASE {{input.database}} TO {{input.new_user}};\nGRANT USAGE ON SCHEMA public TO {{input.new_user}};\nGRANT {{input.privileges}} ON ALL TABLES IN SCHEMA public TO {{input.new_user}};\nALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT {{input.privileges}} ON TABLES TO {{input.new_user}};\nSQL\necho \"User {{input.new_user}} configured with {{input.privileges}} on {{input.database}}\"",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "PostgreSQL host address"
        },
        "admin_user": {
          "type": "string",
          "description": "Admin user with CREATEROLE privilege"
        },
        "new_user": {
          "type": "string",
          "description": "Username for the new role"
        },
        "password": {
          "type": "string",
          "description": "Password for the new role"
        },
        "database": {
          "type": "string",
          "description": "Database to grant access to"
        },
        "privileges": {
          "type": "string",
          "description": "Privileges to grant (e.g. SELECT, SELECT,INSERT,UPDATE,DELETE, ALL)"
        }
      },
      "required": [
        "host",
        "admin_user",
        "new_user",
        "password",
        "database",
        "privileges"
      ]
    }
  },
  "explanation": "Creates a PostgreSQL user in the development environment with specified database privileges and default grants."
}

{
  "fields": {
    "name": "multi-container-app",
    "description": "Deploy multi-container app with DB and cache",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-network",
        "action_type": "SHELL",
        "code": "docker network create {{input.app_name}}-net 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_name": {
              "type": "string"
            },
            "app_image": {
              "type": "string"
            },
            "app_port": {
              "type": "string"
            }
          },
          "required": [
            "app_name",
            "app_image",
            "app_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "start-database",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-db --network {{input.app_name}}-net -v {{input.app_name}}-dbdata:/var/lib/postgresql/data -e POSTGRES_DB={{input.app_name}} -e POSTGRES_PASSWORD=secret postgres:16-alpine",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-redis",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-redis --network {{input.app_name}}-net redis:7-alpine",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "wait-for-deps",
        "action_type": "SHELL",
        "code": "sleep 5 && docker exec {{input.app_name}}-db pg_isready && docker exec {{input.app_name}}-redis redis-cli ping",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "start-app",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-app --network {{input.app_name}}-net -p {{input.app_port}}:8080 -e DATABASE_URL=postgresql://postgres:secret@{{input.app_name}}-db/{{input.app_name}} -e REDIS_URL=redis://{{input.app_name}}-redis:6379 {{input.app_image}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 5 && curl -sf http://localhost:{{input.app_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "undo-multi-container",
        "action_type": "SHELL",
        "code": "docker stop {{input.app_name}}-app {{input.app_name}}-redis {{input.app_name}}-db 2>/dev/null; docker rm {{input.app_name}}-app {{input.app_name}}-redis {{input.app_name}}-db 2>/dev/null; docker network rm {{input.app_name}}-net 2>/dev/null; true",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Multi-container: create network, start DB+Redis in parallel, wait, start app, health check."
}

