{
  "fields": {
    "name": "log-alerting",
    "description": "Set up log-based alerting",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-alert-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/log-alert.sh <<SCRIPT\n#!/bin/bash\nPATTERN=\"{{input.alert_pattern}}\"\nLOGFILE=\"{{input.log_path}}\"\nERRORS=$(tail -100 \"$LOGFILE\" | grep -c \"$PATTERN\")\nif [ \"$ERRORS\" -gt {{input.threshold}} ]; then\n  echo \"ALERT: $ERRORS matches for $PATTERN in $LOGFILE\" | logger -t log-alert\nfi\nSCRIPT\nchmod +x /usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/5 * * * * /usr/local/bin/log-alert.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-alert-script",
        "action_type": "SHELL",
        "code": "/usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": true,
        "name": "undo-log-alerting",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v log-alert | crontab - && rm -f /usr/local/bin/log-alert.sh",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Log alerting: create alert script, add cron, test. Matches pattern in log and fires syslog alert."
}

{
  "fields": {
    "name": "nginx-watchdog-config",
    "action_type": "SHELL",
    "code": "mkdir -p /etc/systemd/system/{{input.service_name}}.service.d && cat > /etc/systemd/system/{{input.service_name}}.service.d/watchdog.conf <<WATCHDOG\n[Service]\nWatchdogSec={{input.watchdog_sec}}\nRestart=on-watchdog\nRestartSec={{input.restart_sec}}\nStartLimitIntervalSec={{input.limit_interval}}\nStartLimitBurst={{input.limit_burst}}\nWATCHDOG\nsystemctl daemon-reload && systemctl restart {{input.service_name}} && systemctl show {{input.service_name}} --property=WatchdogUSec,Restart --no-pager && echo \"Watchdog configured for {{input.service_name}} (timeout: {{input.watchdog_sec}})\"",
    "expected_rc": 0,
    "schema": {
      "input": {
        "service_name": {
          "type": "string",
          "description": "Name of the systemd service"
        },
        "watchdog_sec": {
          "type": "string",
          "description": "Watchdog timeout (e.g. 30s, 60s)"
        },
        "restart_sec": {
          "type": "string",
          "description": "Delay before restart (e.g. 5s)"
        },
        "limit_interval": {
          "type": "string",
          "description": "Rate limit interval (e.g. 300s)"
        },
        "limit_burst": {
          "type": "integer",
          "description": "Maximum restarts within interval"
        }
      },
      "required": [
        "service_name",
        "watchdog_sec",
        "restart_sec",
        "limit_interval",
        "limit_burst"
      ]
    }
  },
  "explanation": "Configures a systemd watchdog for the nginx service with automatic restart on timeout and rate limiting."
}

