        "code": "sed -i \"s|//.*\"\\${distro_id}:${distro_codename}-security\"|\\t\"${distro_id}:${distro_codename}-security\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enable-email-notify",
        "action_type": "SHELL",
        "code": "sed -i \"s|//Unattended-Upgrade::Mail \"\"|Unattended-Upgrade::Mail \"{{input.admin_email}}\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "schema": {
          "input": {
            "admin_email": {
              "type": "string"
            }
          },
          "required": [
            "admin_email"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "dry-run-test",
        "action_type": "SHELL",
        "code": "unattended-upgrade --dry-run --debug",
        "target": "all",
        "parent_step_ids": [
          "3",
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-auto-updates",
        "action_type": "SHELL",
        "code": "rm -f /etc/apt/apt.conf.d/20auto-upgrades; apt-get remove -y unattended-upgrades",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Auto updates: install unattended-upgrades, enable periodic updates, security-only, email notify, dry-run test."
}

{
  "fields": {
    "name": "Build multi-platform image with buildx",
    "action_type": "ANSIBLE",
    "code": "- name: Check if buildx is available\n  command: docker buildx version\n  register: buildx_check\n  changed_when: false\n  failed_when: false\n\n- name: Create buildx builder\n  command: \"docker buildx create --name {{input.builder_name}} --use\"\n  when: buildx_check.rc == 0\n  register: builder_create\n  failed_when: false\n\n- name: Build multi-platform image\n  command: >-\n    docker buildx build\n    --platform {{input.platforms}}\n    -t {{input.image_name}}:{{input.tag}}\n    -f {{input.dockerfile}}\n    --push={{ input.push | default(\"false\") }}\n    {{input.build_context}}\n  register: build_result\n\n- name: Display build result\n  debug:\n    msg: \"Multi-platform build complete for {{ input.image_name }}:{{ input.tag }} ({{ input.platforms }})\"\n",
    "schema": {
      "input": {
        "builder_name": {
          "type": "string",
          "description": "Name for the buildx builder instance"
        },
        "image_name": {
          "type": "string",
          "description": "Image name to build"
        },
        "tag": {
          "type": "string",
          "description": "Image tag"
        },
        "platforms": {
          "type": "string",
          "description": "Comma-separated platforms (e.g. linux/amd64,linux/arm64)"
        },
