{
  "fields": {
    "name": "Count python processes",
    "action_type": "PYTHON",
    "code": "import json
import os
import sys

process_name = "{{input.process_name}}"
min_count = int("{{input.min_count}}" or "1")

count = 0
pids = []
for pid in os.listdir("/proc"):
    if not pid.isdigit():
        continue
    try:
        with open(f"/proc/{{pid}}/comm", "r") as f:
            comm = f.read().strip()
        if process_name in comm:
            count += 1
            pids.append(int(pid))
    except (IOError, OSError):
        continue

result = {{
    "process": process_name,
    "count": count,
    "pids": pids[:20],
    "min_expected": min_count,
    "status": "ok" if count >= min_count else "critical",
}}
print(json.dumps(result))
if count < min_count:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "process_name": {
          "type": "string",
          "description": "Process name to search for"
        },
        "min_count": {
          "type": "string",
          "description": "Minimum expected process count (default 1)"
        }
      },
      "required": [
        "process_name"
      ]
    }
  },
  "explanation": "Python action that counts running python processes by scanning /proc and alerts if count is below minimum."
}

{
  "fields": {
    "name": "Detect redis connection leaks",
    "action_type": "PYTHON",
    "code": "import json
import socket
import time
import sys

host = "{{input.host}}" or "localhost"
port = int("{{input.port}}")
interval = int("{{input.interval}}" or "5")
samples = int("{{input.samples}}" or "6")
growth_threshold = int("{{input.growth_threshold}}" or "10")

def count_connections(h, p):
    count = 0
    try:
        with open("/proc/net/tcp", "r") as f:
            for line in f.readlines()[1:]:
                parts = line.split()
                remote_port = int(parts[2].split(":")[1], 16)
                state = parts[3]
                if remote_port == p and state == "01":
                    count += 1
    except Exception:
        pass
    return count

counts = []
for i in range(samples):
    c = count_connections(host, port)
    counts.append(c)
    if i < samples - 1:
        time.sleep(interval)

growth = counts[-1] - counts[0] if len(counts) > 1 else 0
leak_detected = growth >= growth_threshold
result = {{
    "status": "leak_suspected" if leak_detected else "ok",
    "host": host,
    "port": port,
    "samples": counts,
    "growth": growth,
    "growth_threshold": growth_threshold,
    "first_count": counts[0],
    "last_count": counts[-1],
}}
print(json.dumps(result))
if leak_detected:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "Database host (default localhost)"
        },
        "port": {
          "type": "string",
          "description": "Database port"
        },
        "interval": {
          "type": "string",
          "description": "Seconds between samples (default 5)"
        },
        "samples": {
          "type": "string",
          "description": "Number of samples to take (default 6)"
        },
        "growth_threshold": {
          "type": "string",
          "description": "Connection growth to flag as leak (default 10)"
        }
      },
      "required": [
        "port"
      ]
