    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "image_name": {
              "type": "string"
            },
            "registry": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "image_name",
            "registry"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "docker-build",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && TAG=$(git rev-parse --short HEAD) && docker build -t {{input.registry}}/{{input.image_name}}:$TAG -t {{input.registry}}/{{input.image_name}}:latest .",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "docker-push",
