{
  "fields": {
    "name": "weekly-backup-rotation",
    "action_type": "SHELL",
    "code": "BACKUP_DIR=\"{{input.backup_dir}}\" && KEEP={{input.keep_count}} && if [ ! -d \"$BACKUP_DIR\" ]; then echo \"FAILED: Backup directory not found: $BACKUP_DIR\" >&2; exit 1; fi && TOTAL=$(ls -1t \"$BACKUP_DIR\"/{{input.file_pattern}} 2>/dev/null | wc -l) && if [ \"$TOTAL\" -le \"$KEEP\" ]; then echo \"No rotation needed: $TOTAL backups found, keeping $KEEP\"; exit 0; fi && DELETE_COUNT=$((TOTAL - KEEP)) && ls -1t \"$BACKUP_DIR\"/{{input.file_pattern}} | tail -n \"$DELETE_COUNT\" | xargs rm -f && echo \"Rotation complete: deleted $DELETE_COUNT old backups, kept $KEEP newest\"",
    "expected_rc": 0,
    "schema": {
      "input": {
        "backup_dir": {
          "type": "string",
          "description": "Directory containing backup files"
        },
        "file_pattern": {
          "type": "string",
          "description": "Glob pattern to match backup files (e.g. *.sql.gz, *.tar.gz)"
        },
        "keep_count": {
          "type": "integer",
          "description": "Number of most recent backups to keep"
        }
      },
      "required": [
        "backup_dir",
        "file_pattern",
        "keep_count"
      ]
    }
  },
  "explanation": "Rotates weekly backups by deleting the oldest files and keeping only the specified number."
}

{
  "fields": {
    "name": "docker-volume-backup",
    "description": "Backup Docker volumes to compressed archive",
    "stop_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-backup-dir",
        "action_type": "SHELL",
        "code": "mkdir -p {{input.backup_dir}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "volume_name": {
              "type": "string"
            },
            "backup_dir": {
              "type": "string"
            }
          },
          "required": [
            "volume_name",
            "backup_dir"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "stop-using-containers",
        "action_type": "SHELL",
        "code": "CONTAINERS=$(docker ps -q --filter volume={{input.volume_name}}); if [ -n \"$CONTAINERS\" ]; then docker stop $CONTAINERS; echo \"$CONTAINERS\" > /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "backup-volume",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && docker run --rm -v {{input.volume_name}}:/source -v {{input.backup_dir}}:/backup alpine tar czf /backup/{{input.volume_name}}_$TIMESTAMP.tar.gz -C /source .",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-containers",
        "action_type": "SHELL",
        "code": "if [ -f /tmp/vol_backup_containers ]; then cat /tmp/vol_backup_containers | xargs docker start; rm /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-backup",
        "action_type": "SHELL",
        "code": "ls -lh {{input.backup_dir}}/{{input.volume_name}}_*.tar.gz | tail -1",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      }
    ]
  },
  "explanation": "Volume backup: mkdir, stop containers using volume, tar the volume, restart containers, verify archive."
}

{
  "fields": {
    "name": "sha256-verify-config",
    "action_type": "SHELL",
    "code": "if [ ! -f \"{{input.file_path}}\" ]; then echo \"File not found\" >&2; exit 1; fi && ACTUAL=$(sha256sum \"{{input.file_path}}\" | awk '{{print $1}}') && if [ \"$ACTUAL\" = \"{{input.expected_hash}}\" ]; then echo \"PASS: Checksum matches\"; echo \"SHA256: $ACTUAL\"; exit 0; else echo \"FAIL: Checksum mismatch\" >&2; echo \"Expected: {{input.expected_hash}}\" >&2; echo \"Actual:   $ACTUAL\" >&2; exit 1; fi",
