{
  "fields": {
    "name": "Paginated GET from jira",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport urllib.parse\nimport sys\n\nbase_url = \"{{input.url}}\"\nmax_pages = int(\"{{input.max_pages}}\" or \"10\")\nall_items = []\npage = 1\n\nwhile page <= max_pages:\n    params = urllib.parse.urlencode({{\"page\": page, \"per_page\": 100}})\n    url = f\"{{base_url}}?{{params}}\"\n    req = urllib.request.Request(url, method=\"GET\")\n    req.add_header(\"Authorization\", \"Bearer {{input.api_key}}\")\n    try:\n        resp = urllib.request.urlopen(req, timeout=30)\n        data = json.loads(resp.read().decode())\n        items = data if isinstance(data, list) else data.get(\"items\", data.get(\"results\", []))\n        if not items:\n            break\n        all_items.extend(items)\n        page += 1\n    except Exception as e:\n        print(json.dumps({{\"status\": \"error\", \"page\": page, \"message\": str(e)}}))\n        sys.exit(1)\n\nprint(json.dumps({{\"status\": \"ok\", \"total_items\": len(all_items), \"pages_fetched\": page - 1}}))\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "Base API URL (without pagination params)"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        },
        "max_pages": {
          "type": "string",
          "description": "Maximum pages to fetch (default 10)"
        }
      },
      "required": [
        "url",
        "api_key"
      ]
    }
  },
  "explanation": "Python action that fetches paginated results from jira API, collecting all items across multiple pages."
}

