        "api_url": {
          "type": "string",
          "description": "Storage API list endpoint"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        }
      },
      "required": [
        "api_url",
        "api_key"
      ]
    }
  },
  "explanation": "Python action that queries minio storage API to list all available buckets."
}

