  "fields": {
    "name": "Send email via SMTP",
    "action_type": "PYTHON",
    "code": "import smtplib\nimport json\nimport sys\nfrom email.mime.text import MIMEText\nfrom email.mime.multipart import MIMEMultipart\n\nsmtp_host = \"{{input.smtp_host}}\"\nsmtp_port = int(\"{{input.smtp_port}}\" or \"587\")\nusername = \"{{input.username}}\"\npassword = \"{{input.password}}\"\nsender = \"{{input.from_addr}}\"\nrecipient = \"{{input.to_addr}}\"\nsubject = \"{{input.subject}}\"\nbody = \"{{input.body}}\"\n\nmsg = MIMEMultipart()\nmsg[\"From\"] = sender\nmsg[\"To\"] = recipient\nmsg[\"Subject\"] = subject\nmsg.attach(MIMEText(body, \"plain\"))\n\ntry:\n    with smtplib.SMTP(smtp_host, smtp_port) as server:\n        server.ehlo()\n        server.starttls()\n        server.login(username, password)\n        server.sendmail(sender, [recipient], msg.as_string())\n    print(json.dumps({{\"status\": \"sent\", \"to\": recipient, \"subject\": subject}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "smtp_host": {
          "type": "string",
          "description": "SMTP server hostname"
        },
        "smtp_port": {
          "type": "string",
          "description": "SMTP server port (default 587)"
        },
        "username": {
          "type": "string",
          "description": "SMTP username"
        },
        "password": {
          "type": "string",
          "description": "SMTP password"
        },
        "from_addr": {
          "type": "string",
          "description": "Sender email address"
        },
        "to_addr": {
          "type": "string",
          "description": "Recipient email address"
        },
        "subject": {
          "type": "string",
          "description": "Email subject"
        },
        "body": {
          "type": "string",
          "description": "Email body text"
        }
      },
      "required": [
        "smtp_host",
        "username",
        "password",
        "from_addr",
        "to_addr",
        "subject",
        "body"
      ]
    }
  },
  "explanation": "Python action that sends an email notification via mailgun SMTP with TLS encryption."
}

{
  "fields": {
    "name": "full-mail-server",
    "description": "Full mail stack: Postfix + Dovecot + DKIM",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-packages",
        "action_type": "SHELL",
        "code": "DEBIAN_FRONTEND=noninteractive apt-get update && apt-get install -y postfix dovecot-imapd opendkim opendkim-tools",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"myhostname=mail.{{input.domain}}\" && postconf -e \"mydomain={{input.domain}}\" && postconf -e \"home_mailbox=Maildir/\" && postconf -e \"smtpd_tls_cert_file=/etc/letsencrypt/live/{{input.domain}}/fullchain.pem\" && postconf -e \"smtpd_tls_key_file=/etc/letsencrypt/live/{{input.domain}}/privkey.pem\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "domain": {
              "type": "string"
            },
            "dkim_selector": {
              "type": "string"
            }
          },
          "required": [
            "domain",
            "dkim_selector"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-dovecot",
        "action_type": "SHELL",
        "code": "sed -i \"s|^#*mail_location.*|mail_location = maildir:~/Maildir|\" /etc/dovecot/conf.d/10-mail.conf && sed -i \"s/^#*ssl =.*/ssl = required/\" /etc/dovecot/conf.d/10-ssl.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "generate-dkim",
        "action_type": "SHELL",
        "code": "mkdir -p /etc/opendkim/keys/{{input.domain}} && opendkim-genkey -s {{input.dkim_selector}} -d {{input.domain}} -D /etc/opendkim/keys/{{input.domain}} && chown -R opendkim:opendkim /etc/opendkim",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-dkim",
        "action_type": "SHELL",
        "code": "postconf -e \"milter_protocol = 6\" && postconf -e \"smtpd_milters = inet:localhost:8891\" && postconf -e \"non_smtpd_milters = inet:localhost:8891\"",
        "target": "all",
        "parent_step_ids": [
          "2",
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-all-services",
        "action_type": "SHELL",
        "code": "systemctl enable --now postfix dovecot opendkim",
        "target": "all",
        "parent_step_ids": [
          "3",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-smtp",
        "action_type": "SHELL",
        "code": "echo \"QUIT\" | nc localhost 25 | grep -q \"220\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": false,
        "name": "verify-imap",
        "action_type": "SHELL",
        "code": "echo \"A1 LOGOUT\" | openssl s_client -connect localhost:993 -quiet 2>/dev/null | grep -q \"OK\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "9",
        "undo": true,
        "name": "undo-mail-stack",
        "action_type": "SHELL",
        "code": "systemctl stop postfix dovecot opendkim; apt-get remove -y postfix dovecot-imapd opendkim opendkim-tools",
        "parent_step_ids": [
