{
  "fields": {
    "name": "tar-extract",
    "action_type": "SHELL",
    "code": "if [ \"{{input.action}}\" = \"create\" ]; then tar -czf \"{{input.archive_path}}\" -C \"$(dirname {{input.source_path}})\" \"$(basename {{input.source_path}})\" && echo \"Archive created: {{input.archive_path}}\" && ls -lh \"{{input.archive_path}}\"; elif [ \"{{input.action}}\" = \"extract\" ]; then mkdir -p \"{{input.dest_path}}\" && tar -xzf \"{{input.archive_path}}\" -C \"{{input.dest_path}}\" && echo \"Extracted to: {{input.dest_path}}\" && ls -la \"{{input.dest_path}}\"; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "action": {
          "type": "string",
          "description": "Action to perform: create or extract"
        },
        "archive_path": {
          "type": "string",
          "description": "Path to the tar.gz archive"
        },
        "source_path": {
          "type": "string",
          "description": "Source path for create (directory or file)"
        },
        "dest_path": {
          "type": "string",
          "description": "Destination path for extract"
        }
      },
      "required": [
        "action",
        "archive_path"
      ]
    }
  },
  "explanation": "Performs tar archive extract operation with gzip compression."
}

