{
  "fields": {
    "name": "Socket activation for gunicorn",
    "action_type": "ANSIBLE",
    "code": "- name: Create socket unit for {{input.service_name}}
  copy:
    dest: "/etc/systemd/system/{{input.service_name}}.socket"
    content: |
      [Unit]
      Description=Socket for {{input.service_name}}

      [Socket]
      ListenStream={{input.listen_address}}
      Accept=no

      [Install]
      WantedBy=sockets.target
    owner: root
    group: root
    mode: "0644"

- name: Reload systemd
  systemd:
    daemon_reload: yes

- name: Enable and start socket
  systemd:
    name: "{{input.service_name}}.socket"
    state: started
    enabled: yes
",
    "schema": {
      "input": {
        "service_name": {
          "type": "string",
          "description": "Service name for socket activation"
        },
        "listen_address": {
          "type": "string",
          "description": "Listen address (e.g. 0.0.0.0:8080 or /run/myapp.sock)"
        }
      },
      "required": [
        "service_name",
        "listen_address"
      ]
    }
  },
  "explanation": "Ansible action that creates a systemd socket unit for gunicorn with socket-based activation."
}

