        "port": {
          "type": "string",
          "description": "MongoDB port (default 27017)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 5)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that checks production MongoDB status by attempting a TCP connection to the database port."
}

