    "description": "Deploy PHP Laravel application",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "enable-maintenance",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && php artisan down --retry=60",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "pull-code",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "composer-install",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && composer install --no-dev --optimize-autoloader",
