{
  "fields": {
    "name": "deploy-flask-gunicorn",
    "description": "Deploy Flask app with Gunicorn",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-current",
        "action_type": "SHELL",
        "code": "cp -a {{input.app_dir}} {{input.app_dir}}.bak 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "venv_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "workers": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "venv_dir",
            "branch",
            "workers"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "pull-code",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "{{input.venv_dir}}/bin/pip install -r {{input.app_dir}}/requirements.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "write-gunicorn-conf",
        "action_type": "SHELL",
        "code": "cat > /etc/systemd/system/gunicorn.service <<SVC\n[Unit]\nDescription=Gunicorn Flask\nAfter=network.target\n[Service]\nUser=www-data\nWorkingDirectory={{input.app_dir}}\nExecStart={{input.venv_dir}}/bin/gunicorn -w {{input.workers}} -b 0.0.0.0:8000 wsgi:app\nRestart=always\n[Install]\nWantedBy=multi-user.target\nSVC",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "reload-and-restart",
        "action_type": "SHELL",
        "code": "systemctl daemon-reload && systemctl enable --now gunicorn",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:8000/health",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
