    "code": "import json\nimport re\nimport sys\n\ntemplate_str = '{{input.template}}'\nvars_json = '{{input.variables}}'\noutput_path = \"{{input.output_path}}\"\n\ntry:\n    variables = json.loads(vars_json)\n    def replacer(match):\n        key = match.group(1).strip()\n        return str(variables.get(key, match.group(0)))\n    rendered = re.sub(r\"\\{\\{\\s*(\\w+)\\s*\\}\\}\", replacer, template_str)\n    with open(output_path, \"w\") as f:\n        f.write(rendered)\n    print(json.dumps({{\n        \"status\": \"ok\",\n        \"output\": output_path,\n        \"vars_applied\": len(variables),\n    }}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "template": {
          "type": "string",
          "description": "Config template string with {{ var }} placeholders"
        },
        "variables": {
          "type": "string",
          "description": "JSON string of template variables"
        },
        "output_path": {
          "type": "string",
          "description": "Output file path for rendered config"
        }
