{
  "fields": {
    "name": "log-alerting",
    "description": "Set up log-based alerting",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-alert-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/log-alert.sh <<SCRIPT\n#!/bin/bash\nPATTERN=\"{{input.alert_pattern}}\"\nLOGFILE=\"{{input.log_path}}\"\nERRORS=$(tail -100 \"$LOGFILE\" | grep -c \"$PATTERN\")\nif [ \"$ERRORS\" -gt {{input.threshold}} ]; then\n  echo \"ALERT: $ERRORS matches for $PATTERN in $LOGFILE\" | logger -t log-alert\nfi\nSCRIPT\nchmod +x /usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/5 * * * * /usr/local/bin/log-alert.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-alert-script",
        "action_type": "SHELL",
        "code": "/usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": true,
        "name": "undo-log-alerting",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v log-alert | crontab - && rm -f /usr/local/bin/log-alert.sh",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Log alerting: create alert script, add cron, test. Matches pattern in log and fires syslog alert."
}

{
  "fields": {
    "name": "docker-volume-backup",
    "description": "Backup Docker volumes to compressed archive",
    "stop_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-backup-dir",
        "action_type": "SHELL",
        "code": "mkdir -p {{input.backup_dir}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "volume_name": {
              "type": "string"
            },
            "backup_dir": {
              "type": "string"
            }
          },
          "required": [
            "volume_name",
            "backup_dir"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "stop-using-containers",
        "action_type": "SHELL",
        "code": "CONTAINERS=$(docker ps -q --filter volume={{input.volume_name}}); if [ -n \"$CONTAINERS\" ]; then docker stop $CONTAINERS; echo \"$CONTAINERS\" > /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "backup-volume",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && docker run --rm -v {{input.volume_name}}:/source -v {{input.backup_dir}}:/backup alpine tar czf /backup/{{input.volume_name}}_$TIMESTAMP.tar.gz -C /source .",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-containers",
        "action_type": "SHELL",
        "code": "if [ -f /tmp/vol_backup_containers ]; then cat /tmp/vol_backup_containers | xargs docker start; rm /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-backup",
        "action_type": "SHELL",
        "code": "ls -lh {{input.backup_dir}}/{{input.volume_name}}_*.tar.gz | tail -1",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      }
    ]
  },
  "explanation": "Volume backup: mkdir, stop containers using volume, tar the volume, restart containers, verify archive."
}

{
  "fields": {
    "name": "Check system uptime",
    "action_type": "PYTHON",
    "code": "import json
import sys

min_uptime_hours = float("{{input.min_uptime_hours}}" or "0")

with open("/proc/uptime", "r") as f:
    uptime_seconds = float(f.read().split()[0])

days = int(uptime_seconds // 86400)
hours = int((uptime_seconds % 86400) // 3600)
minutes = int((uptime_seconds % 3600) // 60)
uptime_hours = uptime_seconds / 3600.0

result = {{
    "uptime_seconds": round(uptime_seconds, 1),
    "uptime_human": f"{{days}}d {{hours}}h {{minutes}}m",
    "days": days,
    "hours": hours,
    "minutes": minutes,
    "status": "ok" if uptime_hours >= min_uptime_hours else "recently_rebooted",
}}
print(json.dumps(result))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "min_uptime_hours": {
          "type": "string",
          "description": "Minimum expected uptime in hours (default 0)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/uptime and reports system uptime in human-readable format for routine monitoring."
}

