          },
          "required": [
            "max_size",
            "max_files"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "restart-docker",
        "action_type": "SHELL",
        "code": "systemctl restart docker",
        "target": "all",
        "parent_step_ids": [
