    "code": "if psql -h {{input.host}} -U {{input.admin_user}} -lqt 2>/dev/null | cut -d\"|\" -f1 | grep -qw \"{{input.database}}\"; then echo \"Database {{input.database}} already exists\"; else psql -h {{input.host}} -U {{input.admin_user}} -c \"CREATE DATABASE {{input.database}} OWNER {{input.owner}} ENCODING '{{input.encoding}}' LC_COLLATE '{{input.locale}}' LC_CTYPE '{{input.locale}}' TEMPLATE template0;\" 2>&1 && echo \"Database {{input.database}} created (owner: {{input.owner}}, encoding: {{input.encoding}})\"; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "PostgreSQL host address"
        },
        "admin_user": {
          "type": "string",
          "description": "Admin user with CREATE DATABASE privilege"
        },
        "database": {
          "type": "string",
          "description": "Name of the database to create"
        },
        "owner": {
          "type": "string",
          "description": "Database owner role"
        },
        "encoding": {
          "type": "string",
          "description": "Character encoding (e.g. UTF8)"
        },
        "locale": {
          "type": "string",
          "description": "Locale for collation (e.g. en_US.UTF-8)"
        }
      },
      "required": [
        "host",
        "admin_user",
        "database",
        "owner",
        "encoding",
        "locale"
      ]
    }
  },
  "explanation": "Creates a new PostgreSQL database in the production environment with specified owner and encoding."
}

