{
  "fields": {
    "name": "Check system uptime",
    "action_type": "PYTHON",
    "code": "import json
import sys

min_uptime_hours = float("{{input.min_uptime_hours}}" or "0")

with open("/proc/uptime", "r") as f:
    uptime_seconds = float(f.read().split()[0])

days = int(uptime_seconds // 86400)
hours = int((uptime_seconds % 86400) // 3600)
minutes = int((uptime_seconds % 3600) // 60)
uptime_hours = uptime_seconds / 3600.0

result = {{
    "uptime_seconds": round(uptime_seconds, 1),
    "uptime_human": f"{{days}}d {{hours}}h {{minutes}}m",
    "days": days,
    "hours": hours,
    "minutes": minutes,
    "status": "ok" if uptime_hours >= min_uptime_hours else "recently_rebooted",
}}
print(json.dumps(result))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "min_uptime_hours": {
          "type": "string",
          "description": "Minimum expected uptime in hours (default 0)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/uptime and reports system uptime in human-readable format for post-deployment monitoring."
}

