{
  "fields": {
    "name": "Dispatch webhook to argocd",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport hashlib\nimport hmac\nimport sys\n\nwebhook_url = \"{{input.webhook_url}}\"\nevent_type = \"{{input.event_type}}\"\npayload_str = '{{input.payload}}'\nsecret = \"{{input.secret}}\"\n\npayload = {{\"event\": event_type, \"data\": json.loads(payload_str)}}\nbody = json.dumps(payload).encode(\"utf-8\")\n\nreq = urllib.request.Request(webhook_url, data=body, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"X-Event-Type\", event_type)\nif secret:\n    sig = hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()\n    req.add_header(\"X-Signature\", \"sha256=\" + sig)\n\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    print(json.dumps({{\"status\": \"dispatched\", \"code\": resp.getcode()}}))\nexcept urllib.error.HTTPError as e:\n    print(json.dumps({{\"status\": \"error\", \"code\": e.code}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "webhook_url": {
          "type": "string",
          "description": "Webhook endpoint URL"
        },
        "event_type": {
          "type": "string",
          "description": "Event type identifier"
        },
        "payload": {
          "type": "string",
          "description": "JSON payload string"
        },
        "secret": {
          "type": "string",
          "description": "HMAC secret for signing (optional)"
        }
      },
      "required": [
        "webhook_url",
        "event_type",
        "payload"
      ]
    }
  },
  "explanation": "Python action that dispatches a webhook event to argocd with optional HMAC-SHA256 signature verification."
}

