      },
      {
        "id": "5",
        "undo": false,
        "name": "run-new-container",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.image_name}} --restart unless-stopped -p 8080:8080 {{input.registry}}/{{input.image_name}}:latest",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 5 && curl -sf http://localhost:8080/health",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "undo-docker-deploy",
        "action_type": "SHELL",
        "code": "docker stop {{input.image_name}} 2>/dev/null; docker rm {{input.image_name}} 2>/dev/null; docker run -d --name {{input.image_name}} --restart unless-stopped -p 8080:8080 {{input.registry}}/{{input.image_name}}:previous 2>/dev/null; true",
        "parent_step_ids": [
          "4"
        ]
      }
    ]
  },
  "explanation": "Docker CI/CD: pull, build image with git tag, push to registry, stop old, run new, health check."
}

