{
  "fields": {
    "name": "log-alerting",
    "description": "Set up log-based alerting",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-alert-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/log-alert.sh <<SCRIPT\n#!/bin/bash\nPATTERN=\"{{input.alert_pattern}}\"\nLOGFILE=\"{{input.log_path}}\"\nERRORS=$(tail -100 \"$LOGFILE\" | grep -c \"$PATTERN\")\nif [ \"$ERRORS\" -gt {{input.threshold}} ]; then\n  echo \"ALERT: $ERRORS matches for $PATTERN in $LOGFILE\" | logger -t log-alert\nfi\nSCRIPT\nchmod +x /usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/5 * * * * /usr/local/bin/log-alert.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-alert-script",
        "action_type": "SHELL",
        "code": "/usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": true,
        "name": "undo-log-alerting",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v log-alert | crontab - && rm -f /usr/local/bin/log-alert.sh",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Log alerting: create alert script, add cron, test. Matches pattern in log and fires syslog alert."
}

{
  "fields": {
    "name": "api-ssl-expiry",
    "action_type": "SHELL",
    "code": "EXPIRY_DATE=$(echo | openssl s_client -servername {{input.hostname}} -connect {{input.hostname}}:{{input.port}} 2>/dev/null | openssl x509 -noout -enddate 2>/dev/null | cut -d= -f2) && if [ -z \"$EXPIRY_DATE\" ]; then echo \"FAILED: Could not retrieve certificate for {{input.hostname}}:{{input.port}}\" >&2; exit 1; fi && EXPIRY_EPOCH=$(date -d \"$EXPIRY_DATE\" +%s 2>/dev/null || date -j -f \"%b %d %T %Y %Z\" \"$EXPIRY_DATE\" +%s 2>/dev/null) && NOW_EPOCH=$(date +%s) && DAYS_LEFT=$(( (EXPIRY_EPOCH - NOW_EPOCH) / 86400 )) && echo \"Certificate for {{input.hostname}} expires: $EXPIRY_DATE ($DAYS_LEFT days remaining)\" && if [ \"$DAYS_LEFT\" -le \"{{input.critical_days}}\" ]; then echo \"CRITICAL: Certificate expires in $DAYS_LEFT days\" >&2; exit 2; elif [ \"$DAYS_LEFT\" -le \"{{input.warning_days}}\" ]; then echo \"WARNING: Certificate expires in $DAYS_LEFT days\" >&2; exit 1; else echo \"OK: Certificate is valid for $DAYS_LEFT more days\"; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "hostname": {
          "type": "string",
          "description": "Hostname to check the SSL certificate for"
        },
        "port": {
          "type": "integer",
          "description": "TLS port number (typically 443)"
        },
        "warning_days": {
          "type": "integer",
          "description": "Warn if certificate expires within this many days"
        },
        "critical_days": {
          "type": "integer",
          "description": "Critical alert if certificate expires within this many days"
        }
      },
      "required": [
        "hostname",
        "port",
        "warning_days",
        "critical_days"
      ]
    }
  },
  "explanation": "Checks the SSL certificate expiry date for the api endpoint and alerts based on warning/critical thresholds."
}

