{
  "fields": {
    "name": "log-alerting",
    "description": "Set up log-based alerting",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-alert-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/log-alert.sh <<SCRIPT\n#!/bin/bash\nPATTERN=\"{{input.alert_pattern}}\"\nLOGFILE=\"{{input.log_path}}\"\nERRORS=$(tail -100 \"$LOGFILE\" | grep -c \"$PATTERN\")\nif [ \"$ERRORS\" -gt {{input.threshold}} ]; then\n  echo \"ALERT: $ERRORS matches for $PATTERN in $LOGFILE\" | logger -t log-alert\nfi\nSCRIPT\nchmod +x /usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/5 * * * * /usr/local/bin/log-alert.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-alert-script",
        "action_type": "SHELL",
        "code": "/usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": true,
        "name": "undo-log-alerting",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v log-alert | crontab - && rm -f /usr/local/bin/log-alert.sh",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Log alerting: create alert script, add cron, test. Matches pattern in log and fires syslog alert."
}

{
  "fields": {
    "name": "temp-file-cleanup",
    "description": "Clean temporary files and caches",
    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "clean-tmp-old",
        "action_type": "SHELL",
        "code": "find /tmp -type f -mtime +{{input.days_old}} -delete 2>/dev/null; find /tmp -type d -empty -mtime +{{input.days_old}} -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "days_old": {
              "type": "string"
            }
          },
          "required": [
            "days_old"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clean-var-tmp",
        "action_type": "SHELL",
        "code": "find /var/tmp -type f -mtime +{{input.days_old}} -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "truncate-large-logs",
        "action_type": "SHELL",
        "code": "find /var/log -name \"*.log\" -size +100M -exec truncate -s 10M {} \\; 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "4",
        "undo": false,
        "name": "clean-journal",
        "action_type": "SHELL",
        "code": "journalctl --vacuum-time={{input.days_old}}d --vacuum-size=500M 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "5",
        "undo": false,
        "name": "clean-thumbnail-cache",
        "action_type": "SHELL",
        "code": "find /home -path \"*/.cache/thumbnails\" -type d -exec rm -rf {} + 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "6",
        "undo": false,
        "name": "report-freed-space",
        "action_type": "SHELL",
        "code": "df -h / /tmp /var",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2",
          "3",
          "4",
          "5"
        ]
      }
    ]
  },
  "explanation": "Temp cleanup: parallel clean /tmp, /var/tmp, truncate logs, vacuum journal, remove caches, report space."
}

{
  "fields": {
    "name": "tune-mysql",
    "description": "Tune MySQL/MariaDB performance",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-mysql-conf",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf /etc/mysql/mysql.conf.d/mysqld.cnf.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-buffer-pool",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*innodb_buffer_pool_size.*/innodb_buffer_pool_size = {{input.buffer_pool}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "buffer_pool": {
              "type": "string"
            },
            "max_conn": {
              "type": "string"
            }
          },
          "required": [
            "buffer_pool",
            "max_conn"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-connections",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_connections.*/max_connections = {{input.max_conn}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-mysql",
        "action_type": "SHELL",
        "code": "systemctl restart mysql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-mysql-vars",
        "action_type": "SHELL",
        "code": "mysql -e \"SHOW VARIABLES LIKE 'innodb_buffer_pool_size'; SHOW VARIABLES LIKE 'max_connections';\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-mysql-tuning",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf.bak /etc/mysql/mysql.conf.d/mysqld.cnf && systemctl restart mysql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "MySQL tuning: backup, set buffer pool + max connections in parallel, restart, verify."
}

