{
  "fields": {
    "name": "deploy-django",
    "description": "Deploy Django app with migrations and static files",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-current",
        "action_type": "SHELL",
        "code": "cp -a {{input.app_dir}} {{input.app_dir}}.bak 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "venv_dir": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "venv_dir"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "pull-code",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "{{input.venv_dir}}/bin/pip install -r {{input.app_dir}}/requirements.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-migrations",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && {{input.venv_dir}}/bin/python manage.py migrate --noinput",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "collect-static",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && {{input.venv_dir}}/bin/python manage.py collectstatic --noinput",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-gunicorn",
        "action_type": "SHELL",
        "code": "systemctl restart gunicorn",
        "target": "all",
        "parent_step_ids": [
          "4",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:8000/health/",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-django-deploy",
        "action_type": "SHELL",
        "code": "rm -rf {{input.app_dir}} && mv {{input.app_dir}}.bak {{input.app_dir}} && systemctl restart gunicorn",
        "parent_step_ids": [
          "2"
        ]
      }
    ]
  },
  "explanation": "Django deploy: backup, pull, pip install, migrate+collectstatic in parallel, restart gunicorn, health check."
}

{
  "fields": {
    "name": "private-registry",
    "description": "Deploy private Docker registry",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-registry-dirs",
        "action_type": "SHELL",
        "code": "mkdir -p /opt/registry/data /opt/registry/auth /opt/registry/certs",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-htpasswd",
        "action_type": "SHELL",
        "code": "docker run --rm --entrypoint htpasswd httpd:2 -Bbn {{input.reg_user}} {{input.reg_pass}} > /opt/registry/auth/htpasswd",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "reg_user": {
              "type": "string"
            },
            "reg_pass": {
              "type": "string"
            },
            "reg_port": {
              "type": "string"
            }
          },
          "required": [
            "reg_user",
            "reg_pass",
            "reg_port"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-registry",
        "action_type": "SHELL",
        "code": "docker run -d --name registry --restart unless-stopped -p {{input.reg_port}}:5000 -v /opt/registry/data:/var/lib/registry -v /opt/registry/auth:/auth -e REGISTRY_AUTH=htpasswd -e REGISTRY_AUTH_HTPASSWD_REALM=\"Registry Realm\" -e REGISTRY_AUTH_HTPASSWD_PATH=/auth/htpasswd registry:2",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-registry",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf -u {{input.reg_user}}:{{input.reg_pass}} http://localhost:{{input.reg_port}}/v2/_catalog",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "test-push-pull",
        "action_type": "SHELL",
        "code": "docker pull alpine:latest && docker tag alpine:latest localhost:{{input.reg_port}}/test-alpine && docker push localhost:{{input.reg_port}}/test-alpine && docker rmi localhost:{{input.reg_port}}/test-alpine",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-registry",
        "action_type": "SHELL",
        "code": "docker stop registry 2>/dev/null; docker rm registry 2>/dev/null; rm -rf /opt/registry",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Private registry: create dirs, generate htpasswd, start registry container, verify API, test push+pull."
}

