    "expected_rc": 0,
    "schema": {
      "input": {
        "container_name": {
          "type": "string",
          "description": "Container name"
        },
        "local_path": {
          "type": "string",
          "description": "Local file or directory path"
        },
        "container_path": {
          "type": "string",
          "description": "Path inside the container"
        },
        "direction": {
          "type": "string",
          "description": "Copy direction: \"to\" (local->container) or \"from\" (container->local)"
        }
      },
      "required": [
        "container_name",
        "local_path",
        "container_path",
        "direction"
      ]
    }
  },
  "explanation": "Copies files between the host and the postgres Docker container in either direction using docker cp."
}

