        "code": "cat > /etc/docker/daemon.json <<JSON\n{\n  \"log-driver\": \"json-file\",\n  \"log-opts\": {\n    \"max-size\": \"{{input.max_size}}\",\n    \"max-file\": \"{{input.max_files}}\"\n  }\n}\nJSON",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "max_size": {
              "type": "string"
