{
  "fields": {
    "name": "blue-green-single",
    "description": "Blue-green deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "detect-active-slot",
        "action_type": "SHELL",
        "code": "ACTIVE=$(readlink {{input.app_dir}}/current); if [ \"$ACTIVE\" = \"{{input.app_dir}}/blue\" ]; then echo green > /tmp/deploy_slot; else echo blue > /tmp/deploy_slot; fi",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "repo_url": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "repo_url",
            "branch"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clone-to-inactive",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && rm -rf {{input.app_dir}}/$SLOT && git clone -b {{input.branch}} {{input.repo_url}} {{input.app_dir}}/$SLOT",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps-new",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm ci",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "test-new-slot",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm test",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "switch-symlink",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && ln -sfn {{input.app_dir}}/$SLOT {{input.app_dir}}/current",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-app",
        "action_type": "SHELL",
        "code": "systemctl restart app",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:3000/health",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-blue-green",
        "action_type": "SHELL",
        "code": "ACTIVE=$(cat /tmp/deploy_slot); if [ \"$ACTIVE\" = \"green\" ]; then OTHER=blue; else OTHER=green; fi && ln -sfn {{input.app_dir}}/$OTHER {{input.app_dir}}/current && systemctl restart app",
        "parent_step_ids": [
          "5"
        ]
      }
    ]
  },
  "explanation": "Blue-green: detect active slot, clone to inactive, install, test, swap symlink, restart, health check."
}

{
  "fields": {
    "name": "dkim-signing",
    "description": "Set up OpenDKIM for email signing",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-opendkim",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y opendkim opendkim-tools",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-key-dir",
        "action_type": "SHELL",
        "code": "mkdir -p /etc/opendkim/keys/{{input.domain}} && chown -R opendkim:opendkim /etc/opendkim",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "domain": {
              "type": "string"
            },
            "selector": {
              "type": "string"
            }
          },
          "required": [
            "domain",
            "selector"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "generate-dkim-key",
        "action_type": "SHELL",
        "code": "opendkim-genkey -s {{input.selector}} -d {{input.domain}} -D /etc/opendkim/keys/{{input.domain}} && chown opendkim:opendkim /etc/opendkim/keys/{{input.domain}}/*",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "configure-opendkim",
        "action_type": "SHELL",
        "code": "cat > /etc/opendkim.conf <<DKIM\nSyslog yes\nDomain {{input.domain}}\nSelector {{input.selector}}\nKeyFile /etc/opendkim/keys/{{input.domain}}/{{input.selector}}.private\nSocket inet:8891@localhost\nCanonicalization relaxed/simple\nMode sv\nDKIM",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"milter_default_action = accept\" && postconf -e \"milter_protocol = 6\" && postconf -e \"smtpd_milters = inet:localhost:8891\" && postconf -e \"non_smtpd_milters = inet:localhost:8891\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-opendkim",
        "action_type": "SHELL",
        "code": "systemctl enable --now opendkim && systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "show-dns-record",
        "action_type": "SHELL",
        "code": "cat /etc/opendkim/keys/{{input.domain}}/{{input.selector}}.txt",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-dkim",
        "action_type": "SHELL",
        "code": "systemctl stop opendkim; postconf -e \"smtpd_milters =\" && postconf -e \"non_smtpd_milters =\" && systemctl restart postfix; apt-get remove -y opendkim opendkim-tools",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "DKIM: install OpenDKIM, generate key, configure, integrate with Postfix, start, show DNS record."
}

{
  "fields": {
