{
  "fields": {
    "name": "Check SSL cert for web-server",
    "action_type": "PYTHON",
    "code": "import ssl
import socket
import json
import sys
from datetime import datetime

hostname = "{{input.hostname}}"
port = int("{{input.port}}" or "443")
warn_days = int("{{input.warn_days}}" or "30")

try:
    ctx = ssl.create_default_context()
    with socket.create_connection((hostname, port), timeout=10) as sock:
        with ctx.wrap_socket(sock, server_hostname=hostname) as ssock:
            cert = ssock.getpeercert()
    not_after = cert.get("notAfter", "")
    expiry = datetime.strptime(not_after, "%b %d %H:%M:%S %Y %Z")
    days_left = (expiry - datetime.utcnow()).days
    issuer = dict(x[0] for x in cert.get("issuer", []))
    subject = dict(x[0] for x in cert.get("subject", []))
    print(json.dumps({{
        "status": "warning" if days_left < warn_days else "ok",
        "hostname": hostname,
        "issuer": issuer.get("organizationName", "unknown"),
        "subject_cn": subject.get("commonName", "unknown"),
        "expires": not_after,
        "days_left": days_left,
    }}))
    if days_left < warn_days:
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "hostname": {
          "type": "string",
          "description": "Hostname to check SSL certificate"
        },
        "port": {
          "type": "string",
          "description": "Port number (default 443)"
        },
        "warn_days": {
          "type": "string",
          "description": "Warn if cert expires within N days (default 30)"
        }
      },
      "required": [
        "hostname"
      ]
    }
  },
  "explanation": "Python action that checks the SSL certificate of a web-server, reporting issuer, expiry date, and days remaining."
}

