{
  "fields": {
    "name": "Push metric to Prometheus",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\npushgateway_url = \"{{input.pushgateway_url}}\"\njob_name = \"{{input.job_name}}\"\nmetric_name = \"{{input.metric_name}}\"\nmetric_value = \"{{input.metric_value}}\"\nmetric_help = \"{{input.metric_help}}\" or \"Custom metric\"\nmetric_type = \"{{input.metric_type}}\" or \"gauge\"\n\nbody = (\n    f\"# HELP {{metric_name}} {{metric_help}}\\n\"\n    f\"# TYPE {{metric_name}} {{metric_type}}\\n\"\n    f\"{{metric_name}} {{metric_value}}\\n\"\n)\n\nurl = f\"{{pushgateway_url}}/metrics/job/{{job_name}}\"\nreq = urllib.request.Request(url, data=body.encode(\"utf-8\"), method=\"POST\")\nreq.add_header(\"Content-Type\", \"text/plain\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=10)\n    print(json.dumps({{\n        \"status\": \"pushed\",\n        \"metric\": metric_name,\n        \"value\": metric_value,\n        \"job\": job_name,\n    }}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "pushgateway_url": {
          "type": "string",
          "description": "Prometheus Pushgateway base URL"
        },
        "job_name": {
          "type": "string",
          "description": "Job label for the metric"
        },
        "metric_name": {
          "type": "string",
          "description": "Metric name"
        },
        "metric_value": {
          "type": "string",
          "description": "Metric value"
        },
        "metric_help": {
          "type": "string",
          "description": "Metric help text (optional)"
        },
        "metric_type": {
          "type": "string",
          "description": "Metric type: gauge, counter (default gauge)"
        }
      },
      "required": [
        "pushgateway_url",
        "job_name",
        "metric_name",
        "metric_value"
      ]
    }
  },
  "explanation": "Python action that pushes a custom gauge metric to Prometheus Pushgateway for monitoring."
}

{
  "fields": {
    "name": "uptime-monitor-setup",
    "description": "Set up endpoint uptime monitoring",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-check-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/uptime-check.sh <<SCRIPT\n#!/bin/bash\nLOGFILE=/var/log/uptime-monitor.log\nfor URL in {{input.urls}}; do\n  STATUS=$(curl -sf -o /dev/null -w \"%%{http_code}\" --max-time 10 \"$URL\" 2>/dev/null)\n  echo \"$(date -Iseconds) $URL $STATUS\" >> $LOGFILE\n  if [ \"$STATUS\" != \"200\" ]; then\n    echo \"ALERT: $URL returned $STATUS\" | logger -t uptime-monitor\n  fi\ndone\nSCRIPT\nchmod +x /usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "urls": {
              "type": "string"
            },
            "interval_min": {
              "type": "string"
            }
          },
          "required": [
            "urls",
            "interval_min"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-log-file",
        "action_type": "SHELL",
        "code": "touch /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "add-cron-job",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/{{input.interval_min}} * * * * /usr/local/bin/uptime-check.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-initial-check",
        "action_type": "SHELL",
        "code": "/usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-log-output",
        "action_type": "SHELL",
        "code": "test -s /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-uptime-monitor",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v uptime-check | crontab - && rm -f /usr/local/bin/uptime-check.sh /var/log/uptime-monitor.log",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Uptime monitor: create check script, add cron job, run initial check, verify log."
}

{
  "fields": {
    "name": "private-registry",
    "description": "Deploy private Docker registry",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-registry-dirs",
        "action_type": "SHELL",
        "code": "mkdir -p /opt/registry/data /opt/registry/auth /opt/registry/certs",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-htpasswd",
        "action_type": "SHELL",
        "code": "docker run --rm --entrypoint htpasswd httpd:2 -Bbn {{input.reg_user}} {{input.reg_pass}} > /opt/registry/auth/htpasswd",
        "target": "all",
        "parent_step_ids": [
          "1"
