{
  "fields": {
    "name": "Parse JSON config for docker",
    "action_type": "PYTHON",
    "code": "import json
import sys

config_path = "{{input.config_path}}"
key_path = "{{input.key_path}}"

try:
    with open(config_path, "r") as f:
        config = json.load(f)

    # Navigate nested keys via dot notation
    value = config
    if key_path:
        for key in key_path.split("."):
            if isinstance(value, dict):
                value = value[key]
            elif isinstance(value, list):
                value = value[int(key)]
            else:
                raise KeyError(f"Cannot traverse into {{type(value).__name__}}")

    print(json.dumps({{"status": "ok", "key": key_path, "value": value}}))
except FileNotFoundError:
    print(json.dumps({{"status": "error", "message": f"File not found: {{config_path}}"}}))
    sys.exit(1)
except (KeyError, IndexError) as e:
    print(json.dumps({{"status": "error", "message": f"Key not found: {{e}}"}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "config_path": {
          "type": "string",
          "description": "Path to JSON config file"
        },
        "key_path": {
          "type": "string",
          "description": "Dot-notation path to key (e.g. database.host)"
        }
      },
      "required": [
        "config_path"
      ]
    }
  },
  "explanation": "Python action that parses a docker JSON configuration file and extracts a value at a specified dot-notation key path."
}

