        "undo": false,
        "name": "format-swap",
        "action_type": "SHELL",
        "code": "mkswap /swapfile",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "enable-swap",
        "action_type": "SHELL",
        "code": "swapon /swapfile",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "persist-fstab",
        "action_type": "SHELL",
        "code": "grep -q \"/swapfile\" /etc/fstab || echo \"/swapfile none swap sw 0 0\" >> /etc/fstab",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "set-swappiness",
        "action_type": "SHELL",
        "code": "sysctl vm.swappiness={{input.swappiness}} && echo \"vm.swappiness={{input.swappiness}}\" > /etc/sysctl.d/99-swappiness.conf",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "8",
        "undo": false,
        "name": "verify-swap",
        "action_type": "SHELL",
        "code": "swapon --show | grep /swapfile && sysctl vm.swappiness",
        "target": "all",
        "parent_step_ids": [
          "6",
          "7"
        ],
        "expected_rc": 0
      },
      {
        "id": "9",
        "undo": true,
        "name": "undo-swap",
        "action_type": "SHELL",
        "code": "swapoff /swapfile 2>/dev/null; rm -f /swapfile /etc/sysctl.d/99-swappiness.conf; sed -i \"/\\/swapfile/d\" /etc/fstab; sysctl vm.swappiness=60",
