{
  "fields": {
    "name": "Tail log file for apache patterns",
    "action_type": "PYTHON",
    "code": "import json
import re
import os
import sys

log_file = "{{input.log_file}}"
pattern = "{{input.pattern}}"
max_lines = int("{{input.max_lines}}" or "1000")

if not os.path.isfile(log_file):
    print(json.dumps({{"status": "error", "message": f"Log file not found: {{log_file}}"}}))
    sys.exit(1)

try:
    regex = re.compile(pattern)
except re.error as e:
    print(json.dumps({{"status": "error", "message": f"Invalid regex: {{e}}"}}))
    sys.exit(1)

matches = []
with open(log_file, "r", errors="replace") as f:
    lines = f.readlines()[-max_lines:]
    for i, line in enumerate(lines):
        if regex.search(line):
            matches.append(line.strip())

result = {{
    "status": "ok",
    "log_file": log_file,
    "pattern": pattern,
    "lines_scanned": len(lines),
    "matches_found": len(matches),
    "recent_matches": matches[-20:],
}}
print(json.dumps(result))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "log_file": {
          "type": "string",
          "description": "Path to the log file to scan"
        },
        "pattern": {
          "type": "string",
          "description": "Regex pattern to match in log lines"
        },
        "max_lines": {
          "type": "string",
          "description": "Maximum number of recent lines to scan (default 1000)"
        }
      },
      "required": [
        "log_file",
        "pattern"
      ]
    }
  },
  "explanation": "Python action that scans the tail of a apache log file for lines matching a regex pattern and returns matches."
}

