{
  "fields": {
    "name": "pg-replica-prep",
    "description": "Prepare PostgreSQL for streaming replication",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-pg-conf",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf /etc/postgresql/*/main/postgresql.conf.repl.bak && cp /etc/postgresql/*/main/pg_hba.conf /etc/postgresql/*/main/pg_hba.conf.repl.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-wal-level",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*wal_level.*/wal_level = replica/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-wal-senders",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_wal_senders.*/max_wal_senders = 5/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "create-repl-user",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"CREATE USER {{input.repl_user}} WITH REPLICATION PASSWORD '{{input.repl_pass}}'\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "repl_user": {
              "type": "string"
            },
            "repl_pass": {
              "type": "string"
            },
            "replica_ip": {
              "type": "string"
            }
          },
          "required": [
            "repl_user",
            "repl_pass",
            "replica_ip"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "add-hba-entry",
        "action_type": "SHELL",
        "code": "echo \"host replication {{input.repl_user}} {{input.replica_ip}}/32 md5\" >> /etc/postgresql/*/main/pg_hba.conf",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-postgresql",
        "action_type": "SHELL",
        "code": "systemctl restart postgresql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-wal-level",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"SHOW wal_level\" | grep replica",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-repl-prep",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf.repl.bak /etc/postgresql/*/main/postgresql.conf && cp /etc/postgresql/*/main/pg_hba.conf.repl.bak /etc/postgresql/*/main/pg_hba.conf && systemctl restart postgresql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Replica prep: backup, set wal_level+max_wal_senders, create repl user, add HBA entry, restart, verify."
}

{
  "fields": {
    "name": "spamassassin-filter",
    "description": "Install and configure SpamAssassin",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-spamassassin",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y spamassassin spamc",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-spamd-user",
        "action_type": "SHELL",
        "code": "useradd -r -s /bin/false -d /var/lib/spamassassin spamd 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-rules",
        "action_type": "SHELL",
        "code": "cat > /etc/spamassassin/local.cf <<SPAM\nrewrite_header Subject [SPAM]\nrequired_score {{input.spam_score}}\nuse_bayes 1\nbayes_auto_learn 1\nSPAM",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "spam_score": {
              "type": "string"
            }
          },
          "required": [
            "spam_score"
          ]
        }
      },
      {
        "id": "4",
        "undo": false,
        "name": "update-rules",
        "action_type": "SHELL",
        "code": "sa-update",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"content_filter = smtp-amavis:[127.0.0.1]:10024\" 2>/dev/null; sed -i \"s/^ENABLED=0/ENABLED=1/\" /etc/default/spamassassin",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl enable --now spamassassin && systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-spamd",
        "action_type": "SHELL",
        "code": "echo \"Subject: Test\" | spamc -c; true",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl stop spamassassin; postconf -e \"content_filter =\"; systemctl restart postfix; apt-get remove -y spamassassin spamc",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "SpamAssassin: install, create user, configure rules + Bayes, update rules, integrate Postfix, verify."
}

