{
  "fields": {
    "name": "deploy-rails",
    "description": "Deploy Ruby on Rails app with asset pipeline",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-current",
        "action_type": "SHELL",
        "code": "cp -a {{input.app_dir}} {{input.app_dir}}.bak 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "rails_env": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "rails_env"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "pull-code",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "bundle-install",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && bundle install --deployment --without development test",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "db-migrate",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && RAILS_ENV={{input.rails_env}} bundle exec rake db:migrate",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "precompile-assets",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && RAILS_ENV={{input.rails_env}} bundle exec rake assets:precompile",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-puma",
        "action_type": "SHELL",
        "code": "systemctl restart puma",
        "target": "all",
        "parent_step_ids": [
