        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-rails-deploy",
        "action_type": "SHELL",
        "code": "rm -rf {{input.app_dir}} && mv {{input.app_dir}}.bak {{input.app_dir}} && systemctl restart puma",
        "parent_step_ids": [
          "2"
        ]
      }
    ]
  },
  "explanation": "Rails deploy: backup, pull, bundle, migrate+assets in parallel, restart puma, health check."
}

