{
  "fields": {
    "name": "mail-queue-mgmt",
    "description": "Mail queue inspection and management",
    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "show-queue-stats",
        "action_type": "SHELL",
        "code": "postqueue -p | tail -1",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "flush-deferred",
        "action_type": "SHELL",
        "code": "postqueue -f",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "delete-bounced",
        "action_type": "SHELL",
        "code": "postsuper -d ALL deferred",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-queue-empty",
        "action_type": "SHELL",
        "code": "QSIZE=$(postqueue -p | tail -1 | grep -c \"Mail queue is empty\"); test \"$QSIZE\" -ge 1 && echo \"Queue cleared\" || echo \"Queue still has messages\"",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "check-mail-log",
        "action_type": "SHELL",
        "code": "tail -20 /var/log/mail.log | grep -E \"(reject|bounce|error)\" | tail -5",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      }
    ]
  },
  "explanation": "Mail queue: show stats, flush deferred, delete bounced, verify empty, check error log."
}

