        "code": "test -s /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-uptime-monitor",
        "action_type": "SHELL",
