    "code": "- name: Set directory permissions on {{input.path}}\n  file:\n    path: \"{{input.path}}\"\n    state: directory\n    owner: \"{{input.owner}}\"\n    group: \"{{input.group}}\"\n    mode: \"{{input.dir_mode}}\"\n\n- name: Set file permissions recursively under {{input.path}}\n  command: \"find {{input.path}} -type f -exec chmod {{input.file_mode}} {} +\"\n  register: file_perms\n\n- name: Set directory permissions recursively under {{input.path}}\n  command: \"find {{input.path}} -type d -exec chmod {{input.dir_mode}} {} +\"\n  register: dir_perms\n\n- name: Set ownership recursively on {{input.path}}\n  file:\n    path: \"{{input.path}}\"\n    owner: \"{{input.owner}}\"\n    group: \"{{input.group}}\"\n    recurse: yes\n",
