{
  "fields": {
    "name": "Check API key expiry",
    "action_type": "PYTHON",
    "code": "import json
import os
import sys
from datetime import datetime, timezone

key_file = "{{input.key_file}}"
max_age_days = int("{{input.max_age_days}}" or "90")

if not os.path.isfile(key_file):
    print(json.dumps({{"status": "error", "message": f"Key file not found: {{key_file}}"}}))
    sys.exit(1)

mod_time = os.path.getmtime(key_file)
mod_dt = datetime.fromtimestamp(mod_time, tz=timezone.utc)
now = datetime.now(timezone.utc)
age_days = (now - mod_dt).days
expired = age_days > max_age_days

print(json.dumps({{
    "status": "expired" if expired else "ok",
    "key_file": key_file,
    "age_days": age_days,
    "max_age_days": max_age_days,
    "last_modified": mod_dt.isoformat(),
}}))
if expired:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "key_file": {
          "type": "string",
          "description": "Path to the API key file"
        },
        "max_age_days": {
          "type": "string",
          "description": "Maximum key age in days (default 90)"
        }
      },
      "required": [
        "key_file"
      ]
    }
  },
  "explanation": "Python action that checks the age of a monitoring API key file and alerts if it exceeds the maximum age."
}

{
  "fields": {
    "name": "Ping MySQL server",
    "action_type": "PYTHON",
    "code": "import json\nimport socket\nimport sys\n\nhost = \"{{input.host}}\" or \"localhost\"\nport = int(\"{{input.port}}\" or \"3306\")\ntimeout = int(\"{{input.timeout}}\" or \"5\")\n\ntry:\n    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n    sock.settimeout(timeout)\n    sock.connect((host, port))\n    greeting = sock.recv(1024)\n    sock.close()\n    if len(greeting) > 4:\n        version_end = greeting.find(b\"\\x00\", 5)\n        version = greeting[5:version_end].decode(\"utf-8\", errors=\"replace\") if version_end > 5 else \"unknown\"\n        print(json.dumps({{\"status\": \"ok\", \"host\": host, \"port\": port, \"version\": version}}))\n    else:\n        print(json.dumps({{\"status\": \"ok\", \"host\": host, \"port\": port, \"message\": \"MySQL responded\"}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "MySQL host (default localhost)"
        },
        "port": {
          "type": "string",
          "description": "MySQL port (default 3306)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 5)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that pings the production MySQL server by connecting via socket and reading the protocol greeting."
}

