{
  "fields": {
    "name": "SQLite integrity check",
    "action_type": "PYTHON",
    "code": "import json
import sqlite3
import os
import sys

db_path = "{{input.db_path}}"

if not os.path.isfile(db_path):
    print(json.dumps({{"status": "error", "message": f"Database not found: {{db_path}}"}}))
    sys.exit(1)

try:
    conn = sqlite3.connect(db_path)
    cursor = conn.execute("PRAGMA integrity_check")
    results = cursor.fetchall()
    conn.close()
    ok = all(row[0] == "ok" for row in results)
    size_bytes = os.path.getsize(db_path)
    print(json.dumps({{
        "status": "ok" if ok else "corrupt",
        "db_path": db_path,
        "size_bytes": size_bytes,
        "integrity": [row[0] for row in results],
    }}))
    if not ok:
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "db_path": {
          "type": "string",
          "description": "Path to SQLite database file"
        }
      },
      "required": [
        "db_path"
      ]
    }
  },
  "explanation": "Python action that runs PRAGMA integrity_check on a audit SQLite database and reports the result."
}

