{
  "fields": {
    "name": "Check open file descriptors",
    "action_type": "PYTHON",
    "code": "import json
import sys

threshold_pct = float("{{input.threshold_pct}}" or "80")

with open("/proc/sys/fs/file-nr", "r") as f:
    parts = f.read().strip().split()
    allocated = int(parts[0])
    free = int(parts[1])
    maximum = int(parts[2])

used = allocated - free
pct = (used / maximum) * 100.0 if maximum > 0 else 0.0

result = {{
    "allocated": allocated,
    "free": free,
    "used": used,
    "maximum": maximum,
    "percent_used": round(pct, 2),
    "threshold": threshold_pct,
    "status": "critical" if pct > threshold_pct else "ok",
}}
print(json.dumps(result))
if pct > threshold_pct:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "threshold_pct": {
          "type": "string",
          "description": "Usage threshold percentage (default 80)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/sys/fs/file-nr to check system-wide open file descriptor usage."
}

