    "stop_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-backup-dir",
        "action_type": "SHELL",
        "code": "mkdir -p {{input.backup_dir}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "volume_name": {
              "type": "string"
            },
            "backup_dir": {
              "type": "string"
            }
