{
  "fields": {
    "name": "Diff two config files",
    "action_type": "PYTHON",
    "code": "import json
import difflib
import sys

file_a = "{{input.file_a}}"
file_b = "{{input.file_b}}"

try:
    with open(file_a, "r") as f:
        lines_a = f.readlines()
    with open(file_b, "r") as f:
        lines_b = f.readlines()

    diff = list(difflib.unified_diff(lines_a, lines_b, fromfile=file_a, tofile=file_b, lineterm=""))
    has_changes = len(diff) > 0
    added = sum(1 for l in diff if l.startswith("+") and not l.startswith("+++"))
    removed = sum(1 for l in diff if l.startswith("-") and not l.startswith("---"))

    print(json.dumps({{
        "status": "changed" if has_changes else "identical",
        "lines_added": added,
        "lines_removed": removed,
        "diff": "\n".join(diff[:50]),
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "file_a": {
          "type": "string",
          "description": "Path to first config file"
        },
        "file_b": {
          "type": "string",
          "description": "Path to second config file"
        }
      },
      "required": [
        "file_a",
        "file_b"
      ]
    }
  },
  "explanation": "Python action that generates a unified diff between two fstab configuration files, reporting added and removed lines."
}

