{
  "fields": {
    "name": "test-runner-notify",
    "description": "Run test suite and send notification",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "webhook_url": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "webhook_url"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pip install -r requirements.txt",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pytest --junitxml=/tmp/test-results.xml 2>&1 | tee /tmp/test-output.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "notify-success",
        "action_type": "SHELL",
        "code": "PASS=$(grep -c \"passed\" /tmp/test-output.txt); curl -sf -X POST {{input.webhook_url}} -H \"Content-Type: application/json\" -d \"{\"text\":\"Tests passed: $PASS tests on {{input.branch}}\"}\"",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": true,
        "name": "notify-failure",
        "action_type": "SHELL",
        "code": "FAIL=$(tail -5 /tmp/test-output.txt); curl -sf -X POST {{input.webhook_url}} -H \"Content-Type: application/json\" -d \"{\"text\":\"Tests FAILED on {{input.branch}}: $FAIL\"}\"",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Test runner: pull, install deps, run pytest with XML report, notify webhook on success/failure."
}

{
  "fields": {
    "name": "system-tar-backup",
    "action_type": "SHELL",
    "code": "TIMESTAMP=$(date +%Y%m%d_%H%M%S) && ARCHIVE=\"{{input.backup_dir}}/{{input.backup_name}}_${TIMESTAMP}.tar.gz\" && mkdir -p {{input.backup_dir}} && tar czf \"$ARCHIVE\" --exclude={{input.backup_dir}} --exclude=/proc --exclude=/sys --exclude=/dev --exclude=/run --exclude=/tmp --exclude=/mnt --exclude=/media --exclude=/lost+found {{input.source_dir}} 2>&1 && FILESIZE=$(du -sh \"$ARCHIVE\" | cut -f1) && echo \"Full backup completed: $ARCHIVE ($FILESIZE)\" || (echo \"FAILED: tar backup error\" >&2; exit 1)",
    "expected_rc": 0,
    "schema": {
      "input": {
        "source_dir": {
          "type": "string",
          "description": "Root directory to back up (e.g. /)"
        },
        "backup_dir": {
          "type": "string",
          "description": "Directory to store the archive"
        },
        "backup_name": {
          "type": "string",
          "description": "Base name for the backup archive"
        }
      },
      "required": [
        "source_dir",
        "backup_dir",
        "backup_name"
      ]
    }
  },
  "explanation": "Creates a compressed tar archive of the full system filesystem, excluding virtual filesystems."
}

{
  "fields": {
    "name": "deploy-mongodb",
    "description": "Deploy MongoDB with auth enabled",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "import-mongo-key",
        "action_type": "SHELL",
        "code": "curl -fsSL https://pgp.mongodb.com/server-7.0.asc | gpg --dearmor -o /usr/share/keyrings/mongodb-server-7.0.gpg",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-mongo-repo",
        "action_type": "SHELL",
        "code": "echo \"deb [signed-by=/usr/share/keyrings/mongodb-server-7.0.gpg] https://repo.mongodb.org/apt/ubuntu jammy/mongodb-org/7.0 multiverse\" > /etc/apt/sources.list.d/mongodb-org-7.0.list && apt-get update",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-mongodb",
        "action_type": "SHELL",
        "code": "apt-get install -y mongodb-org",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-mongodb",
        "action_type": "SHELL",
        "code": "systemctl enable --now mongod",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "create-admin-user",
        "action_type": "SHELL",
        "code": "mongosh --eval \"use admin; db.createUser({user:\"{{input.admin_user}}\",pwd:\"{{input.admin_pass}}\",roles:[\"root\"]})\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "schema": {
          "input": {
            "admin_user": {
              "type": "string"
            },
            "admin_pass": {
              "type": "string"
            }
          },
          "required": [
            "admin_user",
            "admin_pass"
          ]
        }
      },
      {
        "id": "6",
        "undo": false,
        "name": "enable-auth",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#security:/security:\\n  authorization: enabled/\" /etc/mongod.conf && systemctl restart mongod",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-mongodb",
        "action_type": "SHELL",
        "code": "mongosh -u {{input.admin_user}} -p {{input.admin_pass}} --authenticationDatabase admin --eval \"db.runCommand({ping:1})\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-mongodb",
        "action_type": "SHELL",
        "code": "systemctl stop mongod; apt-get remove -y mongodb-org",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "MongoDB: import key, add repo, install, start, create admin, enable auth, verify."
}

