    "name": "Check MongoDB status",
    "action_type": "PYTHON",
    "code": "import json\nimport socket\nimport sys\n\nhost = \"{{input.host}}\" or \"localhost\"\nport = int(\"{{input.port}}\" or \"27017\")\ntimeout = int(\"{{input.timeout}}\" or \"5\")\n\ntry:\n    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n    sock.settimeout(timeout)\n    result = sock.connect_ex((host, port))\n    sock.close()\n    if result == 0:\n        print(json.dumps({{\"status\": \"ok\", \"host\": host, \"port\": port, \"message\": \"MongoDB port is reachable\"}}))\n    else:\n        print(json.dumps({{\"status\": \"error\", \"host\": host, \"port\": port, \"message\": \"Connection refused\"}}))\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "MongoDB host (default localhost)"
        },
        "port": {
          "type": "string",
          "description": "MongoDB port (default 27017)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 5)"
        }
      },
      "required": []
    }
  },
