{
  "fields": {
    "name": "db-migration-pipeline",
    "description": "CI pipeline with database migration",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "db_name": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "db_name"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "backup-database",
        "action_type": "SHELL",
        "code": "sudo -u postgres pg_dump {{input.db_name}} > /tmp/{{input.db_name}}_pre_ci.sql",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pip install -r requirements.txt",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
