    "name": "mysql-log-extract",
    "action_type": "SHELL",
    "code": "journalctl -u {{input.service_name}} --since \"{{input.since}}\" --no-pager --priority={{input.priority}} -o json 2>&1 | head -n {{input.max_lines}} && echo \"Log extraction complete for {{input.service_name}}\"",
    "expected_rc": 0,
    "schema": {
      "input": {
        "service_name": {
          "type": "string",
          "description": "Name of the systemd service"
        },
        "since": {
          "type": "string",
          "description": "Time range (e.g. \"1 hour ago\", \"today\")"
        },
        "priority": {
          "type": "string",
          "description": "Minimum priority level (emerg, alert, crit, err, warning, notice, info, debug)"
        },
        "max_lines": {
          "type": "integer",
          "description": "Maximum number of log lines to return"
        }
      },
      "required": [
        "service_name",
        "since",
        "priority",
        "max_lines"
      ]
    }
  },
  "explanation": "Extracts journal logs from the mysql service filtered by time range and priority in JSON format."
}

{
  "fields": {
    "name": "container-log-collect",
    "description": "Set up centralized container log collection",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "configure-log-driver",
        "action_type": "SHELL",
        "code": "cat > /etc/docker/daemon.json <<JSON\n{\n  \"log-driver\": \"json-file\",\n  \"log-opts\": {\n    \"max-size\": \"{{input.max_size}}\",\n    \"max-file\": \"{{input.max_files}}\"\n  }\n}\nJSON",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "max_size": {
              "type": "string"
            },
            "max_files": {
              "type": "string"
            }
          },
          "required": [
            "max_size",
            "max_files"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "restart-docker",
        "action_type": "SHELL",
        "code": "systemctl restart docker",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "deploy-log-aggregator",
        "action_type": "SHELL",
        "code": "docker run -d --name log-aggregator --restart unless-stopped -v /var/lib/docker/containers:/var/lib/docker/containers:ro -v /var/run/docker.sock:/var/run/docker.sock:ro -p 24224:24224 fluent/fluentd:v1.16-1",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-log-driver",
        "action_type": "SHELL",
        "code": "docker info --format \"{{.LoggingDriver}}\" | grep json-file",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-aggregator",
        "action_type": "SHELL",
        "code": "sleep 3 && docker logs log-aggregator 2>&1 | head -3",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-log-collection",
        "action_type": "SHELL",
        "code": "docker stop log-aggregator 2>/dev/null; docker rm log-aggregator 2>/dev/null; rm /etc/docker/daemon.json; systemctl restart docker",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Container logs: configure JSON log driver with rotation, restart Docker, deploy fluentd aggregator, verify."
}

