{
  "fields": {
    "name": "Check gcp-lb LB status",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\napi_url = \"{{input.api_url}}\"\napi_key = \"{{input.api_key}}\"\nlb_id = \"{{input.lb_id}}\"\n\nurl = f\"{{api_url}}/{{lb_id}}/status\"\nreq = urllib.request.Request(url, method=\"GET\")\nreq.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    data = json.loads(resp.read().decode())\n    healthy = data.get(\"status\", \"\").lower() in (\"active\", \"healthy\", \"running\")\n    print(json.dumps({{\"status\": \"healthy\" if healthy else \"unhealthy\", \"lb_id\": lb_id, \"details\": data}}))\n    if not healthy:\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "api_url": {
          "type": "string",
          "description": "Load balancer API base URL"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        },
        "lb_id": {
          "type": "string",
          "description": "Load balancer ID"
        }
      },
      "required": [
        "api_url",
        "api_key",
        "lb_id"
      ]
    }
  },
  "explanation": "Python action that checks the status of a gcp-lb load balancer via API."
}

{
  "fields": {
    "name": "log-alerting",
    "description": "Set up log-based alerting",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-alert-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/log-alert.sh <<SCRIPT\n#!/bin/bash\nPATTERN=\"{{input.alert_pattern}}\"\nLOGFILE=\"{{input.log_path}}\"\nERRORS=$(tail -100 \"$LOGFILE\" | grep -c \"$PATTERN\")\nif [ \"$ERRORS\" -gt {{input.threshold}} ]; then\n  echo \"ALERT: $ERRORS matches for $PATTERN in $LOGFILE\" | logger -t log-alert\nfi\nSCRIPT\nchmod +x /usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/5 * * * * /usr/local/bin/log-alert.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-alert-script",
        "action_type": "SHELL",
        "code": "/usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": true,
        "name": "undo-log-alerting",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v log-alert | crontab - && rm -f /usr/local/bin/log-alert.sh",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Log alerting: create alert script, add cron, test. Matches pattern in log and fires syslog alert."
}

{
  "fields": {
    "name": "spamassassin-filter",
    "description": "Install and configure SpamAssassin",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-spamassassin",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y spamassassin spamc",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-spamd-user",
        "action_type": "SHELL",
        "code": "useradd -r -s /bin/false -d /var/lib/spamassassin spamd 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-rules",
        "action_type": "SHELL",
        "code": "cat > /etc/spamassassin/local.cf <<SPAM\nrewrite_header Subject [SPAM]\nrequired_score {{input.spam_score}}\nuse_bayes 1\nbayes_auto_learn 1\nSPAM",
        "target": "all",
        "parent_step_ids": [
          "1"
