{
  "fields": {
    "name": "GraphQL query to github",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nurl = \"{{input.graphql_url}}\"\nquery = \"{{input.query}}\"\nvariables = json.loads('{{input.variables}}' or \"{{}}\")\n\npayload = json.dumps({{\"query\": query, \"variables\": variables}}).encode(\"utf-8\")\nreq = urllib.request.Request(url, data=payload, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"Authorization\", \"Bearer {{input.api_token}}\")\n\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    result = json.loads(resp.read().decode())\n    if \"errors\" in result:\n        print(json.dumps({{\"status\": \"error\", \"errors\": result[\"errors\"]}}))\n        sys.exit(1)\n    print(json.dumps({{\"status\": \"ok\", \"data\": result.get(\"data\", {{}})}}))\nexcept urllib.error.HTTPError as e:\n    print(json.dumps({{\"status\": \"error\", \"code\": e.code}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "graphql_url": {
          "type": "string",
          "description": "GraphQL endpoint URL"
        },
        "query": {
          "type": "string",
          "description": "GraphQL query string"
        },
        "variables": {
          "type": "string",
          "description": "JSON string of query variables"
        },
        "api_token": {
          "type": "string",
          "description": "Bearer token for auth"
        }
      },
      "required": [
        "graphql_url",
        "query",
        "api_token"
      ]
    }
  },
  "explanation": "Python action that executes a GraphQL query against github API with variables and bearer token auth."
}

