{
  "fields": {
    "name": "Patch JSON config file",
    "action_type": "ANSIBLE",
    "code": "- name: Read current {{input.file_path}} content\n  slurp:\n    src: \"{{input.file_path}}\"\n  register: json_content\n\n- name: Parse and patch JSON\n  set_fact:\n    json_data: \"{{ json_content.content | b64decode | from_json | combine(input.patch_data | from_json, recursive=True) }}\"\n\n- name: Write patched JSON to {{input.file_path}}\n  copy:\n    content: \"{{ json_data | to_nice_json }}\"\n    dest: \"{{input.file_path}}\"\n    backup: yes\n    mode: \"{{input.mode}}\"\n\n- name: Validate JSON syntax\n  command: \"python3 -c \\\"import json; json.load(open('{{input.file_path}}')); print('Valid JSON')\\\"\"\n  register: json_check\n  changed_when: false\n",
    "schema": {
      "input": {
        "file_path": {
          "type": "string",
          "description": "Path to the JSON file to patch"
        },
        "patch_data": {
          "type": "string",
          "description": "JSON string with keys to merge/update"
        },
        "mode": {
          "type": "string",
          "description": "File permissions (default 0644)"
        }
      },
      "required": [
        "file_path",
        "patch_data"
      ]
    }
  },
  "explanation": "Ansible action that reads, patches, and writes a manifest.json JSON file using recursive merge with backup and validation."
