{
  "fields": {
    "name": "Generate random api-key",
    "action_type": "PYTHON",
    "code": "import secrets
import json
import sys

length = int("{{input.length}}" or "32")
format_type = "{{input.format}}" or "hex"

if format_type == "hex":
    token = secrets.token_hex(length)
elif format_type == "urlsafe":
    token = secrets.token_urlsafe(length)
elif format_type == "bytes":
    import base64
    token = base64.b64encode(secrets.token_bytes(length)).decode()
else:
    token = secrets.token_hex(length)

print(json.dumps({{
    "status": "ok",
    "token": token,
    "format": format_type,
    "length": length,
}}))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "length": {
          "type": "string",
          "description": "Token length in bytes (default 32)"
        },
        "format": {
          "type": "string",
          "description": "Token format: hex, urlsafe, bytes (default hex)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that generates a cryptographically secure random api-key using the secrets module."
}

