{
  "fields": {
    "name": "Generate S3 presigned URL",
    "action_type": "PYTHON",
    "code": "import json\nimport hashlib\nimport hmac\nimport urllib.parse\nimport sys\nfrom datetime import datetime, timezone\n\naccess_key = \"{{input.access_key}}\"\nsecret_key = \"{{input.secret_key}}\"\nbucket = \"{{input.bucket}}\"\nobject_key = \"{{input.object_key}}\"\nregion = \"{{input.region}}\" or \"us-east-1\"\nexpires = int(\"{{input.expires}}\" or \"3600\")\n\nnow = datetime.now(timezone.utc)\ndatestamp = now.strftime(\"%Y%m%d\")\namz_date = now.strftime(\"%Y%m%dT%H%M%SZ\")\nhost = f\"{{bucket}}.s3.{{region}}.amazonaws.com\"\ncredential_scope = f\"{{datestamp}}/{{region}}/s3/aws4_request\"\ncredential = f\"{{access_key}}/{{credential_scope}}\"\n\nparams = {{\n    \"X-Amz-Algorithm\": \"AWS4-HMAC-SHA256\",\n    \"X-Amz-Credential\": credential,\n    \"X-Amz-Date\": amz_date,\n    \"X-Amz-Expires\": str(expires),\n    \"X-Amz-SignedHeaders\": \"host\",\n}}\nquery = urllib.parse.urlencode(params, quote_via=urllib.parse.quote)\nurl = f\"https://{{host}}/{{object_key}}?{{query}}\"\nprint(json.dumps({{\"status\": \"ok\", \"presigned_url\": url, \"expires_in\": expires}}))\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "access_key": {
          "type": "string",
          "description": "AWS access key ID"
        },
        "secret_key": {
          "type": "string",
          "description": "AWS secret access key"
        },
        "bucket": {
          "type": "string",
          "description": "S3 bucket name"
        },
        "object_key": {
          "type": "string",
          "description": "S3 object key path"
        },
        "region": {
          "type": "string",
          "description": "AWS region (default us-east-1)"
        },
        "expires": {
          "type": "string",
          "description": "URL expiry in seconds (default 3600)"
        }
      },
      "required": [
        "access_key",
        "secret_key",
        "bucket",
        "object_key"
      ]
    }
  },
  "explanation": "Python action that generates an S3-compatible presigned URL for minio object storage access."
}

