    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "detect-active-slot",
        "action_type": "SHELL",
        "code": "ACTIVE=$(readlink {{input.app_dir}}/current); if [ \"$ACTIVE\" = \"{{input.app_dir}}/blue\" ]; then echo green > /tmp/deploy_slot; else echo blue > /tmp/deploy_slot; fi",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "repo_url": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "repo_url",
            "branch"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clone-to-inactive",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && rm -rf {{input.app_dir}}/$SLOT && git clone -b {{input.branch}} {{input.repo_url}} {{input.app_dir}}/$SLOT",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps-new",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm ci",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "test-new-slot",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm test",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "switch-symlink",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && ln -sfn {{input.app_dir}}/$SLOT {{input.app_dir}}/current",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-app",
        "action_type": "SHELL",
        "code": "systemctl restart app",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:3000/health",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-blue-green",
        "action_type": "SHELL",
        "code": "ACTIVE=$(cat /tmp/deploy_slot); if [ \"$ACTIVE\" = \"green\" ]; then OTHER=blue; else OTHER=green; fi && ln -sfn {{input.app_dir}}/$OTHER {{input.app_dir}}/current && systemctl restart app",
        "parent_step_ids": [
          "5"
        ]
      }
    ]
  },
  "explanation": "Blue-green: detect active slot, clone to inactive, install, test, swap symlink, restart, health check."
}

{
  "fields": {
    "name": "artifact-cleanup",
    "description": "Clean up old CI/CD artifacts and images",
    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "clean-old-backups",
        "action_type": "SHELL",
        "code": "find /var/backups/app_* -maxdepth 0 -mtime +{{input.retention_days}} -exec rm -rf {} \\; 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "retention_days": {
              "type": "string"
            },
            "registry": {
              "type": "string"
            },
            "image_name": {
              "type": "string"
            }
          },
          "required": [
            "retention_days"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clean-docker-images",
        "action_type": "SHELL",
        "code": "docker image prune -a --filter \"until={{input.retention_days}}d\" -f 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "clean-build-caches",
        "action_type": "SHELL",
        "code": "docker builder prune -f --keep-storage=5GB 2>/dev/null; npm cache clean --force 2>/dev/null; pip cache purge 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "4",
        "undo": false,
        "name": "clean-test-artifacts",
        "action_type": "SHELL",
        "code": "find /tmp -name \"test-results*.xml\" -mtime +7 -delete 2>/dev/null; find /tmp -name \"*_pre_ci.sql\" -mtime +3 -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "5",
        "undo": false,
        "name": "report-disk-freed",
        "action_type": "SHELL",
        "code": "df -h / | tail -1",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2",
          "3",
          "4"
        ]
      }
    ]
  },
  "explanation": "Artifact cleanup: parallel clean old backups, docker images, build caches, test artifacts, then report disk."
}

