{
  "fields": {
    "name": "Hash password with pbkdf2",
    "action_type": "PYTHON",
    "code": "import hashlib
import os
import json
import sys

password = "{{input.password}}"
algorithm = "{{input.algorithm}}" or "sha256"
salt_length = int("{{input.salt_length}}" or "16")

salt = os.urandom(salt_length)
salt_hex = salt.hex()

if algorithm == "sha256":
    hashed = hashlib.sha256(salt + password.encode()).hexdigest()
elif algorithm == "sha512":
    hashed = hashlib.sha512(salt + password.encode()).hexdigest()
elif algorithm == "pbkdf2":
    dk = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 100000)
    hashed = dk.hex()
else:
    print(json.dumps({{"status": "error", "message": f"Unsupported algorithm: {{algorithm}}"}}))
    sys.exit(1)

print(json.dumps({{
    "status": "ok",
    "algorithm": algorithm,
    "salt": salt_hex,
    "hash": hashed,
}}))
",
    "expected_rc": 0,
    "schema": {
