          "description": "Hash algorithm: sha256, sha512, pbkdf2 (default sha256)"
        },
        "salt_length": {
          "type": "string",
          "description": "Salt length in bytes (default 16)"
        }
      },
      "required": [
        "password"
      ]
    }
  },
  "explanation": "Python action that hashes a password using pbkdf2 with a random salt for secure storage."
}

