{
  "fields": {
    "name": "Schema diff for mariadb databases",
    "action_type": "PYTHON",
    "code": "import json
import sqlite3
import sys

db_path_a = "{{input.db_path_a}}"
db_path_b = "{{input.db_path_b}}"

def get_schema(db_path):
    conn = sqlite3.connect(db_path)
    tables = {{}}
    for (name,) in conn.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name").fetchall():
        cols = conn.execute(f"PRAGMA table_info({{name}})").fetchall()
        tables[name] = [(c[1], c[2], c[3], c[5]) for c in cols]
    conn.close()
    return tables

try:
    schema_a = get_schema(db_path_a)
    schema_b = get_schema(db_path_b)
    diffs = []
    all_tables = set(list(schema_a.keys()) + list(schema_b.keys()))
    for t in sorted(all_tables):
        if t not in schema_a:
            diffs.append({{"type": "table_added", "table": t}})
        elif t not in schema_b:
            diffs.append({{"type": "table_removed", "table": t}})
        elif schema_a[t] != schema_b[t]:
            diffs.append({{"type": "table_changed", "table": t, "a_cols": len(schema_a[t]), "b_cols": len(schema_b[t])}})
    print(json.dumps({{
        "status": "ok" if not diffs else "differences_found",
        "tables_a": len(schema_a),
        "tables_b": len(schema_b),
        "differences": diffs,
        "diff_count": len(diffs),
    }}))
    if diffs:
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "db_path_a": {
          "type": "string",
          "description": "Path to the first SQLite database"
        },
        "db_path_b": {
          "type": "string",
          "description": "Path to the second SQLite database"
        }
      },
      "required": [
        "db_path_a",
        "db_path_b"
      ]
    }
  },
  "explanation": "Python action that compares table schemas between two mariadb databases and reports added, removed, and changed tables."
}

