{
  "fields": {
    "name": "temp-file-cleanup",
    "description": "Clean temporary files and caches",
    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "clean-tmp-old",
        "action_type": "SHELL",
        "code": "find /tmp -type f -mtime +{{input.days_old}} -delete 2>/dev/null; find /tmp -type d -empty -mtime +{{input.days_old}} -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "days_old": {
              "type": "string"
            }
          },
          "required": [
            "days_old"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clean-var-tmp",
        "action_type": "SHELL",
        "code": "find /var/tmp -type f -mtime +{{input.days_old}} -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "truncate-large-logs",
        "action_type": "SHELL",
        "code": "find /var/log -name \"*.log\" -size +100M -exec truncate -s 10M {} \\; 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "4",
        "undo": false,
        "name": "clean-journal",
        "action_type": "SHELL",
        "code": "journalctl --vacuum-time={{input.days_old}}d --vacuum-size=500M 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "5",
        "undo": false,
        "name": "clean-thumbnail-cache",
        "action_type": "SHELL",
        "code": "find /home -path \"*/.cache/thumbnails\" -type d -exec rm -rf {} + 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "6",
        "undo": false,
        "name": "report-freed-space",
        "action_type": "SHELL",
        "code": "df -h / /tmp /var",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2",
          "3",
          "4",
          "5"
        ]
      }
    ]
  },
  "explanation": "Temp cleanup: parallel clean /tmp, /var/tmp, truncate logs, vacuum journal, remove caches, report space."
}

{
  "fields": {
    "name": "deploy-pgbouncer",
    "description": "Deploy PgBouncer connection pooler",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-pgbouncer",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y pgbouncer",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-pgbouncer",
        "action_type": "SHELL",
        "code": "cat > /etc/pgbouncer/pgbouncer.ini <<INI\n[databases]\n{{input.db_name}} = host=127.0.0.1 port=5432 dbname={{input.db_name}}\n[pgbouncer]\nlisten_addr = 127.0.0.1\nlisten_port = 6432\nauth_type = md5\nauth_file = /etc/pgbouncer/userlist.txt\npool_mode = transaction\nmax_client_conn = {{input.max_clients}}\ndefault_pool_size = {{input.pool_size}}\nINI",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "db_name": {
              "type": "string"
            },
            "db_user": {
              "type": "string"
            },
            "db_pass": {
              "type": "string"
            },
            "max_clients": {
              "type": "string"
            },
            "pool_size": {
              "type": "string"
            }
          },
          "required": [
            "db_name",
            "db_user",
            "db_pass",
            "max_clients",
            "pool_size"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "write-userlist",
        "action_type": "SHELL",
        "code": "echo \"\"{{input.db_user}}\" \"{{input.db_pass}}\"\" > /etc/pgbouncer/userlist.txt && chmod 640 /etc/pgbouncer/userlist.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl enable --now pgbouncer",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-pgbouncer",
        "action_type": "SHELL",
        "code": "psql -h 127.0.0.1 -p 6432 -U {{input.db_user}} {{input.db_name}} -c \"SELECT 1\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl stop pgbouncer; apt-get remove -y pgbouncer",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "PgBouncer: install, configure pool, write userlist, start, verify connectivity."
}

