{
  "fields": {
    "name": "spamassassin-filter",
    "description": "Install and configure SpamAssassin",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-spamassassin",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y spamassassin spamc",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-spamd-user",
        "action_type": "SHELL",
        "code": "useradd -r -s /bin/false -d /var/lib/spamassassin spamd 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-rules",
        "action_type": "SHELL",
        "code": "cat > /etc/spamassassin/local.cf <<SPAM\nrewrite_header Subject [SPAM]\nrequired_score {{input.spam_score}}\nuse_bayes 1\nbayes_auto_learn 1\nSPAM",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "spam_score": {
              "type": "string"
            }
          },
          "required": [
            "spam_score"
          ]
        }
      },
      {
        "id": "4",
        "undo": false,
        "name": "update-rules",
        "action_type": "SHELL",
        "code": "sa-update",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"content_filter = smtp-amavis:[127.0.0.1]:10024\" 2>/dev/null; sed -i \"s/^ENABLED=0/ENABLED=1/\" /etc/default/spamassassin",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl enable --now spamassassin && systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-spamd",
        "action_type": "SHELL",
        "code": "echo \"Subject: Test\" | spamc -c; true",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl stop spamassassin; postconf -e \"content_filter =\"; systemctl restart postfix; apt-get remove -y spamassassin spamc",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "SpamAssassin: install, create user, configure rules + Bayes, update rules, integrate Postfix, verify."
}

{
  "fields": {
    "name": "test-runner-notify",
    "description": "Run test suite and send notification",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "webhook_url": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "webhook_url"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pip install -r requirements.txt",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pytest --junitxml=/tmp/test-results.xml 2>&1 | tee /tmp/test-output.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "notify-success",
        "action_type": "SHELL",
        "code": "PASS=$(grep -c \"passed\" /tmp/test-output.txt); curl -sf -X POST {{input.webhook_url}} -H \"Content-Type: application/json\" -d \"{\"text\":\"Tests passed: $PASS tests on {{input.branch}}\"}\"",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": true,
        "name": "notify-failure",
        "action_type": "SHELL",
        "code": "FAIL=$(tail -5 /tmp/test-output.txt); curl -sf -X POST {{input.webhook_url}} -H \"Content-Type: application/json\" -d \"{\"text\":\"Tests FAILED on {{input.branch}}: $FAIL\"}\"",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Test runner: pull, install deps, run pytest with XML report, notify webhook on success/failure."
}

