        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "db_name": {
              "type": "string"
            },
            "db_user": {
              "type": "string"
            },
            "db_pass": {
              "type": "string"
            },
            "max_clients": {
              "type": "string"
            },
            "pool_size": {
              "type": "string"
            }
          },
          "required": [
            "db_name",
            "db_user",
            "db_pass",
            "max_clients",
            "pool_size"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "write-userlist",
        "action_type": "SHELL",
        "code": "echo \"\"{{input.db_user}}\" \"{{input.db_pass}}\"\" > /etc/pgbouncer/userlist.txt && chmod 640 /etc/pgbouncer/userlist.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl enable --now pgbouncer",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-pgbouncer",
        "action_type": "SHELL",
        "code": "psql -h 127.0.0.1 -p 6432 -U {{input.db_user}} {{input.db_name}} -c \"SELECT 1\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl stop pgbouncer; apt-get remove -y pgbouncer",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "PgBouncer: install, configure pool, write userlist, start, verify connectivity."
}

