        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "docker-push",
        "action_type": "SHELL",
        "code": "TAG=$(cd {{input.app_dir}} && git rev-parse --short HEAD) && docker push {{input.registry}}/{{input.image_name}}:$TAG && docker push {{input.registry}}/{{input.image_name}}:latest",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "stop-old-container",
        "action_type": "SHELL",
        "code": "docker stop {{input.image_name}} 2>/dev/null; docker rm {{input.image_name}} 2>/dev/null; true",
        "target": "all",
