      {
        "id": "1",
        "undo": false,
        "name": "install-dovecot",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y dovecot-imapd dovecot-lmtpd",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-maildir",
        "action_type": "SHELL",
