        "destination": {
          "type": "string",
          "description": "Local file path to save to"
        }
      },
      "required": [
        "url",
        "destination"
      ]
    }
  },
  "explanation": "Python action that downloads a file from artifactory to a specified local path, creating directories as needed."
}

