          "description": "S3 bucket name"
        },
        "s3_prefix": {
          "type": "string",
          "description": "S3 key prefix/folder path"
        },
        "storage_class": {
          "type": "string",
          "description": "S3 storage class (STANDARD, STANDARD_IA, GLACIER, DEEP_ARCHIVE)"
