{
  "fields": {
    "name": "Check MongoDB status",
    "action_type": "PYTHON",
    "code": "import json\nimport socket\nimport sys\n\nhost = \"{{input.host}}\" or \"localhost\"\nport = int(\"{{input.port}}\" or \"27017\")\ntimeout = int(\"{{input.timeout}}\" or \"5\")\n\ntry:\n    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n    sock.settimeout(timeout)\n    result = sock.connect_ex((host, port))\n    sock.close()\n    if result == 0:\n        print(json.dumps({{\"status\": \"ok\", \"host\": host, \"port\": port, \"message\": \"MongoDB port is reachable\"}}))\n    else:\n        print(json.dumps({{\"status\": \"error\", \"host\": host, \"port\": port, \"message\": \"Connection refused\"}}))\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "MongoDB host (default localhost)"
        },
        "port": {
          "type": "string",
          "description": "MongoDB port (default 27017)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 5)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that checks staging MongoDB status by attempting a TCP connection to the database port."
}

{
  "fields": {
    "name": "Count rows in mysql table",
    "action_type": "PYTHON",
    "code": "import json\nimport sqlite3\nimport sys\n\ndb_path = \"{{input.db_path}}\"\ntable_name = \"{{input.table_name}}\"\nmin_rows = int(\"{{input.min_rows}}\" or \"0\")\n\ntry:\n    conn = sqlite3.connect(db_path)\n    cursor = conn.execute(f\"SELECT COUNT(*) FROM {{table_name}}\")\n    count = cursor.fetchone()[0]\n    conn.close()\n    ok = count >= min_rows\n    print(json.dumps({{\n        \"status\": \"ok\" if ok else \"below_minimum\",\n        \"table\": table_name,\n        \"row_count\": count,\n        \"min_expected\": min_rows,\n    }}))\n    if not ok:\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "db_path": {
          "type": "string",
          "description": "Path to SQLite database file"
        },
        "table_name": {
          "type": "string",
          "description": "Table name to count rows in"
        },
        "min_rows": {
          "type": "string",
          "description": "Minimum expected rows (default 0)"
        }
      },
      "required": [
        "db_path",
        "table_name"
      ]
    }
  },
  "explanation": "Python action that counts rows in a mysql table and alerts if the count falls below the minimum threshold."
}

