{
  "fields": {
    "name": "Validate json syntax",
    "action_type": "PYTHON",
    "code": "import json
import re
import sys

file_path = "{{input.file_path}}"
file_format = "{{input.format}}" or "json"

try:
    with open(file_path, "r") as f:
        content = f.read()
    if file_format == "json":
        json.loads(content)
        print(json.dumps({{"status": "valid", "format": "json", "file": file_path}}))
    elif file_format == "yaml":
        lines = content.splitlines()
        errors = []
        for i, line in enumerate(lines, 1):
            stripped = line.strip()
            if stripped and not stripped.startswith("#"):
                if "\t" in line:
                    errors.append(f"Line {{i}}: tab character found")
        if errors:
            print(json.dumps({{"status": "invalid", "format": "yaml", "errors": errors}}))
            sys.exit(1)
        print(json.dumps({{"status": "valid", "format": "yaml", "file": file_path}}))
    else:
        print(json.dumps({{"status": "error", "message": f"Unknown format: {{file_format}}"}}))
        sys.exit(1)
except json.JSONDecodeError as e:
    print(json.dumps({{"status": "invalid", "format": "json", "error": str(e)}}))
    sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "file_path": {
          "type": "string",
          "description": "Path to configuration file to validate"
        },
        "format": {
          "type": "string",
          "description": "File format: json or yaml (default json)"
        }
      },
      "required": [
        "file_path"
      ]
    }
  },
  "explanation": "Python action that validates json configuration file syntax, reporting any parse errors."
}

{
  "fields": {
    "name": "dkim-signing",
    "description": "Set up OpenDKIM for email signing",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-opendkim",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y opendkim opendkim-tools",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-key-dir",
        "action_type": "SHELL",
        "code": "mkdir -p /etc/opendkim/keys/{{input.domain}} && chown -R opendkim:opendkim /etc/opendkim",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "domain": {
              "type": "string"
            },
            "selector": {
              "type": "string"
            }
          },
          "required": [
            "domain",
            "selector"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "generate-dkim-key",
        "action_type": "SHELL",
        "code": "opendkim-genkey -s {{input.selector}} -d {{input.domain}} -D /etc/opendkim/keys/{{input.domain}} && chown opendkim:opendkim /etc/opendkim/keys/{{input.domain}}/*",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "configure-opendkim",
        "action_type": "SHELL",
        "code": "cat > /etc/opendkim.conf <<DKIM\nSyslog yes\nDomain {{input.domain}}\nSelector {{input.selector}}\nKeyFile /etc/opendkim/keys/{{input.domain}}/{{input.selector}}.private\nSocket inet:8891@localhost\nCanonicalization relaxed/simple\nMode sv\nDKIM",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"milter_default_action = accept\" && postconf -e \"milter_protocol = 6\" && postconf -e \"smtpd_milters = inet:localhost:8891\" && postconf -e \"non_smtpd_milters = inet:localhost:8891\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-opendkim",
        "action_type": "SHELL",
        "code": "systemctl enable --now opendkim && systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "show-dns-record",
        "action_type": "SHELL",
        "code": "cat /etc/opendkim/keys/{{input.domain}}/{{input.selector}}.txt",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-dkim",
        "action_type": "SHELL",
        "code": "systemctl stop opendkim; postconf -e \"smtpd_milters =\" && postconf -e \"non_smtpd_milters =\" && systemctl restart postfix; apt-get remove -y opendkim opendkim-tools",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "DKIM: install OpenDKIM, generate key, configure, integrate with Postfix, start, show DNS record."
}

