        "api_key": {
          "type": "string",
          "description": "API key for auth"
        },
        "instance_id": {
          "type": "string",
          "description": "Instance ID to tag"
        },
        "tags": {
          "type": "string",
          "description": "JSON string of key-value tags"
        }
      },
      "required": [
        "api_url",
        "api_key",
        "instance_id",
        "tags"
      ]
    }
  },
  "explanation": "Python action that applies key-value tags to a azure cloud instance via API."
}

