        "id": "5",
        "undo": false,
        "name": "switch-symlink",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && ln -sfn {{input.app_dir}}/$SLOT {{input.app_dir}}/current",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-app",
