{
  "fields": {
    "name": "multi-container-app",
    "description": "Deploy multi-container app with DB and cache",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-network",
        "action_type": "SHELL",
        "code": "docker network create {{input.app_name}}-net 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_name": {
              "type": "string"
            },
            "app_image": {
              "type": "string"
            },
            "app_port": {
              "type": "string"
            }
          },
          "required": [
            "app_name",
            "app_image",
            "app_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "start-database",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-db --network {{input.app_name}}-net -v {{input.app_name}}-dbdata:/var/lib/postgresql/data -e POSTGRES_DB={{input.app_name}} -e POSTGRES_PASSWORD=secret postgres:16-alpine",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-redis",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-redis --network {{input.app_name}}-net redis:7-alpine",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "wait-for-deps",
        "action_type": "SHELL",
        "code": "sleep 5 && docker exec {{input.app_name}}-db pg_isready && docker exec {{input.app_name}}-redis redis-cli ping",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "start-app",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.app_name}}-app --network {{input.app_name}}-net -p {{input.app_port}}:8080 -e DATABASE_URL=postgresql://postgres:secret@{{input.app_name}}-db/{{input.app_name}} -e REDIS_URL=redis://{{input.app_name}}-redis:6379 {{input.app_image}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 5 && curl -sf http://localhost:{{input.app_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "undo-multi-container",
        "action_type": "SHELL",
        "code": "docker stop {{input.app_name}}-app {{input.app_name}}-redis {{input.app_name}}-db 2>/dev/null; docker rm {{input.app_name}}-app {{input.app_name}}-redis {{input.app_name}}-db 2>/dev/null; docker network rm {{input.app_name}}-net 2>/dev/null; true",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Multi-container: create network, start DB+Redis in parallel, wait, start app, health check."
}

{
  "fields": {
    "name": "reverse-proxy-apache2",
    "description": "Configure apache2 as reverse proxy",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-config",
        "action_type": "SHELL",
        "code": "cp -a /etc/apache2 /etc/apache2.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "write-proxy-conf",
        "action_type": "SHELL",
        "code": "cat > /etc/apache2/sites-available/proxy.conf <<CONF\nupstream backend { server {{input.backend_host}}:{{input.backend_port}}; }\nserver { listen 80; server_name {{input.server_name}}; location / { proxy_pass http://backend; } }\nCONF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "backend_host": {
              "type": "string"
            },
            "backend_port": {
              "type": "string"
            },
            "server_name": {
              "type": "string"
            }
          },
          "required": [
            "backend_host",
            "backend_port",
            "server_name"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-config",
        "action_type": "SHELL",
        "code": "apachectl configtest",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": false,
        "name": "reload-apache2",
        "action_type": "SHELL",
        "code": "systemctl reload apache2",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-proxy",
        "action_type": "SHELL",
        "code": "curl -sf -H \"Host: {{input.server_name}}\" http://localhost/",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-proxy",
        "action_type": "SHELL",
        "code": "rm -rf /etc/apache2 && mv /etc/apache2.bak /etc/apache2 && systemctl reload apache2",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Reverse proxy: backup, write proxy config, test, reload, verify with rollback."
}

