{
  "fields": {
    "name": "Validate JSON against schema",
    "action_type": "PYTHON",
    "code": "import json
import sys

data_path = "{{input.data_path}}"
schema_path = "{{input.schema_path}}"

def validate(data, schema, path=""):
    errors = []
    stype = schema.get("type")
    if stype == "object" and isinstance(data, dict):
        for req in schema.get("required", []):
            if req not in data:
                errors.append(f"{{path}}: missing required field '{{req}}'")
        props = schema.get("properties", {})
        for k, v in props.items():
            if k in data:
                errors.extend(validate(data[k], v, str(path) + "." + str(k)))
    elif stype == "string" and not isinstance(data, str):
        errors.append(str(path) + ": expected string, got " + type(data).__name__)
    elif stype == "number" and not isinstance(data, (int, float)):
        errors.append(str(path) + ": expected number, got " + type(data).__name__)
    elif stype == "array" and not isinstance(data, list):
        errors.append(str(path) + ": expected array, got " + type(data).__name__)
    return errors

try:
    with open(data_path) as f:
        data = json.load(f)
    with open(schema_path) as f:
        schema = json.load(f)
    errors = validate(data, schema)
    if errors:
        print(json.dumps({{"status": "invalid", "errors": errors}}))
        sys.exit(1)
    print(json.dumps({{"status": "valid", "message": "Schema validation passed"}}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "data_path": {
          "type": "string",
          "description": "Path to JSON data file"
        },
        "schema_path": {
          "type": "string",
          "description": "Path to JSON schema file"
        }
      },
      "required": [
        "data_path",
        "schema_path"
      ]
    }
  },
  "explanation": "Python action that validates a response JSON file against a JSON schema definition, reporting any validation errors."
}

{
  "fields": {
    "name": "Query systemd journal for redis",
    "action_type": "PYTHON",
    "code": "import json
import subprocess
import sys

unit = "{{input.unit}}"
since = "{{input.since}}" or "1 hour ago"
priority = "{{input.priority}}" or "err"
max_entries = int("{{input.max_entries}}" or "50")

try:
    cmd = [
        "journalctl", "-u", unit,
        "--since", since,
        "--priority", priority,
        "--no-pager", "-o", "json",
        "-n", str(max_entries),
    ]
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
    entries = []
    for line in result.stdout.strip().split("\n"):
        if line.strip():
            try:
                entries.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    summary = {{
        "status": "ok",
        "unit": unit,
        "since": since,
        "priority": priority,
        "entry_count": len(entries),
        "messages": [e.get("MESSAGE", "") for e in entries[-20:]],
    }}
    print(json.dumps(summary))
except subprocess.TimeoutExpired:
    print(json.dumps({{"status": "error", "message": "journalctl timed out"}}))
    sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "unit": {
          "type": "string",
          "description": "Systemd unit name to query"
        },
        "since": {
          "type": "string",
          "description": "Time range (default "1 hour ago")"
        },
        "priority": {
          "type": "string",
          "description": "Minimum priority level (default "err")"
        },
        "max_entries": {
          "type": "string",
          "description": "Maximum entries to return (default 50)"
        }
      },
      "required": [
        "unit"
      ]
    }
  },
  "explanation": "Python action that queries the systemd journal for redis entries filtered by time range and priority level."
}

