{
  "fields": {
    "name": "WebSocket ping to realtime",
    "action_type": "PYTHON",
    "code": "import json
import socket
import hashlib
import base64
import os
import sys

host = "{{input.host}}"
port = int("{{input.port}}" or "80")
path = "{{input.path}}" or "/"
timeout = int("{{input.timeout}}" or "10")

ws_key = base64.b64encode(os.urandom(16)).decode()
try:
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    sock.connect((host, port))
    handshake = (
        f"GET {{path}} HTTP/1.1\r\n"
        f"Host: {{host}}\r\n"
        f"Upgrade: websocket\r\n"
        f"Connection: Upgrade\r\n"
        f"Sec-WebSocket-Key: {{ws_key}}\r\n"
        f"Sec-WebSocket-Version: 13\r\n\r\n"
    )
    sock.sendall(handshake.encode())
    resp = sock.recv(4096).decode()
    sock.close()
    if "101" in resp and "Upgrade" in resp:
        print(json.dumps({{"status": "ok", "message": "WebSocket handshake successful"}}))
    else:
        print(json.dumps({{"status": "error", "message": "Handshake failed", "response": resp[:200]}}))
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "WebSocket server hostname"
        },
        "port": {
          "type": "string",
          "description": "WebSocket server port (default 80)"
        },
        "path": {
          "type": "string",
          "description": "WebSocket endpoint path (default /)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 10)"
        }
      },
      "required": [
        "host"
      ]
    }
  },
  "explanation": "Python action that tests realtime WebSocket connectivity by performing the HTTP upgrade handshake."
}

{
  "fields": {
    "name": "Check CPU usage",
    "action_type": "PYTHON",
    "code": "import json
import sys
import os

threshold = float("{{input.threshold}}" or "80")

def get_cpu_usage():
    with open("/proc/stat", "r") as f:
        line = f.readline()
    parts = line.split()
    idle = int(parts[4])
    total = sum(int(p) for p in parts[1:])
    return idle, total

import time
idle1, total1 = get_cpu_usage()
time.sleep(1)
idle2, total2 = get_cpu_usage()

idle_delta = idle2 - idle1
total_delta = total2 - total1
usage = (1.0 - idle_delta / total_delta) * 100.0 if total_delta > 0 else 0.0
cpu_count = os.cpu_count() or 1

result = {{
    "cpu_percent": round(usage, 2),
    "cpu_count": cpu_count,
    "threshold": threshold,
    "status": "critical" if usage > threshold else "ok",
}}
print(json.dumps(result))
if usage > threshold:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "threshold": {
          "type": "string",
          "description": "CPU usage percent threshold (default 80)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/stat to compute CPU usage percentage and alerts if it exceeds the threshold."
}

