{
  "fields": {
    "name": "deploy-pgbouncer",
    "description": "Deploy PgBouncer connection pooler",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-pgbouncer",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y pgbouncer",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-pgbouncer",
        "action_type": "SHELL",
        "code": "cat > /etc/pgbouncer/pgbouncer.ini <<INI\n[databases]\n{{input.db_name}} = host=127.0.0.1 port=5432 dbname={{input.db_name}}\n[pgbouncer]\nlisten_addr = 127.0.0.1\nlisten_port = 6432\nauth_type = md5\nauth_file = /etc/pgbouncer/userlist.txt\npool_mode = transaction\nmax_client_conn = {{input.max_clients}}\ndefault_pool_size = {{input.pool_size}}\nINI",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "db_name": {
              "type": "string"
            },
            "db_user": {
              "type": "string"
            },
            "db_pass": {
              "type": "string"
            },
            "max_clients": {
              "type": "string"
            },
            "pool_size": {
              "type": "string"
            }
          },
          "required": [
            "db_name",
            "db_user",
            "db_pass",
            "max_clients",
            "pool_size"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "write-userlist",
        "action_type": "SHELL",
        "code": "echo \"\"{{input.db_user}}\" \"{{input.db_pass}}\"\" > /etc/pgbouncer/userlist.txt && chmod 640 /etc/pgbouncer/userlist.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl enable --now pgbouncer",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-pgbouncer",
        "action_type": "SHELL",
        "code": "psql -h 127.0.0.1 -p 6432 -U {{input.db_user}} {{input.db_name}} -c \"SELECT 1\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl stop pgbouncer; apt-get remove -y pgbouncer",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "PgBouncer: install, configure pool, write userlist, start, verify connectivity."
}

{
  "fields": {
    "name": "blue-green-single",
    "description": "Blue-green deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "detect-active-slot",
        "action_type": "SHELL",
        "code": "ACTIVE=$(readlink {{input.app_dir}}/current); if [ \"$ACTIVE\" = \"{{input.app_dir}}/blue\" ]; then echo green > /tmp/deploy_slot; else echo blue > /tmp/deploy_slot; fi",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "repo_url": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "repo_url",
            "branch"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clone-to-inactive",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && rm -rf {{input.app_dir}}/$SLOT && git clone -b {{input.branch}} {{input.repo_url}} {{input.app_dir}}/$SLOT",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps-new",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm ci",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "test-new-slot",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm test",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "switch-symlink",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && ln -sfn {{input.app_dir}}/$SLOT {{input.app_dir}}/current",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-app",
        "action_type": "SHELL",
        "code": "systemctl restart app",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:3000/health",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-blue-green",
        "action_type": "SHELL",
        "code": "ACTIVE=$(cat /tmp/deploy_slot); if [ \"$ACTIVE\" = \"green\" ]; then OTHER=blue; else OTHER=green; fi && ln -sfn {{input.app_dir}}/$OTHER {{input.app_dir}}/current && systemctl restart app",
        "parent_step_ids": [
          "5"
        ]
      }
    ]
  },
  "explanation": "Blue-green: detect active slot, clone to inactive, install, test, swap symlink, restart, health check."
}

{
  "fields": {
    "name": "deploy-mongodb",
    "description": "Deploy MongoDB with auth enabled",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "import-mongo-key",
        "action_type": "SHELL",
        "code": "curl -fsSL https://pgp.mongodb.com/server-7.0.asc | gpg --dearmor -o /usr/share/keyrings/mongodb-server-7.0.gpg",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-mongo-repo",
        "action_type": "SHELL",
        "code": "echo \"deb [signed-by=/usr/share/keyrings/mongodb-server-7.0.gpg] https://repo.mongodb.org/apt/ubuntu jammy/mongodb-org/7.0 multiverse\" > /etc/apt/sources.list.d/mongodb-org-7.0.list && apt-get update",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-mongodb",
        "action_type": "SHELL",
        "code": "apt-get install -y mongodb-org",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-mongodb",
        "action_type": "SHELL",
        "code": "systemctl enable --now mongod",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "create-admin-user",
        "action_type": "SHELL",
        "code": "mongosh --eval \"use admin; db.createUser({user:\"{{input.admin_user}}\",pwd:\"{{input.admin_pass}}\",roles:[\"root\"]})\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "schema": {
          "input": {
            "admin_user": {
              "type": "string"
            },
            "admin_pass": {
              "type": "string"
            }
          },
          "required": [
            "admin_user",
            "admin_pass"
          ]
        }
      },
      {
        "id": "6",
        "undo": false,
        "name": "enable-auth",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#security:/security:\\n  authorization: enabled/\" /etc/mongod.conf && systemctl restart mongod",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-mongodb",
        "action_type": "SHELL",
        "code": "mongosh -u {{input.admin_user}} -p {{input.admin_pass}} --authenticationDatabase admin --eval \"db.runCommand({ping:1})\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-mongodb",
        "action_type": "SHELL",
        "code": "systemctl stop mongod; apt-get remove -y mongodb-org",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "MongoDB: import key, add repo, install, start, create admin, enable auth, verify."
}

