        },
        "domain": {
          "type": "string",
          "description": "Domain name"
        },
        "record_type": {
          "type": "string",
          "description": "DNS record type (default A)"
        },
        "record_name": {
          "type": "string",
          "description": "Record name (subdomain)"
        },
        "record_value": {
          "type": "string",
          "description": "Record value (IP or target)"
        },
        "ttl": {
          "type": "string",
          "description": "TTL in seconds (default 300)"
        }
      },
      "required": [
        "api_url",
        "api_key",
        "domain",
        "record_name",
        "record_value"
      ]
    }
  },
