{
  "fields": {
    "name": "tune-mysql",
    "description": "Tune MySQL/MariaDB performance",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-mysql-conf",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf /etc/mysql/mysql.conf.d/mysqld.cnf.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-buffer-pool",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*innodb_buffer_pool_size.*/innodb_buffer_pool_size = {{input.buffer_pool}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "buffer_pool": {
              "type": "string"
            },
            "max_conn": {
              "type": "string"
            }
          },
          "required": [
            "buffer_pool",
            "max_conn"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-connections",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_connections.*/max_connections = {{input.max_conn}}/\" /etc/mysql/mysql.conf.d/mysqld.cnf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-mysql",
        "action_type": "SHELL",
        "code": "systemctl restart mysql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-mysql-vars",
        "action_type": "SHELL",
        "code": "mysql -e \"SHOW VARIABLES LIKE 'innodb_buffer_pool_size'; SHOW VARIABLES LIKE 'max_connections';\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-mysql-tuning",
        "action_type": "SHELL",
        "code": "cp /etc/mysql/mysql.conf.d/mysqld.cnf.bak /etc/mysql/mysql.conf.d/mysqld.cnf && systemctl restart mysql",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "MySQL tuning: backup, set buffer pool + max connections in parallel, restart, verify."
}

{
  "fields": {
    "name": "redis-watchdog-config",
    "action_type": "SHELL",
    "code": "mkdir -p /etc/systemd/system/{{input.service_name}}.service.d && cat > /etc/systemd/system/{{input.service_name}}.service.d/watchdog.conf <<WATCHDOG\n[Service]\nWatchdogSec={{input.watchdog_sec}}\nRestart=on-watchdog\nRestartSec={{input.restart_sec}}\nStartLimitIntervalSec={{input.limit_interval}}\nStartLimitBurst={{input.limit_burst}}\nWATCHDOG\nsystemctl daemon-reload && systemctl restart {{input.service_name}} && systemctl show {{input.service_name}} --property=WatchdogUSec,Restart --no-pager && echo \"Watchdog configured for {{input.service_name}} (timeout: {{input.watchdog_sec}})\"",
    "expected_rc": 0,
    "schema": {
      "input": {
        "service_name": {
          "type": "string",
          "description": "Name of the systemd service"
        },
        "watchdog_sec": {
          "type": "string",
          "description": "Watchdog timeout (e.g. 30s, 60s)"
        },
        "restart_sec": {
          "type": "string",
          "description": "Delay before restart (e.g. 5s)"
        },
        "limit_interval": {
          "type": "string",
          "description": "Rate limit interval (e.g. 300s)"
        },
        "limit_burst": {
          "type": "integer",
          "description": "Maximum restarts within interval"
        }
      },
      "required": [
        "service_name",
        "watchdog_sec",
        "restart_sec",
        "limit_interval",
        "limit_burst"
      ]
    }
  },
  "explanation": "Configures a systemd watchdog for the redis service with automatic restart on timeout and rate limiting."
}

