        "id": "6",
        "undo": false,
        "name": "enable-auth",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#security:/security:\\n  authorization: enabled/\" /etc/mongod.conf && systemctl restart mongod",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-mongodb",
