    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "clean-old-backups",
        "action_type": "SHELL",
        "code": "find /var/backups/app_* -maxdepth 0 -mtime +{{input.retention_days}} -exec rm -rf {} \\; 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "retention_days": {
              "type": "string"
            },
            "registry": {
              "type": "string"
            },
            "image_name": {
              "type": "string"
            }
          },
          "required": [
            "retention_days"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clean-docker-images",
        "action_type": "SHELL",
        "code": "docker image prune -a --filter \"until={{input.retention_days}}d\" -f 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "clean-build-caches",
        "action_type": "SHELL",
