      },
      {
        "id": "5",
        "undo": false,
        "name": "report-disk-freed",
        "action_type": "SHELL",
        "code": "df -h / | tail -1",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2",
          "3",
          "4"
        ]
      }
    ]
  },
