{
  "fields": {
    "name": "log-alerting",
    "description": "Set up log-based alerting",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-alert-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/log-alert.sh <<SCRIPT\n#!/bin/bash\nPATTERN=\"{{input.alert_pattern}}\"\nLOGFILE=\"{{input.log_path}}\"\nERRORS=$(tail -100 \"$LOGFILE\" | grep -c \"$PATTERN\")\nif [ \"$ERRORS\" -gt {{input.threshold}} ]; then\n  echo \"ALERT: $ERRORS matches for $PATTERN in $LOGFILE\" | logger -t log-alert\nfi\nSCRIPT\nchmod +x /usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/5 * * * * /usr/local/bin/log-alert.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-alert-script",
        "action_type": "SHELL",
        "code": "/usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": true,
        "name": "undo-log-alerting",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v log-alert | crontab - && rm -f /usr/local/bin/log-alert.sh",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Log alerting: create alert script, add cron, test. Matches pattern in log and fires syslog alert."
}

{
  "fields": {
    "name": "Check aws service health",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nhealth_url = \"{{input.health_url}}\"\napi_key = \"{{input.api_key}}\" or \"\"\nexpected_status = int(\"{{input.expected_status}}\" or \"200\")\n\nreq = urllib.request.Request(health_url, method=\"GET\")\nif api_key:\n    req.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=15)\n    code = resp.getcode()\n    body = resp.read().decode()\n    try:\n        data = json.loads(body)\n    except json.JSONDecodeError:\n        data = body\n    healthy = code == expected_status\n    print(json.dumps({{\"status\": \"healthy\" if healthy else \"unhealthy\", \"code\": code, \"body\": data}}))\n    if not healthy:\n        sys.exit(1)\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"unreachable\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "health_url": {
          "type": "string",
          "description": "Health check endpoint URL"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth (optional)"
        },
        "expected_status": {
          "type": "string",
          "description": "Expected HTTP status code (default 200)"
        }
      },
      "required": [
        "health_url"
      ]
    }
  },
  "explanation": "Python action that checks aws cloud service health by querying an endpoint and validating the response code."
}

