{
  "fields": {
    "name": "Send Microsoft Teams message",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nwebhook_url = \"{{input.webhook_url}}\"\ntitle = \"{{input.title}}\"\nmessage = \"{{input.message}}\"\nseverity = \"{{input.severity}}\" or \"info\"\n\ncolor_map = {{\"info\": \"0076D7\", \"warning\": \"FFA500\", \"critical\": \"FF0000\", \"success\": \"00FF00\"}}\npayload = {{\n    \"@type\": \"MessageCard\",\n    \"@context\": \"http://schema.org/extensions\",\n    \"themeColor\": color_map.get(severity, \"0076D7\"),\n    \"summary\": title,\n    \"sections\": [{{\n        \"activityTitle\": title,\n        \"activitySubtitle\": f\"Severity: {{severity}}\",\n        \"text\": message,\n    }}],\n}}\n\ndata = json.dumps(payload).encode(\"utf-8\")\nreq = urllib.request.Request(webhook_url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=15)\n    print(json.dumps({{\"status\": \"sent\", \"severity\": severity}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "webhook_url": {
          "type": "string",
          "description": "Microsoft Teams webhook URL"
        },
        "title": {
          "type": "string",
          "description": "Card title"
        },
        "message": {
          "type": "string",
          "description": "Message body text"
        },
        "severity": {
          "type": "string",
          "description": "Severity: info, warning, critical, success"
        }
      },
      "required": [
        "webhook_url",
        "title",
        "message"
      ]
    }
  },
  "explanation": "Python action that sends a info-level MessageCard notification to Microsoft Teams via incoming webhook."
}

