{
  "fields": {
    "name": "swap-management",
    "description": "Configure or resize swap space",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "check-current-swap",
        "action_type": "SHELL",
        "code": "swapon --show && free -h | grep Swap",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "disable-old-swap",
        "action_type": "SHELL",
        "code": "swapoff /swapfile 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "create-swapfile",
        "action_type": "SHELL",
        "code": "fallocate -l {{input.swap_size}} /swapfile && chmod 600 /swapfile",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "schema": {
          "input": {
            "swap_size": {
              "type": "string"
            },
            "swappiness": {
              "type": "string"
            }
          },
          "required": [
            "swap_size",
            "swappiness"
          ]
        }
      },
      {
        "id": "4",
        "undo": false,
        "name": "format-swap",
        "action_type": "SHELL",
        "code": "mkswap /swapfile",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "enable-swap",
        "action_type": "SHELL",
        "code": "swapon /swapfile",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "persist-fstab",
        "action_type": "SHELL",
        "code": "grep -q \"/swapfile\" /etc/fstab || echo \"/swapfile none swap sw 0 0\" >> /etc/fstab",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "set-swappiness",
        "action_type": "SHELL",
        "code": "sysctl vm.swappiness={{input.swappiness}} && echo \"vm.swappiness={{input.swappiness}}\" > /etc/sysctl.d/99-swappiness.conf",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "8",
        "undo": false,
        "name": "verify-swap",
        "action_type": "SHELL",
        "code": "swapon --show | grep /swapfile && sysctl vm.swappiness",
        "target": "all",
        "parent_step_ids": [
          "6",
          "7"
        ],
        "expected_rc": 0
      },
      {
        "id": "9",
        "undo": true,
        "name": "undo-swap",
        "action_type": "SHELL",
        "code": "swapoff /swapfile 2>/dev/null; rm -f /swapfile /etc/sysctl.d/99-swappiness.conf; sed -i \"/\\/swapfile/d\" /etc/fstab; sysctl vm.swappiness=60",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Swap management: check current, disable old, create+format+enable swapfile, persist in fstab, set swappiness, verify."
}

{
  "fields": {
    "name": "docker-volume-backup",
    "description": "Backup Docker volumes to compressed archive",
    "stop_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-backup-dir",
        "action_type": "SHELL",
        "code": "mkdir -p {{input.backup_dir}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "volume_name": {
              "type": "string"
            },
            "backup_dir": {
              "type": "string"
            }
          },
          "required": [
            "volume_name",
            "backup_dir"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "stop-using-containers",
        "action_type": "SHELL",
        "code": "CONTAINERS=$(docker ps -q --filter volume={{input.volume_name}}); if [ -n \"$CONTAINERS\" ]; then docker stop $CONTAINERS; echo \"$CONTAINERS\" > /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "backup-volume",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && docker run --rm -v {{input.volume_name}}:/source -v {{input.backup_dir}}:/backup alpine tar czf /backup/{{input.volume_name}}_$TIMESTAMP.tar.gz -C /source .",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-containers",
        "action_type": "SHELL",
        "code": "if [ -f /tmp/vol_backup_containers ]; then cat /tmp/vol_backup_containers | xargs docker start; rm /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-backup",
        "action_type": "SHELL",
        "code": "ls -lh {{input.backup_dir}}/{{input.volume_name}}_*.tar.gz | tail -1",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      }
    ]
  },
  "explanation": "Volume backup: mkdir, stop containers using volume, tar the volume, restart containers, verify archive."
}

