{
  "fields": {
    "name": "tune-mysql",
    "description": "Tune MySQL/MariaDB performance",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-mysql-conf",
