        "code": "docker run -d --name log-aggregator --restart unless-stopped -v /var/lib/docker/containers:/var/lib/docker/containers:ro -v /var/run/docker.sock:/var/run/docker.sock:ro -p 24224:24224 fluent/fluentd:v1.16-1",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
