{
  "fields": {
    "name": "Validate postgres conn pool",
    "action_type": "PYTHON",
    "code": "import json
import socket
import sys

host = "{{input.host}}" or "localhost"
port = int("{{input.port}}")
max_connections = int("{{input.max_connections}}" or "10")
timeout = int("{{input.timeout}}" or "3")

successful = 0
failed = 0
sockets = []

for i in range(max_connections):
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(timeout)
        s.connect((host, port))
        sockets.append(s)
        successful += 1
    except Exception:
        failed += 1

for s in sockets:
    try:
        s.close()
    except Exception:
        pass

result = {{
    "status": "ok" if failed == 0 else "degraded",
    "host": host,
    "port": port,
    "successful": successful,
    "failed": failed,
    "max_connections": max_connections,
}}
print(json.dumps(result))
if failed > 0:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "Database host (default localhost)"
        },
        "port": {
          "type": "string",
          "description": "Database port"
        },
        "max_connections": {
          "type": "string",
          "description": "Number of connections to test (default 10)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 3)"
        }
      },
      "required": [
        "port"
      ]
    }
  },
  "explanation": "Python action that validates postgres connection pool by opening multiple simultaneous TCP connections."
}

{
  "fields": {
    "name": "WebSocket ping to chat",
    "action_type": "PYTHON",
    "code": "import json
import socket
import hashlib
import base64
import os
import sys

host = "{{input.host}}"
port = int("{{input.port}}" or "80")
path = "{{input.path}}" or "/"
timeout = int("{{input.timeout}}" or "10")

ws_key = base64.b64encode(os.urandom(16)).decode()
try:
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    sock.connect((host, port))
    handshake = (
        f"GET {{path}} HTTP/1.1\r\n"
        f"Host: {{host}}\r\n"
        f"Upgrade: websocket\r\n"
        f"Connection: Upgrade\r\n"
        f"Sec-WebSocket-Key: {{ws_key}}\r\n"
        f"Sec-WebSocket-Version: 13\r\n\r\n"
    )
    sock.sendall(handshake.encode())
    resp = sock.recv(4096).decode()
    sock.close()
    if "101" in resp and "Upgrade" in resp:
        print(json.dumps({{"status": "ok", "message": "WebSocket handshake successful"}}))
    else:
        print(json.dumps({{"status": "error", "message": "Handshake failed", "response": resp[:200]}}))
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "WebSocket server hostname"
        },
        "port": {
          "type": "string",
          "description": "WebSocket server port (default 80)"
        },
        "path": {
          "type": "string",
          "description": "WebSocket endpoint path (default /)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 10)"
        }
      },
      "required": [
        "host"
      ]
    }
  },
  "explanation": "Python action that tests chat WebSocket connectivity by performing the HTTP upgrade handshake."
}

{
  "fields": {
    "name": "pg-replica-prep",
    "description": "Prepare PostgreSQL for streaming replication",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-pg-conf",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf /etc/postgresql/*/main/postgresql.conf.repl.bak && cp /etc/postgresql/*/main/pg_hba.conf /etc/postgresql/*/main/pg_hba.conf.repl.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-wal-level",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*wal_level.*/wal_level = replica/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-wal-senders",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_wal_senders.*/max_wal_senders = 5/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "create-repl-user",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"CREATE USER {{input.repl_user}} WITH REPLICATION PASSWORD '{{input.repl_pass}}'\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "repl_user": {
              "type": "string"
            },
            "repl_pass": {
              "type": "string"
            },
            "replica_ip": {
              "type": "string"
            }
          },
          "required": [
            "repl_user",
            "repl_pass",
            "replica_ip"
          ]
