{
  "fields": {
    "name": "canary-single-server",
    "description": "Canary deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "deploy-canary",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git stash && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "canary_port": {
              "type": "string"
            },
            "prod_port": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "canary_port",
            "prod_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-canary",
        "action_type": "SHELL",
        "code": "PORT={{input.canary_port}} node {{input.app_dir}}/server.js &",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "canary-health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:{{input.canary_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "route-canary-traffic",
        "action_type": "SHELL",
        "code": "sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}} weight=9;\\n    server 127.0.0.1:{{input.canary_port}} weight=1;/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "monitor-errors",
        "action_type": "SHELL",
        "code": "sleep 30 && ERROR_RATE=$(tail -100 /var/log/nginx/access.log | grep -c \" 5[0-9][0-9] \") && test \"$ERROR_RATE\" -lt 5",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": false,
        "name": "promote-canary",
        "action_type": "SHELL",
        "code": "systemctl restart app && kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}};/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-canary",
        "action_type": "SHELL",
        "code": "kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; cd {{input.app_dir}} && git stash pop; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Canary: deploy new version on alternate port, route 10% traffic, monitor errors, promote or rollback."
}

{
  "fields": {
    "name": "cdn-cert-chain-verify",
    "action_type": "SHELL",
    "code": "echo \"=== Certificate Chain Verification for {{input.hostname}}:{{input.port}} ===\" && CERT_CHAIN=$(echo | openssl s_client -servername {{input.hostname}} -connect {{input.hostname}}:{{input.port}} -showcerts 2>/dev/null) && if [ -z \"$CERT_CHAIN\" ]; then echo \"FAILED: Could not connect to {{input.hostname}}:{{input.port}}\" >&2; exit 1; fi && VERIFY=$(echo | openssl s_client -servername {{input.hostname}} -connect {{input.hostname}}:{{input.port}} 2>&1 | grep \"Verify return code\") && echo \"$VERIFY\" && CERT_COUNT=$(echo \"$CERT_CHAIN\" | grep -c \"BEGIN CERTIFICATE\") && echo \"Certificates in chain: $CERT_COUNT\" && echo \"$CERT_CHAIN\" | openssl x509 -noout -subject -issuer -dates 2>/dev/null && if echo \"$VERIFY\" | grep -q \"0 (ok)\"; then echo \"OK: Certificate chain is valid\"; else echo \"FAILED: Certificate chain verification failed\" >&2; exit 1; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "hostname": {
          "type": "string",
          "description": "Hostname to verify certificate chain for"
        },
        "port": {
          "type": "integer",
          "description": "TLS port number (typically 443)"
        }
      },
      "required": [
        "hostname",
        "port"
      ]
    }
  },
  "explanation": "Verifies the complete SSL/TLS certificate chain for the cdn endpoint including chain depth and validity."
}

