{
  "fields": {
    "name": "database-backup-verify",
    "action_type": "SHELL",
    "code": "if [ ! -f \"{{input.backup_file}}\" ]; then echo \"FAILED: Backup file not found: {{input.backup_file}}\" >&2; exit 1; fi && echo \"Computing SHA-256 checksum...\" && COMPUTED=$(sha256sum \"{{input.backup_file}}\" | awk '{print $1}') && if [ -n \"{{input.expected_checksum}}\" ]; then if [ \"$COMPUTED\" = \"{{input.expected_checksum}}\" ]; then echo \"VERIFIED: Checksum matches ($COMPUTED)\"; else echo \"FAILED: Checksum mismatch (expected: {{input.expected_checksum}}, got: $COMPUTED)\" >&2; exit 1; fi; else echo \"SHA-256: $COMPUTED\"; echo \"$COMPUTED  {{input.backup_file}}\" >> \"{{input.backup_file}}.sha256\"; echo \"Checksum saved to {{input.backup_file}}.sha256\"; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "backup_file": {
          "type": "string",
          "description": "Path to the backup file to verify"
        },
        "expected_checksum": {
          "type": "string",
          "description": "Expected SHA-256 checksum (leave empty to generate)"
        }
      },
      "required": [
        "backup_file"
      ]
    }
  },
  "explanation": "Verifies database backup integrity by computing or comparing SHA-256 checksums."
}

{
  "fields": {
    "name": "swap-management",
    "description": "Configure or resize swap space",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "check-current-swap",
        "action_type": "SHELL",
        "code": "swapon --show && free -h | grep Swap",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "disable-old-swap",
        "action_type": "SHELL",
        "code": "swapoff /swapfile 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "create-swapfile",
        "action_type": "SHELL",
        "code": "fallocate -l {{input.swap_size}} /swapfile && chmod 600 /swapfile",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "schema": {
          "input": {
            "swap_size": {
              "type": "string"
            },
            "swappiness": {
              "type": "string"
            }
          },
          "required": [
            "swap_size",
            "swappiness"
          ]
        }
      },
      {
        "id": "4",
        "undo": false,
        "name": "format-swap",
        "action_type": "SHELL",
        "code": "mkswap /swapfile",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "enable-swap",
        "action_type": "SHELL",
        "code": "swapon /swapfile",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "persist-fstab",
        "action_type": "SHELL",
        "code": "grep -q \"/swapfile\" /etc/fstab || echo \"/swapfile none swap sw 0 0\" >> /etc/fstab",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "set-swappiness",
        "action_type": "SHELL",
        "code": "sysctl vm.swappiness={{input.swappiness}} && echo \"vm.swappiness={{input.swappiness}}\" > /etc/sysctl.d/99-swappiness.conf",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "8",
        "undo": false,
        "name": "verify-swap",
        "action_type": "SHELL",
        "code": "swapon --show | grep /swapfile && sysctl vm.swappiness",
        "target": "all",
        "parent_step_ids": [
          "6",
          "7"
        ],
        "expected_rc": 0
      },
      {
        "id": "9",
        "undo": true,
        "name": "undo-swap",
        "action_type": "SHELL",
        "code": "swapoff /swapfile 2>/dev/null; rm -f /swapfile /etc/sysctl.d/99-swappiness.conf; sed -i \"/\\/swapfile/d\" /etc/fstab; sysctl vm.swappiness=60",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Swap management: check current, disable old, create+format+enable swapfile, persist in fstab, set swappiness, verify."
}

