    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-check-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/uptime-check.sh <<SCRIPT\n#!/bin/bash\nLOGFILE=/var/log/uptime-monitor.log\nfor URL in {{input.urls}}; do\n  STATUS=$(curl -sf -o /dev/null -w \"%%{http_code}\" --max-time 10 \"$URL\" 2>/dev/null)\n  echo \"$(date -Iseconds) $URL $STATUS\" >> $LOGFILE\n  if [ \"$STATUS\" != \"200\" ]; then\n    echo \"ALERT: $URL returned $STATUS\" | logger -t uptime-monitor\n  fi\ndone\nSCRIPT\nchmod +x /usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "urls": {
              "type": "string"
            },
            "interval_min": {
              "type": "string"
            }
          },
          "required": [
            "urls",
            "interval_min"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-log-file",
        "action_type": "SHELL",
        "code": "touch /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "add-cron-job",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/{{input.interval_min}} * * * * /usr/local/bin/uptime-check.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-initial-check",
        "action_type": "SHELL",
        "code": "/usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-log-output",
        "action_type": "SHELL",
        "code": "test -s /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-uptime-monitor",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v uptime-check | crontab - && rm -f /usr/local/bin/uptime-check.sh /var/log/uptime-monitor.log",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Uptime monitor: create check script, add cron job, run initial check, verify log."
}

{
  "fields": {
    "name": "Dispatch webhook to github",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport hashlib\nimport hmac\nimport sys\n\nwebhook_url = \"{{input.webhook_url}}\"\nevent_type = \"{{input.event_type}}\"\npayload_str = '{{input.payload}}'\nsecret = \"{{input.secret}}\"\n\npayload = {{\"event\": event_type, \"data\": json.loads(payload_str)}}\nbody = json.dumps(payload).encode(\"utf-8\")\n\nreq = urllib.request.Request(webhook_url, data=body, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"X-Event-Type\", event_type)\nif secret:\n    sig = hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()\n    req.add_header(\"X-Signature\", \"sha256=\" + sig)\n\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    print(json.dumps({{\"status\": \"dispatched\", \"code\": resp.getcode()}}))\nexcept urllib.error.HTTPError as e:\n    print(json.dumps({{\"status\": \"error\", \"code\": e.code}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "webhook_url": {
          "type": "string",
          "description": "Webhook endpoint URL"
        },
        "event_type": {
          "type": "string",
          "description": "Event type identifier"
        },
        "payload": {
          "type": "string",
          "description": "JSON payload string"
        },
        "secret": {
          "type": "string",
          "description": "HMAC secret for signing (optional)"
        }
      },
      "required": [
        "webhook_url",
        "event_type",
        "payload"
      ]
    }
  },
  "explanation": "Python action that dispatches a webhook event to github with optional HMAC-SHA256 signature verification."
}

{
  "fields": {
    "name": "deploy-pgbouncer",
    "description": "Deploy PgBouncer connection pooler",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-pgbouncer",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y pgbouncer",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-pgbouncer",
        "action_type": "SHELL",
        "code": "cat > /etc/pgbouncer/pgbouncer.ini <<INI\n[databases]\n{{input.db_name}} = host=127.0.0.1 port=5432 dbname={{input.db_name}}\n[pgbouncer]\nlisten_addr = 127.0.0.1\nlisten_port = 6432\nauth_type = md5\nauth_file = /etc/pgbouncer/userlist.txt\npool_mode = transaction\nmax_client_conn = {{input.max_clients}}\ndefault_pool_size = {{input.pool_size}}\nINI",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "db_name": {
              "type": "string"
            },
            "db_user": {
              "type": "string"
            },
            "db_pass": {
              "type": "string"
            },
            "max_clients": {
              "type": "string"
            },
            "pool_size": {
              "type": "string"
            }
          },
          "required": [
            "db_name",
            "db_user",
            "db_pass",
            "max_clients",
            "pool_size"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "write-userlist",
        "action_type": "SHELL",
        "code": "echo \"\"{{input.db_user}}\" \"{{input.db_pass}}\"\" > /etc/pgbouncer/userlist.txt && chmod 640 /etc/pgbouncer/userlist.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "start-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl enable --now pgbouncer",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-pgbouncer",
        "action_type": "SHELL",
        "code": "psql -h 127.0.0.1 -p 6432 -U {{input.db_user}} {{input.db_name}} -c \"SELECT 1\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-pgbouncer",
        "action_type": "SHELL",
        "code": "systemctl stop pgbouncer; apt-get remove -y pgbouncer",
        "parent_step_ids": [
          "1"
        ]
