}

{
  "fields": {
    "name": "Update DNS via azure-dns API",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\napi_url = \"{{input.api_url}}\"\napi_key = \"{{input.api_key}}\"\ndomain = \"{{input.domain}}\"\nrecord_type = \"{{input.record_type}}\" or \"A\"\nrecord_name = \"{{input.record_name}}\"\nrecord_value = \"{{input.record_value}}\"\nttl = int(\"{{input.ttl}}\" or \"300\")\n\npayload = {{\n    \"type\": record_type,\n    \"name\": record_name,\n    \"content\": record_value,\n    \"ttl\": ttl,\n}}\ndata = json.dumps(payload).encode(\"utf-8\")\nreq = urllib.request.Request(api_url, data=data, method=\"PUT\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    result = json.loads(resp.read().decode())\n    print(json.dumps({{\"status\": \"updated\", \"domain\": domain, \"record\": record_name, \"type\": record_type}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "api_url": {
          "type": "string",
          "description": "DNS provider API URL"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        },
        "domain": {
          "type": "string",
          "description": "Domain name"
        },
        "record_type": {
          "type": "string",
          "description": "DNS record type (default A)"
        },
        "record_name": {
          "type": "string",
          "description": "Record name (subdomain)"
        },
        "record_value": {
          "type": "string",
          "description": "Record value (IP or target)"
        },
        "ttl": {
          "type": "string",
          "description": "TTL in seconds (default 300)"
        }
      },
      "required": [
        "api_url",
        "api_key",
        "domain",
        "record_name",
        "record_value"
      ]
    }
  },
  "explanation": "Python action that updates a DNS record via azure-dns API with configurable type, name, value, and TTL."
}

