{
  "fields": {
    "name": "docker-cicd",
    "description": "Build Docker image, push to registry, deploy",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "image_name": {
              "type": "string"
            },
            "registry": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "image_name",
            "registry"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "docker-build",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && TAG=$(git rev-parse --short HEAD) && docker build -t {{input.registry}}/{{input.image_name}}:$TAG -t {{input.registry}}/{{input.image_name}}:latest .",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "docker-push",
        "action_type": "SHELL",
        "code": "TAG=$(cd {{input.app_dir}} && git rev-parse --short HEAD) && docker push {{input.registry}}/{{input.image_name}}:$TAG && docker push {{input.registry}}/{{input.image_name}}:latest",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "stop-old-container",
        "action_type": "SHELL",
        "code": "docker stop {{input.image_name}} 2>/dev/null; docker rm {{input.image_name}} 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "run-new-container",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.image_name}} --restart unless-stopped -p 8080:8080 {{input.registry}}/{{input.image_name}}:latest",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 5 && curl -sf http://localhost:8080/health",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "undo-docker-deploy",
        "action_type": "SHELL",
        "code": "docker stop {{input.image_name}} 2>/dev/null; docker rm {{input.image_name}} 2>/dev/null; docker run -d --name {{input.image_name}} --restart unless-stopped -p 8080:8080 {{input.registry}}/{{input.image_name}}:previous 2>/dev/null; true",
        "parent_step_ids": [
          "4"
        ]
      }
    ]
  },
  "explanation": "Docker CI/CD: pull, build image with git tag, push to registry, stop old, run new, health check."
}

