{
  "fields": {
    "name": "worker-docker-cp",
    "action_type": "SHELL",
    "code": "if ! docker inspect {{input.container_name}} > /dev/null 2>&1; then echo \"FAILED: Container {{input.container_name}} not found\" >&2; exit 1; fi && if [ \"{{input.direction}}\" = \"to\" ]; then docker cp \"{{input.local_path}}\" \"{{input.container_name}}:{{input.container_path}}\" 2>&1 && echo \"Copied {{input.local_path}} -> {{input.container_name}}:{{input.container_path}}\"; elif [ \"{{input.direction}}\" = \"from\" ]; then docker cp \"{{input.container_name}}:{{input.container_path}}\" \"{{input.local_path}}\" 2>&1 && echo \"Copied {{input.container_name}}:{{input.container_path}} -> {{input.local_path}}\"; else echo \"FAILED: direction must be to or from\" >&2; exit 1; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "container_name": {
          "type": "string",
          "description": "Container name"
        },
        "local_path": {
          "type": "string",
          "description": "Local file or directory path"
        },
        "container_path": {
          "type": "string",
          "description": "Path inside the container"
        },
        "direction": {
          "type": "string",
          "description": "Copy direction: \"to\" (local->container) or \"from\" (container->local)"
        }
      },
      "required": [
        "container_name",
        "local_path",
        "container_path",
        "direction"
      ]
    }
  },
  "explanation": "Copies files between the host and the worker Docker container in either direction using docker cp."
}

{
  "fields": {
    "name": "Generate grafana config",
    "action_type": "PYTHON",
    "code": "import json\nimport re\nimport sys\n\ntemplate_str = '{{input.template}}'\nvars_json = '{{input.variables}}'\noutput_path = \"{{input.output_path}}\"\n\ntry:\n    variables = json.loads(vars_json)\n    def replacer(match):\n        key = match.group(1).strip()\n        return str(variables.get(key, match.group(0)))\n    rendered = re.sub(r\"\\{\\{\\s*(\\w+)\\s*\\}\\}\", replacer, template_str)\n    with open(output_path, \"w\") as f:\n        f.write(rendered)\n    print(json.dumps({{\n        \"status\": \"ok\",\n        \"output\": output_path,\n        \"vars_applied\": len(variables),\n    }}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "template": {
          "type": "string",
          "description": "Config template string with {{ var }} placeholders"
        },
        "variables": {
          "type": "string",
          "description": "JSON string of template variables"
        },
        "output_path": {
          "type": "string",
          "description": "Output file path for rendered config"
        }
      },
      "required": [
        "template",
        "variables",
        "output_path"
      ]
    }
  },
  "explanation": "Python action that generates a grafana configuration file by rendering a template with variable substitution."
}

