{
  "fields": {
    "name": "swap-management",
    "description": "Configure or resize swap space",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "check-current-swap",
        "action_type": "SHELL",
        "code": "swapon --show && free -h | grep Swap",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "disable-old-swap",
        "action_type": "SHELL",
        "code": "swapoff /swapfile 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "create-swapfile",
        "action_type": "SHELL",
        "code": "fallocate -l {{input.swap_size}} /swapfile && chmod 600 /swapfile",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "schema": {
          "input": {
            "swap_size": {
              "type": "string"
            },
            "swappiness": {
              "type": "string"
            }
          },
          "required": [
            "swap_size",
            "swappiness"
          ]
        }
      },
      {
        "id": "4",
        "undo": false,
        "name": "format-swap",
        "action_type": "SHELL",
        "code": "mkswap /swapfile",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "enable-swap",
        "action_type": "SHELL",
        "code": "swapon /swapfile",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "persist-fstab",
        "action_type": "SHELL",
        "code": "grep -q \"/swapfile\" /etc/fstab || echo \"/swapfile none swap sw 0 0\" >> /etc/fstab",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "set-swappiness",
        "action_type": "SHELL",
        "code": "sysctl vm.swappiness={{input.swappiness}} && echo \"vm.swappiness={{input.swappiness}}\" > /etc/sysctl.d/99-swappiness.conf",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "8",
        "undo": false,
        "name": "verify-swap",
        "action_type": "SHELL",
        "code": "swapon --show | grep /swapfile && sysctl vm.swappiness",
        "target": "all",
        "parent_step_ids": [
          "6",
          "7"
        ],
        "expected_rc": 0
      },
      {
        "id": "9",
        "undo": true,
        "name": "undo-swap",
        "action_type": "SHELL",
        "code": "swapoff /swapfile 2>/dev/null; rm -f /swapfile /etc/sysctl.d/99-swappiness.conf; sed -i \"/\\/swapfile/d\" /etc/fstab; sysctl vm.swappiness=60",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Swap management: check current, disable old, create+format+enable swapfile, persist in fstab, set swappiness, verify."
}

{
  "fields": {
    "name": "full-mail-server",
    "description": "Full mail stack: Postfix + Dovecot + DKIM",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-packages",
        "action_type": "SHELL",
        "code": "DEBIAN_FRONTEND=noninteractive apt-get update && apt-get install -y postfix dovecot-imapd opendkim opendkim-tools",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"myhostname=mail.{{input.domain}}\" && postconf -e \"mydomain={{input.domain}}\" && postconf -e \"home_mailbox=Maildir/\" && postconf -e \"smtpd_tls_cert_file=/etc/letsencrypt/live/{{input.domain}}/fullchain.pem\" && postconf -e \"smtpd_tls_key_file=/etc/letsencrypt/live/{{input.domain}}/privkey.pem\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "domain": {
              "type": "string"
            },
            "dkim_selector": {
              "type": "string"
            }
          },
          "required": [
            "domain",
            "dkim_selector"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-dovecot",
        "action_type": "SHELL",
        "code": "sed -i \"s|^#*mail_location.*|mail_location = maildir:~/Maildir|\" /etc/dovecot/conf.d/10-mail.conf && sed -i \"s/^#*ssl =.*/ssl = required/\" /etc/dovecot/conf.d/10-ssl.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "generate-dkim",
        "action_type": "SHELL",
        "code": "mkdir -p /etc/opendkim/keys/{{input.domain}} && opendkim-genkey -s {{input.dkim_selector}} -d {{input.domain}} -D /etc/opendkim/keys/{{input.domain}} && chown -R opendkim:opendkim /etc/opendkim",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-dkim",
        "action_type": "SHELL",
        "code": "postconf -e \"milter_protocol = 6\" && postconf -e \"smtpd_milters = inet:localhost:8891\" && postconf -e \"non_smtpd_milters = inet:localhost:8891\"",
        "target": "all",
        "parent_step_ids": [
          "2",
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-all-services",
        "action_type": "SHELL",
        "code": "systemctl enable --now postfix dovecot opendkim",
        "target": "all",
        "parent_step_ids": [
          "3",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-smtp",
        "action_type": "SHELL",
        "code": "echo \"QUIT\" | nc localhost 25 | grep -q \"220\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": false,
        "name": "verify-imap",
        "action_type": "SHELL",
        "code": "echo \"A1 LOGOUT\" | openssl s_client -connect localhost:993 -quiet 2>/dev/null | grep -q \"OK\"",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "9",
        "undo": true,
        "name": "undo-mail-stack",
        "action_type": "SHELL",
        "code": "systemctl stop postfix dovecot opendkim; apt-get remove -y postfix dovecot-imapd opendkim opendkim-tools",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Full mail stack: install all packages, configure Postfix+Dovecot+DKIM in parallel, start all, verify SMTP+IMAP."
}

