        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "run-new-container",
        "action_type": "SHELL",
        "code": "docker run -d --name {{input.image_name}} --restart unless-stopped -p 8080:8080 {{input.registry}}/{{input.image_name}}:latest",
