{
  "fields": {
    "name": "Report mysql database size",
    "action_type": "PYTHON",
    "code": "import json
import sqlite3
import os
import sys

db_path = "{{input.db_path}}"
max_size_mb = float("{{input.max_size_mb}}" or "0")

if not os.path.isfile(db_path):
    print(json.dumps({{"status": "error", "message": f"Database not found: {{db_path}}"}}))
    sys.exit(1)

try:
    size_bytes = os.path.getsize(db_path)
    size_mb = round(size_bytes / (1024 * 1024), 2)
    conn = sqlite3.connect(db_path)
    tables = conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
    table_info = []
    for (tname,) in tables:
        count = conn.execute(f"SELECT COUNT(*) FROM {{tname}}").fetchone()[0]
        table_info.append({{"table": tname, "rows": count}})
    conn.close()
    over_limit = max_size_mb > 0 and size_mb > max_size_mb
    print(json.dumps({{
        "status": "warning" if over_limit else "ok",
        "size_mb": size_mb,
        "size_bytes": size_bytes,
        "tables": table_info,
        "table_count": len(table_info),
    }}))
    if over_limit:
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "db_path": {
          "type": "string",
          "description": "Path to SQLite database file"
        },
        "max_size_mb": {
          "type": "string",
          "description": "Max size alert threshold in MB (0=no limit)"
        }
      },
      "required": [
        "db_path"
      ]
    }
  },
  "explanation": "Python action that reports mysql database size, table count, and row counts, with optional size threshold alerting."
}

