{
  "fields": {
    "name": "Backup haproxy config file",
    "action_type": "PYTHON",
    "code": "import json
import os
import shutil
import sys
from datetime import datetime, timezone

config_path = "{{input.config_path}}"
backup_dir = "{{input.backup_dir}}" or "/tmp/config_backups"
max_backups = int("{{input.max_backups}}" or "10")

if not os.path.isfile(config_path):
    print(json.dumps({{"status": "error", "message": f"Config not found: {{config_path}}"}}))
    sys.exit(1)

os.makedirs(backup_dir, exist_ok=True)
ts = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
filename = os.path.basename(config_path)
backup_path = os.path.join(backup_dir, f"{{filename}}.{{ts}}.bak")
shutil.copy2(config_path, backup_path)

backups = sorted(
    [f for f in os.listdir(backup_dir) if f.startswith(filename) and f.endswith(".bak")],
    reverse=True,
)
removed = []
for old in backups[max_backups:]:
    os.remove(os.path.join(backup_dir, old))
    removed.append(old)

print(json.dumps({{
    "status": "backed_up",
    "source": config_path,
    "backup": backup_path,
    "size_bytes": os.path.getsize(backup_path),
    "pruned": len(removed),
}}))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "config_path": {
          "type": "string",
          "description": "Path to config file to back up"
        },
        "backup_dir": {
          "type": "string",
          "description": "Directory to store backups (default /tmp/config_backups)"
        },
        "max_backups": {
          "type": "string",
          "description": "Max backups to keep (default 10)"
        }
      },
      "required": [
        "config_path"
      ]
    }
  },
  "explanation": "Python action that creates a timestamped backup of the haproxy config file and prunes old backups."
}

