{
  "fields": {
    "name": "log-alerting",
    "description": "Set up log-based alerting",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-alert-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/log-alert.sh <<SCRIPT\n#!/bin/bash\nPATTERN=\"{{input.alert_pattern}}\"\nLOGFILE=\"{{input.log_path}}\"\nERRORS=$(tail -100 \"$LOGFILE\" | grep -c \"$PATTERN\")\nif [ \"$ERRORS\" -gt {{input.threshold}} ]; then\n  echo \"ALERT: $ERRORS matches for $PATTERN in $LOGFILE\" | logger -t log-alert\nfi\nSCRIPT\nchmod +x /usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/5 * * * * /usr/local/bin/log-alert.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-alert-script",
        "action_type": "SHELL",
        "code": "/usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": true,
        "name": "undo-log-alerting",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v log-alert | crontab - && rm -f /usr/local/bin/log-alert.sh",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Log alerting: create alert script, add cron, test. Matches pattern in log and fires syslog alert."
}

{
  "fields": {
    "name": "Read temperature sensors",
    "action_type": "PYTHON",
    "code": "import json
import os
import glob
import sys

threshold_c = float("{{input.threshold_c}}" or "85")

sensors = []
thermal_zones = glob.glob("/sys/class/thermal/thermal_zone*/temp")

for path in sorted(thermal_zones):
    zone = os.path.basename(os.path.dirname(path))
    type_path = os.path.join(os.path.dirname(path), "type")
    try:
        with open(path, "r") as f:
            temp_mc = int(f.read().strip())
        temp_c = temp_mc / 1000.0
        sensor_type = "unknown"
        if os.path.isfile(type_path):
            with open(type_path, "r") as f:
                sensor_type = f.read().strip()
        sensors.append({{"zone": zone, "type": sensor_type, "temp_c": temp_c}})
    except Exception:
        continue

max_temp = max((s["temp_c"] for s in sensors), default=0.0)
result = {{
    "sensors": sensors,
    "max_temp_c": max_temp,
    "threshold_c": threshold_c,
    "status": "critical" if max_temp > threshold_c else "ok",
}}
print(json.dumps(result))
if max_temp > threshold_c:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "threshold_c": {
          "type": "string",
          "description": "Temperature threshold in Celsius (default 85)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads thermal zone sensors from /sys/class/thermal and alerts if any exceed the temperature threshold."
}

