        "username": {
          "type": "string",
          "description": "Database user with vacuum privilege"
        },
        "database": {
          "type": "string",
          "description": "Database name"
        },
        "table_name": {
          "type": "string",
          "description": "Table to vacuum and analyze"
        }
      },
      "required": [
        "host",
        "username",
        "database",
        "table_name"
      ]
    }
  },
  "explanation": "Runs VACUUM ANALYZE on a PostgreSQL table in the analytics environment and displays dead tuple statistics."
}

