{
  "fields": {
    "name": "Ping MySQL server",
    "action_type": "PYTHON",
    "code": "import json\nimport socket\nimport sys\n\nhost = \"{{input.host}}\" or \"localhost\"\nport = int(\"{{input.port}}\" or \"3306\")\ntimeout = int(\"{{input.timeout}}\" or \"5\")\n\ntry:\n    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n    sock.settimeout(timeout)\n    sock.connect((host, port))\n    greeting = sock.recv(1024)\n    sock.close()\n    if len(greeting) > 4:\n        version_end = greeting.find(b\"\\x00\", 5)\n        version = greeting[5:version_end].decode(\"utf-8\", errors=\"replace\") if version_end > 5 else \"unknown\"\n        print(json.dumps({{\"status\": \"ok\", \"host\": host, \"port\": port, \"version\": version}}))\n    else:\n        print(json.dumps({{\"status\": \"ok\", \"host\": host, \"port\": port, \"message\": \"MySQL responded\"}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "MySQL host (default localhost)"
        },
        "port": {
          "type": "string",
          "description": "MySQL port (default 3306)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 5)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that pings the replica MySQL server by connecting via socket and reading the protocol greeting."
}

