{
  "fields": {
    "name": "Count postgres processes",
    "action_type": "PYTHON",
    "code": "import json
import os
import sys

process_name = "{{input.process_name}}"
min_count = int("{{input.min_count}}" or "1")

count = 0
pids = []
for pid in os.listdir("/proc"):
    if not pid.isdigit():
        continue
    try:
        with open(f"/proc/{{pid}}/comm", "r") as f:
            comm = f.read().strip()
        if process_name in comm:
            count += 1
            pids.append(int(pid))
    except (IOError, OSError):
        continue

result = {{
    "process": process_name,
    "count": count,
    "pids": pids[:20],
    "min_expected": min_count,
    "status": "ok" if count >= min_count else "critical",
}}
print(json.dumps(result))
if count < min_count:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "process_name": {
          "type": "string",
          "description": "Process name to search for"
        },
        "min_count": {
          "type": "string",
          "description": "Minimum expected process count (default 1)"
        }
      },
      "required": [
        "process_name"
      ]
    }
  },
  "explanation": "Python action that counts running postgres processes by scanning /proc and alerts if count is below minimum."
}

