          "type": "string",
          "description": "Volume group name"
        },
        "lv_name": {
          "type": "string",
          "description": "Logical volume name"
        },
        "size": {
          "type": "string",
          "description": "Size (e.g. 10G, 500M)"
        },
        "fs_type": {
          "type": "string",
          "description": "Filesystem type for new LVs (e.g. ext4, xfs)"
        }
      },
      "required": [
        "action",
        "vg_name",
        "lv_name",
        "size"
      ]
    }
  },
  "explanation": "Performs LVM logical volume create operation with filesystem creation or extension."
}

