{
  "fields": {
    "name": "blue-green-single",
    "description": "Blue-green deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "detect-active-slot",
        "action_type": "SHELL",
        "code": "ACTIVE=$(readlink {{input.app_dir}}/current); if [ \"$ACTIVE\" = \"{{input.app_dir}}/blue\" ]; then echo green > /tmp/deploy_slot; else echo blue > /tmp/deploy_slot; fi",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "repo_url": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "repo_url",
            "branch"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clone-to-inactive",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && rm -rf {{input.app_dir}}/$SLOT && git clone -b {{input.branch}} {{input.repo_url}} {{input.app_dir}}/$SLOT",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps-new",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm ci",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "test-new-slot",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm test",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "switch-symlink",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && ln -sfn {{input.app_dir}}/$SLOT {{input.app_dir}}/current",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-app",
        "action_type": "SHELL",
        "code": "systemctl restart app",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:3000/health",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-blue-green",
        "action_type": "SHELL",
        "code": "ACTIVE=$(cat /tmp/deploy_slot); if [ \"$ACTIVE\" = \"green\" ]; then OTHER=blue; else OTHER=green; fi && ln -sfn {{input.app_dir}}/$OTHER {{input.app_dir}}/current && systemctl restart app",
        "parent_step_ids": [
          "5"
        ]
      }
    ]
  },
  "explanation": "Blue-green: detect active slot, clone to inactive, install, test, swap symlink, restart, health check."
}

{
  "fields": {
    "name": "docker-volume-backup",
    "description": "Backup Docker volumes to compressed archive",
    "stop_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-backup-dir",
        "action_type": "SHELL",
        "code": "mkdir -p {{input.backup_dir}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "volume_name": {
              "type": "string"
            },
            "backup_dir": {
              "type": "string"
            }
          },
          "required": [
            "volume_name",
            "backup_dir"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "stop-using-containers",
        "action_type": "SHELL",
        "code": "CONTAINERS=$(docker ps -q --filter volume={{input.volume_name}}); if [ -n \"$CONTAINERS\" ]; then docker stop $CONTAINERS; echo \"$CONTAINERS\" > /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "backup-volume",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && docker run --rm -v {{input.volume_name}}:/source -v {{input.backup_dir}}:/backup alpine tar czf /backup/{{input.volume_name}}_$TIMESTAMP.tar.gz -C /source .",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-containers",
        "action_type": "SHELL",
        "code": "if [ -f /tmp/vol_backup_containers ]; then cat /tmp/vol_backup_containers | xargs docker start; rm /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-backup",
        "action_type": "SHELL",
        "code": "ls -lh {{input.backup_dir}}/{{input.volume_name}}_*.tar.gz | tail -1",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      }
    ]
  },
  "explanation": "Volume backup: mkdir, stop containers using volume, tar the volume, restart containers, verify archive."
}

