    "action_type": "SHELL",
    "code": "if [ ! -f \"{{input.cert_path}}\" ] || [ ! -f \"{{input.key_path}}\" ]; then echo \"FAILED: Certificate or key file not found\" >&2; exit 1; fi && CHAIN_OPT=\"\" && if [ -n \"{{input.chain_path}}\" ] && [ -f \"{{input.chain_path}}\" ]; then CHAIN_OPT=\"-certfile {{input.chain_path}}\"; fi && openssl pkcs12 -export -out {{input.p12_path}} -inkey {{input.key_path}} -in {{input.cert_path}} $CHAIN_OPT -name {{input.friendly_name}} -passout pass:{{input.export_password}} 2>&1 && chmod 600 {{input.p12_path}} && echo \"PKCS12 file created: {{input.p12_path}}\" && openssl pkcs12 -in {{input.p12_path}} -passin pass:{{input.export_password}} -nokeys -info 2>&1 | head -5 || (echo \"FAILED: PKCS12 conversion error\" >&2; exit 1)",
    "expected_rc": 0,
    "schema": {
      "input": {
        "cert_path": {
          "type": "string",
          "description": "Path to the PEM certificate file"
        },
        "key_path": {
          "type": "string",
          "description": "Path to the PEM private key file"
        },
        "chain_path": {
          "type": "string",
          "description": "Path to the CA chain file (optional, empty string to skip)"
        },
        "p12_path": {
          "type": "string",
          "description": "Output path for the PKCS12 file"
        },
        "friendly_name": {
          "type": "string",
          "description": "Friendly name for the certificate in the PKCS12 bundle"
        },
        "export_password": {
          "type": "string",
          "description": "Password to protect the PKCS12 file"
        }
      },
      "required": [
        "cert_path",
        "key_path",
        "p12_path",
        "friendly_name",
        "export_password"
      ]
    }
  },
  "explanation": "Converts PEM certificate and key files to PKCS12 format for the loadbalancer service, optionally including the CA chain."
}

{
  "fields": {
    "name": "docker-volume-backup",
    "description": "Backup Docker volumes to compressed archive",
    "stop_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-backup-dir",
        "action_type": "SHELL",
        "code": "mkdir -p {{input.backup_dir}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "volume_name": {
              "type": "string"
            },
            "backup_dir": {
              "type": "string"
            }
          },
          "required": [
            "volume_name",
            "backup_dir"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "stop-using-containers",
        "action_type": "SHELL",
        "code": "CONTAINERS=$(docker ps -q --filter volume={{input.volume_name}}); if [ -n \"$CONTAINERS\" ]; then docker stop $CONTAINERS; echo \"$CONTAINERS\" > /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "backup-volume",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && docker run --rm -v {{input.volume_name}}:/source -v {{input.backup_dir}}:/backup alpine tar czf /backup/{{input.volume_name}}_$TIMESTAMP.tar.gz -C /source .",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-containers",
        "action_type": "SHELL",
        "code": "if [ -f /tmp/vol_backup_containers ]; then cat /tmp/vol_backup_containers | xargs docker start; rm /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
