{
  "fields": {
    "name": "uptime-monitor-setup",
    "description": "Set up endpoint uptime monitoring",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-check-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/uptime-check.sh <<SCRIPT\n#!/bin/bash\nLOGFILE=/var/log/uptime-monitor.log\nfor URL in {{input.urls}}; do\n  STATUS=$(curl -sf -o /dev/null -w \"%%{http_code}\" --max-time 10 \"$URL\" 2>/dev/null)\n  echo \"$(date -Iseconds) $URL $STATUS\" >> $LOGFILE\n  if [ \"$STATUS\" != \"200\" ]; then\n    echo \"ALERT: $URL returned $STATUS\" | logger -t uptime-monitor\n  fi\ndone\nSCRIPT\nchmod +x /usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "urls": {
              "type": "string"
            },
            "interval_min": {
              "type": "string"
            }
          },
          "required": [
            "urls",
            "interval_min"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-log-file",
        "action_type": "SHELL",
        "code": "touch /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "add-cron-job",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/{{input.interval_min}} * * * * /usr/local/bin/uptime-check.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-initial-check",
        "action_type": "SHELL",
        "code": "/usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-log-output",
        "action_type": "SHELL",
        "code": "test -s /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-uptime-monitor",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v uptime-check | crontab - && rm -f /usr/local/bin/uptime-check.sh /var/log/uptime-monitor.log",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Uptime monitor: create check script, add cron job, run initial check, verify log."
}

{
  "fields": {
    "name": "canary-single-server",
    "description": "Canary deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "deploy-canary",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git stash && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "canary_port": {
              "type": "string"
            },
            "prod_port": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "canary_port",
            "prod_port"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-canary",
        "action_type": "SHELL",
        "code": "PORT={{input.canary_port}} node {{input.app_dir}}/server.js &",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "canary-health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:{{input.canary_port}}/health",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "route-canary-traffic",
        "action_type": "SHELL",
        "code": "sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}} weight=9;\\n    server 127.0.0.1:{{input.canary_port}} weight=1;/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "monitor-errors",
        "action_type": "SHELL",
        "code": "sleep 30 && ERROR_RATE=$(tail -100 /var/log/nginx/access.log | grep -c \" 5[0-9][0-9] \") && test \"$ERROR_RATE\" -lt 5",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": false,
        "name": "promote-canary",
        "action_type": "SHELL",
        "code": "systemctl restart app && kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && sed -i \"s/server 127.0.0.1:{{input.prod_port}};/server 127.0.0.1:{{input.prod_port}};/\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-canary",
        "action_type": "SHELL",
        "code": "kill $(lsof -ti:{{input.canary_port}}) 2>/dev/null; cd {{input.app_dir}} && git stash pop; sed -i \"/weight=/d\" /etc/nginx/conf.d/upstream.conf && nginx -s reload",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Canary: deploy new version on alternate port, route 10% traffic, monitor errors, promote or rollback."
}

