        "code": "find /home -path \"*/.cache/thumbnails\" -type d -exec rm -rf {} + 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "6",
        "undo": false,
        "name": "report-freed-space",
        "action_type": "SHELL",
        "code": "df -h / /tmp /var",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2",
          "3",
          "4",
          "5"
        ]
      }
