    "code": "import json\nimport socket\nimport sys\n\nprimary_host = \"{{input.primary_host}}\"\nprimary_port = int(\"{{input.primary_port}}\")\nreplica_host = \"{{input.replica_host}}\"\nreplica_port = int(\"{{input.replica_port}}\")\ntimeout = int(\"{{input.timeout}}\" or \"5\")\n\nresults = {{}}\nfor label, host, port in [(\"primary\", primary_host, primary_port), (\"replica\", replica_host, replica_port)]:\n    try:\n        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n        sock.settimeout(timeout)\n        result = sock.connect_ex((host, port))\n        sock.close()\n        results[label] = {{\"host\": host, \"port\": port, \"reachable\": result == 0}}\n    except Exception as e:\n        results[label] = {{\"host\": host, \"port\": port, \"reachable\": False, \"error\": str(e)}}\n\nboth_up = results.get(\"primary\", {{}}).get(\"reachable\", False) and results.get(\"replica\", {{}}).get(\"reachable\", False)\noutput = {{\n    \"status\": \"ok\" if both_up else \"error\",\n    \"primary\": results.get(\"primary\", {{}}),\n    \"replica\": results.get(\"replica\", {{}}),\n}}\nprint(json.dumps(output))\nif not both_up:\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "primary_host": {
          "type": "string",
          "description": "Primary/master database host"
        },
        "primary_port": {
          "type": "string",
          "description": "Primary database port"
        },
        "replica_host": {
          "type": "string",
          "description": "Replica/slave database host"
        },
        "replica_port": {
          "type": "string",
          "description": "Replica database port"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 5)"
        }
      },
      "required": [
        "primary_host",
        "primary_port",
        "replica_host",
        "replica_port"
      ]
    }
  },
  "explanation": "Python action that checks postgres replication status by verifying connectivity to both the primary and replica instances."
}

