{
  "fields": {
    "name": "Check memory usage",
    "action_type": "PYTHON",
    "code": "import json
import sys

threshold = float("{{input.threshold}}" or "80")

meminfo = {{}}
with open("/proc/meminfo", "r") as f:
    for line in f:
        parts = line.split()
        key = parts[0].rstrip(":")
        meminfo[key] = int(parts[1])

total = meminfo.get("MemTotal", 0)
available = meminfo.get("MemAvailable", 0)
used = total - available
pct = (used / total) * 100.0 if total > 0 else 0.0

result = {{
    "total_mb": round(total / 1024, 1),
    "used_mb": round(used / 1024, 1),
    "available_mb": round(available / 1024, 1),
    "percent_used": round(pct, 2),
    "threshold": threshold,
    "status": "critical" if pct > threshold else "ok",
}}
print(json.dumps(result))
if pct > threshold:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "threshold": {
          "type": "string",
          "description": "Memory usage percent threshold (default 80)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/meminfo to compute memory usage and alerts if it exceeds the threshold."
}

