{
  "fields": {
    "name": "Decode JWT token",
    "action_type": "PYTHON",
    "code": "import json
import base64
import sys

token = "{{input.token}}"

parts = token.split(".")
if len(parts) != 3:
    print(json.dumps({{"status": "error", "message": "Invalid JWT format"}}))
    sys.exit(1)

def decode_part(part):
    padding = 4 - len(part) % 4
    part += "=" * padding
    return json.loads(base64.urlsafe_b64decode(part).decode("utf-8"))

try:
    header = decode_part(parts[0])
    payload = decode_part(parts[1])
    import time
    exp = payload.get("exp")
    expired = exp is not None and exp < time.time()
    print(json.dumps({{
        "status": "ok",
        "header": header,
        "payload": payload,
        "expired": expired,
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "token": {
          "type": "string",
          "description": "JWT token string to decode"
        }
      },
      "required": [
        "token"
      ]
    }
  },
  "explanation": "Python action that decodes a api-access JWT token header and payload using base64, checking expiration."
}

{
  "fields": {
    "name": "Time mariadb query execution",
    "action_type": "PYTHON",
    "code": "import json
import sqlite3
import time
import sys

db_path = "{{input.db_path}}"
query = "{{input.query}}" or "SELECT 1"
iterations = int("{{input.iterations}}" or "10")

try:
    conn = sqlite3.connect(db_path)
    timings = []
    for i in range(iterations):
        start = time.time()
        conn.execute(query).fetchall()
        elapsed = (time.time() - start) * 1000
        timings.append(round(elapsed, 3))
    conn.close()
    avg = round(sum(timings) / len(timings), 3)
    print(json.dumps({{
        "status": "ok",
        "iterations": iterations,
        "avg_ms": avg,
        "min_ms": min(timings),
        "max_ms": max(timings),
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "db_path": {
          "type": "string",
          "description": "Path to SQLite database file"
        },
        "query": {
          "type": "string",
          "description": "SQL query to benchmark (default SELECT 1)"
        },
        "iterations": {
          "type": "string",
          "description": "Number of iterations (default 10)"
        }
      },
      "required": [
        "db_path"
      ]
    }
  },
  "explanation": "Python action that benchmarks mariadb query execution time over multiple iterations and reports min/avg/max latency."
}

