{
  "fields": {
    "name": "Base64 encode file",
    "action_type": "PYTHON",
    "code": "import base64
import json
import os
import sys

input_path = "{{input.input_path}}"
output_path = "{{input.output_path}}"
operation = "{{input.operation}}" or "encode"

if not os.path.isfile(input_path):
    print(json.dumps({{"status": "error", "message": f"File not found: {{input_path}}"}}))
    sys.exit(1)

try:
    with open(input_path, "rb") as f:
        data = f.read()
    if operation == "encode":
        result = base64.b64encode(data)
    elif operation == "decode":
        result = base64.b64decode(data)
    else:
        print(json.dumps({{"status": "error", "message": f"Invalid operation: {{operation}}"}}))
        sys.exit(1)
    with open(output_path, "wb") as f:
        f.write(result)
    print(json.dumps({{
        "status": "ok",
        "operation": operation,
        "input_size": len(data),
        "output_size": len(result),
        "output_path": output_path,
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "input_path": {
          "type": "string",
          "description": "Path to input file"
        },
        "output_path": {
          "type": "string",
          "description": "Path for output file"
        },
        "operation": {
          "type": "string",
          "description": "Operation: encode or decode (default encode)"
        }
      },
      "required": [
        "input_path",
        "output_path"
      ]
    }
  },
  "explanation": "Python action that performs base64 encode on a file for secure transport or storage."
}

