        "id": "1",
        "undo": false,
        "name": "install-apparmor-utils",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y apparmor-utils",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-profile",
        "action_type": "SHELL",
        "code": "cat > /etc/apparmor.d/usr.local.bin.{{input.app_name}} <<PROF\n#include <tunables/global>\n/usr/local/bin/{{input.app_name}} {\n  #include <abstractions/base>\n  #include <abstractions/nameservice>\n  /usr/local/bin/{{input.app_name}} mr,\n  /var/log/{{input.app_name}}/** rw,\n  /tmp/{{input.app_name}}/** rw,\n  /etc/{{input.app_name}}/** r,\n  deny /etc/shadow r,\n  deny /etc/passwd w,\n}\nPROF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "app_name": {
              "type": "string"
            }
          },
          "required": [
            "app_name"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "load-profile-complain",
        "action_type": "SHELL",
        "code": "apparmor_parser -r /etc/apparmor.d/usr.local.bin.{{input.app_name}} && aa-complain /usr/local/bin/{{input.app_name}}",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enforce-profile",
        "action_type": "SHELL",
