    "code": "import json\nimport urllib.request\nimport sys\n\napi_url = \"{{input.api_url}}\"\napi_key = \"{{input.api_key}}\"\ninstance_id = \"{{input.instance_id}}\"\ntags_json = '{{input.tags}}'\n\ntags = json.loads(tags_json)\npayload = {{\"instance_id\": instance_id, \"tags\": tags}}\ndata = json.dumps(payload).encode(\"utf-8\")\nreq = urllib.request.Request(api_url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    print(json.dumps({{\"status\": \"tagged\", \"instance\": instance_id, \"tags\": tags}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "api_url": {
          "type": "string",
          "description": "Cloud API URL for tagging"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        },
        "instance_id": {
          "type": "string",
          "description": "Instance ID to tag"
        },
        "tags": {
          "type": "string",
          "description": "JSON string of key-value tags"
        }
      },
      "required": [
        "api_url",
        "api_key",
        "instance_id",
        "tags"
      ]
    }
  },
  "explanation": "Python action that applies key-value tags to a hetzner cloud instance via API."
}

{
  "fields": {
    "name": "spamassassin-filter",
    "description": "Install and configure SpamAssassin",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-spamassassin",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y spamassassin spamc",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-spamd-user",
        "action_type": "SHELL",
        "code": "useradd -r -s /bin/false -d /var/lib/spamassassin spamd 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-rules",
        "action_type": "SHELL",
        "code": "cat > /etc/spamassassin/local.cf <<SPAM\nrewrite_header Subject [SPAM]\nrequired_score {{input.spam_score}}\nuse_bayes 1\nbayes_auto_learn 1\nSPAM",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "spam_score": {
              "type": "string"
            }
          },
          "required": [
            "spam_score"
          ]
        }
      },
      {
        "id": "4",
        "undo": false,
        "name": "update-rules",
        "action_type": "SHELL",
        "code": "sa-update",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"content_filter = smtp-amavis:[127.0.0.1]:10024\" 2>/dev/null; sed -i \"s/^ENABLED=0/ENABLED=1/\" /etc/default/spamassassin",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl enable --now spamassassin && systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-spamd",
        "action_type": "SHELL",
        "code": "echo \"Subject: Test\" | spamc -c; true",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-spamassassin",
        "action_type": "SHELL",
        "code": "systemctl stop spamassassin; postconf -e \"content_filter =\"; systemctl restart postfix; apt-get remove -y spamassassin spamc",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
