{
  "fields": {
    "name": "Check system load average",
    "action_type": "PYTHON",
    "code": "import json
import os
import sys

threshold_multiplier = float("{{input.threshold_multiplier}}" or "1.5")

with open("/proc/loadavg", "r") as f:
    parts = f.read().split()

load_1 = float(parts[0])
load_5 = float(parts[1])
load_15 = float(parts[2])
cpu_count = os.cpu_count() or 1
threshold = cpu_count * threshold_multiplier

result = {{
    "load_1min": load_1,
    "load_5min": load_5,
    "load_15min": load_15,
    "cpu_count": cpu_count,
    "threshold": threshold,
    "status": "critical" if load_1 > threshold else "ok",
}}
print(json.dumps(result))
if load_1 > threshold:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "threshold_multiplier": {
          "type": "string",
          "description": "Load threshold as CPU count multiplier (default 1.5)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/loadavg and alerts if 1-minute load exceeds 3.0x the CPU count."
}

