          "description": "Port(s) to protect (e.g. ssh, http,https)"
        },
        "filter_name": {
          "type": "string",
          "description": "fail2ban filter to use (e.g. sshd, nginx-http-auth)"
        },
        "log_path": {
          "type": "string",
          "description": "Path to the log file to monitor"
        },
        "max_retry": {
          "type": "integer",
          "description": "Number of failures before ban"
        },
        "ban_time": {
          "type": "string",
          "description": "Ban duration (e.g. 3600, 1h, 1d)"
        },
        "find_time": {
          "type": "string",
          "description": "Time window for counting failures (e.g. 600, 10m)"
        }
      },
      "required": [
        "jail_name",
        "port",
        "filter_name",
        "log_path",
        "max_retry",
        "ban_time",
        "find_time"
      ]
