{
  "fields": {
    "name": "Count java processes",
    "action_type": "PYTHON",
    "code": "import json
import os
import sys

process_name = "{{input.process_name}}"
min_count = int("{{input.min_count}}" or "1")

count = 0
pids = []
for pid in os.listdir("/proc"):
    if not pid.isdigit():
        continue
    try:
        with open(f"/proc/{{pid}}/comm", "r") as f:
            comm = f.read().strip()
        if process_name in comm:
            count += 1
            pids.append(int(pid))
    except (IOError, OSError):
        continue

result = {{
    "process": process_name,
    "count": count,
    "pids": pids[:20],
    "min_expected": min_count,
    "status": "ok" if count >= min_count else "critical",
}}
print(json.dumps(result))
if count < min_count:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "process_name": {
          "type": "string",
          "description": "Process name to search for"
        },
        "min_count": {
          "type": "string",
          "description": "Minimum expected process count (default 1)"
        }
      },
      "required": [
        "process_name"
      ]
    }
  },
  "explanation": "Python action that counts running java processes by scanning /proc and alerts if count is below minimum."
}

{
  "fields": {
    "name": "Expand environment variables",
    "action_type": "PYTHON",
    "code": "import os
import re
import json
import sys

input_path = "{{input.input_path}}"
output_path = "{{input.output_path}}"
strict = "{{input.strict}}" == "true"

def expand_env(text, strict_mode):
    missing = []
    def replacer(match):
        var = match.group(1) or match.group(2)
        value = os.environ.get(var)
        if value is None:
            missing.append(var)
            return match.group(0) if not strict_mode else ""
        return value
    expanded = re.sub(r"\$\{{(\w+)\}}|\$(\w+)", replacer, text)
    return expanded, missing

try:
    with open(input_path, "r") as f:
        content = f.read()

    expanded, missing = expand_env(content, strict)

    if strict and missing:
        print(json.dumps({{"status": "error", "missing_vars": missing}}))
        sys.exit(1)

    with open(output_path, "w") as f:
        f.write(expanded)

    print(json.dumps({{
        "status": "expanded",
        "output": output_path,
        "missing_vars": missing,
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "input_path": {
          "type": "string",
          "description": "Path to template file with $VAR or ${VAR} references"
        },
        "output_path": {
          "type": "string",
          "description": "Path for expanded output"
        },
        "strict": {
          "type": "string",
          "description": "Fail on missing vars: true/false (default false)"
        }
      },
      "required": [
        "input_path",
        "output_path"
      ]
    }
  },
  "explanation": "Python action that expands environment variable references in a shell-script file, optionally failing on missing variables."
}

