    "code": "TIMESTAMP=$(date +%Y%m%d_%H%M%S) && SNAP_FILE=\"{{input.backup_dir}}/etcd_snapshot_${TIMESTAMP}.db\" && mkdir -p {{input.backup_dir}} && ETCDCTL_API=3 etcdctl snapshot save \"$SNAP_FILE\" --endpoints={{input.endpoints}} --cacert={{input.ca_cert}} --cert={{input.client_cert}} --key={{input.client_key}} 2>&1 && ETCDCTL_API=3 etcdctl snapshot status \"$SNAP_FILE\" --write-out=table 2>&1 && echo \"etcd snapshot saved: $SNAP_FILE\" || (echo \"FAILED: etcd snapshot error\" >&2; exit 1)",
    "expected_rc": 0,
    "schema": {
      "input": {
        "backup_dir": {
          "type": "string",
          "description": "Directory to store the snapshot"
        },
        "endpoints": {
          "type": "string",
          "description": "etcd endpoint URL (e.g. https://127.0.0.1:2379)"
        },
        "ca_cert": {
          "type": "string",
          "description": "Path to CA certificate file"
        },
        "client_cert": {
          "type": "string",
          "description": "Path to client certificate file"
        },
        "client_key": {
          "type": "string",
          "description": "Path to client key file"
        }
      },
      "required": [
        "backup_dir",
        "endpoints",
        "ca_cert",
        "client_cert",
        "client_key"
      ]
    }
  },
  "explanation": "Creates an etcd v3 snapshot backup for the k8s-cluster cluster with TLS authentication."
}

{
  "fields": {
    "name": "docker-volume-backup",
    "description": "Backup Docker volumes to compressed archive",
    "stop_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-backup-dir",
        "action_type": "SHELL",
        "code": "mkdir -p {{input.backup_dir}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "volume_name": {
              "type": "string"
            },
            "backup_dir": {
              "type": "string"
            }
          },
          "required": [
            "volume_name",
            "backup_dir"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "stop-using-containers",
        "action_type": "SHELL",
        "code": "CONTAINERS=$(docker ps -q --filter volume={{input.volume_name}}); if [ -n \"$CONTAINERS\" ]; then docker stop $CONTAINERS; echo \"$CONTAINERS\" > /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "backup-volume",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && docker run --rm -v {{input.volume_name}}:/source -v {{input.backup_dir}}:/backup alpine tar czf /backup/{{input.volume_name}}_$TIMESTAMP.tar.gz -C /source .",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-containers",
        "action_type": "SHELL",
        "code": "if [ -f /tmp/vol_backup_containers ]; then cat /tmp/vol_backup_containers | xargs docker start; rm /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-backup",
        "action_type": "SHELL",
        "code": "ls -lh {{input.backup_dir}}/{{input.volume_name}}_*.tar.gz | tail -1",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      }
    ]
  },
  "explanation": "Volume backup: mkdir, stop containers using volume, tar the volume, restart containers, verify archive."
}

