{
  "fields": {
    "name": "Parse XML document",
    "action_type": "PYTHON",
    "code": "import json
import sys
import xml.etree.ElementTree as ET

xml_path = "{{input.xml_path}}"
xpath = "{{input.xpath}}"

def element_to_dict(elem):
    result = {{"tag": elem.tag, "attributes": dict(elem.attrib)}}
    text = (elem.text or "").strip()
    if text:
        result["text"] = text
    children = [element_to_dict(child) for child in elem]
    if children:
        result["children"] = children
    return result

try:
    tree = ET.parse(xml_path)
    root = tree.getroot()
    if xpath:
        elements = root.findall(xpath)
        results = [element_to_dict(e) for e in elements]
    else:
        results = [element_to_dict(root)]
    print(json.dumps({{"status": "ok", "count": len(results), "elements": results}}))
except ET.ParseError as e:
    print(json.dumps({{"status": "error", "message": f"XML parse error: {{e}}"}}))
    sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "xml_path": {
          "type": "string",
          "description": "Path to XML file"
        },
        "xpath": {
          "type": "string",
          "description": "XPath expression to query (optional)"
        }
      },
      "required": [
        "xml_path"
      ]
    }
  },
  "explanation": "Python action that parses a sitemap XML file, optionally applying an XPath query, and returns elements as JSON."
}

