{
  "fields": {
    "name": "Validate cockroachdb conn pool",
    "action_type": "PYTHON",
    "code": "import json
import socket
import sys

host = "{{input.host}}" or "localhost"
port = int("{{input.port}}")
max_connections = int("{{input.max_connections}}" or "10")
timeout = int("{{input.timeout}}" or "3")

successful = 0
failed = 0
sockets = []

for i in range(max_connections):
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(timeout)
        s.connect((host, port))
        sockets.append(s)
        successful += 1
    except Exception:
        failed += 1

for s in sockets:
    try:
        s.close()
    except Exception:
        pass

result = {{
    "status": "ok" if failed == 0 else "degraded",
    "host": host,
    "port": port,
    "successful": successful,
    "failed": failed,
    "max_connections": max_connections,
}}
print(json.dumps(result))
if failed > 0:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "Database host (default localhost)"
        },
        "port": {
          "type": "string",
          "description": "Database port"
        },
        "max_connections": {
          "type": "string",
          "description": "Number of connections to test (default 10)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 3)"
        }
      },
      "required": [
        "port"
      ]
    }
  },
  "explanation": "Python action that validates cockroachdb connection pool by opening multiple simultaneous TCP connections."
}

