{
  "fields": {
    "name": "Render config from template",
    "action_type": "PYTHON",
    "code": "import json\nimport re\nimport sys\n\ntemplate_path = \"{{input.template_path}}\"\nvars_json = '{{input.variables}}'\noutput_path = \"{{input.output_path}}\"\n\ndef simple_render(template_str, variables):\n    \"\"\"Simple template renderer replacing {{ var }} patterns.\"\"\"\n    def replacer(match):\n        key = match.group(1).strip()\n        return str(variables.get(key, match.group(0)))\n    return re.sub(r\"\\{\\{\\s*(\\w+)\\s*\\}\\}\", replacer, template_str)\n\ntry:\n    with open(template_path, \"r\") as f:\n        template = f.read()\n    variables = json.loads(vars_json)\n    rendered = simple_render(template, variables)\n    with open(output_path, \"w\") as f:\n        f.write(rendered)\n    print(json.dumps({{\"status\": \"rendered\", \"output\": output_path, \"vars_used\": len(variables)}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "template_path": {
          "type": "string",
          "description": "Path to template file with {{ var }} placeholders"
        },
        "variables": {
          "type": "string",
          "description": "JSON string of template variables"
        },
        "output_path": {
          "type": "string",
          "description": "Path for rendered output file"
        }
      },
      "required": [
        "template_path",
        "variables",
        "output_path"
      ]
    }
  },
  "explanation": "Python action that renders a nginx configuration file from a template with variable substitution."
}

