{
  "fields": {
    "name": "Transform CSV to JSON",
    "action_type": "PYTHON",
    "code": "import csv\nimport json\nimport sys\n\ncsv_path = \"{{input.csv_path}}\"\njson_path = \"{{input.json_path}}\"\ndelimiter = \"{{input.delimiter}}\" or \",\"\n\ntry:\n    records = []\n    with open(csv_path, \"r\", newline=\"\") as f:\n        reader = csv.DictReader(f, delimiter=delimiter)\n        for row in reader:\n            records.append(dict(row))\n\n    with open(json_path, \"w\") as f:\n        json.dump(records, f, indent=2)\n\n    print(json.dumps({{\"status\": \"converted\", \"records\": len(records), \"output\": json_path}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "csv_path": {
          "type": "string",
          "description": "Path to input CSV file"
        },
        "json_path": {
          "type": "string",
          "description": "Path for output JSON file"
        },
        "delimiter": {
          "type": "string",
          "description": "CSV delimiter (default comma)"
        }
      },
      "required": [
        "csv_path",
        "json_path"
      ]
    }
  },
  "explanation": "Python action that reads a hosts CSV file and converts it to JSON format."
