{
  "fields": {
    "name": "Time postgres query execution",
    "action_type": "PYTHON",
    "code": "import json
import sqlite3
import time
import sys

db_path = "{{input.db_path}}"
query = "{{input.query}}" or "SELECT 1"
iterations = int("{{input.iterations}}" or "10")

try:
    conn = sqlite3.connect(db_path)
    timings = []
    for i in range(iterations):
        start = time.time()
        conn.execute(query).fetchall()
        elapsed = (time.time() - start) * 1000
        timings.append(round(elapsed, 3))
    conn.close()
    avg = round(sum(timings) / len(timings), 3)
    print(json.dumps({{
        "status": "ok",
        "iterations": iterations,
        "avg_ms": avg,
        "min_ms": min(timings),
        "max_ms": max(timings),
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "db_path": {
          "type": "string",
          "description": "Path to SQLite database file"
        },
        "query": {
          "type": "string",
          "description": "SQL query to benchmark (default SELECT 1)"
        },
        "iterations": {
          "type": "string",
          "description": "Number of iterations (default 10)"
        }
      },
      "required": [
        "db_path"
      ]
    }
  },
  "explanation": "Python action that benchmarks postgres query execution time over multiple iterations and reports min/avg/max latency."
}

{
  "fields": {
    "name": "Check system uptime",
    "action_type": "PYTHON",
    "code": "import json
import sys

min_uptime_hours = float("{{input.min_uptime_hours}}" or "0")

with open("/proc/uptime", "r") as f:
    uptime_seconds = float(f.read().split()[0])

days = int(uptime_seconds // 86400)
hours = int((uptime_seconds % 86400) // 3600)
minutes = int((uptime_seconds % 3600) // 60)
uptime_hours = uptime_seconds / 3600.0

result = {{
    "uptime_seconds": round(uptime_seconds, 1),
    "uptime_human": f"{{days}}d {{hours}}h {{minutes}}m",
    "days": days,
    "hours": hours,
    "minutes": minutes,
    "status": "ok" if uptime_hours >= min_uptime_hours else "recently_rebooted",
}}
print(json.dumps(result))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "min_uptime_hours": {
          "type": "string",
          "description": "Minimum expected uptime in hours (default 0)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that reads /proc/uptime and reports system uptime in human-readable format for incident monitoring."
}

