{
  "fields": {
    "name": "Test Redis connection",
    "action_type": "PYTHON",
    "code": "import json
import socket
import sys

host = "{{input.host}}" or "localhost"
port = int("{{input.port}}" or "6379")
password = "{{input.password}}" or ""
timeout = int("{{input.timeout}}" or "5")

try:
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    sock.connect((host, port))
    if password:
        sock.sendall(f"AUTH {{password}}\r\n".encode())
        auth_resp = sock.recv(1024).decode()
        if not auth_resp.startswith("+OK"):
            print(json.dumps({{"status": "auth_failed", "message": auth_resp.strip()}}))
            sys.exit(1)
    sock.sendall(b"PING\r\n")
    resp = sock.recv(1024).decode().strip()
    sock.close()
    if "PONG" in resp:
        print(json.dumps({{"status": "ok", "host": host, "port": port, "response": "PONG"}}))
    else:
        print(json.dumps({{"status": "error", "response": resp}}))
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "Redis host (default localhost)"
        },
        "port": {
          "type": "string",
          "description": "Redis port (default 6379)"
        },
        "password": {
          "type": "string",
          "description": "Redis password (optional)"
        },
        "timeout": {
          "type": "string",
          "description": "Connection timeout in seconds (default 5)"
        }
      },
      "required": []
    }
  },
  "explanation": "Python action that tests cache Redis connectivity by sending a PING command via raw socket protocol."
}

