{
  "fields": {
    "name": "Rollback sshd config",
    "action_type": "PYTHON",
    "code": "import json
import os
import shutil
import sys

config_path = "{{input.config_path}}"
backup_dir = "{{input.backup_dir}}" or "/tmp/config_backups"
version = "{{input.version}}" or "latest"

filename = os.path.basename(config_path)
backups = sorted(
    [f for f in os.listdir(backup_dir) if f.startswith(filename) and f.endswith(".bak")],
    reverse=True,
)

if not backups:
    print(json.dumps({{"status": "error", "message": "No backups found"}}))
    sys.exit(1)

if version == "latest":
    restore_file = backups[0]
else:
    restore_file = next((b for b in backups if version in b), None)
    if not restore_file:
        print(json.dumps({{"status": "error", "message": f"Backup version {{version}} not found"}}))
        sys.exit(1)

restore_path = os.path.join(backup_dir, restore_file)
shutil.copy2(restore_path, config_path)

print(json.dumps({{
    "status": "rolled_back",
    "config": config_path,
    "restored_from": restore_file,
    "size_bytes": os.path.getsize(config_path),
}}))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "config_path": {
          "type": "string",
          "description": "Path to config file to restore"
        },
        "backup_dir": {
          "type": "string",
          "description": "Directory containing backups"
        },
        "version": {
          "type": "string",
          "description": "Backup version to restore (default latest)"
        }
      },
      "required": [
        "config_path"
      ]
    }
  },
  "explanation": "Python action that rolls back the sshd configuration by restoring from a backup version."
}

