{
  "fields": {
    "name": "Regex extraction from file",
    "action_type": "PYTHON",
    "code": "import re
import json
import sys

file_path = "{{input.file_path}}"
pattern = "{{input.pattern}}"
group = int("{{input.group}}" or "0")

try:
    with open(file_path, "r") as f:
        content = f.read()

    matches = re.findall(pattern, content)
    if not matches:
        print(json.dumps({{"status": "no_match", "pattern": pattern}}))
        sys.exit(0)

    # If pattern has groups, flatten tuples
    if matches and isinstance(matches[0], tuple):
        extracted = [m[group] if group < len(m) else m[0] for m in matches]
    else:
        extracted = matches

    print(json.dumps({{
        "status": "ok",
        "count": len(extracted),
        "matches": extracted[:100],
    }}))
except re.error as e:
    print(json.dumps({{"status": "error", "message": f"Invalid regex: {{e}}"}}))
    sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "file_path": {
          "type": "string",
          "description": "Path to file to search"
        },
        "pattern": {
          "type": "string",
          "description": "Regular expression pattern"
        },
        "group": {
          "type": "string",
          "description": "Capture group index (default 0)"
        }
      },
      "required": [
        "file_path",
        "pattern"
      ]
    }
  },
  "explanation": "Python action that applies a regular expression to extract matching data from reports files."
}

